window.TXB=window.TXB||{};TXB["svd/Gen"]={"1:1":"في البدء خلق الله السماوات والأرض.","1:2":"وكانت الأرض خربة وخالية, وعلى وجه الغمر ظلمة, وروح الله يرف على وجه المياه.","1:3":"وقال الله: «ليكن نور», فكان نور.","1:4":"ورأى الله النور أنه حسن. وفصل الله بين النور والظلمة.","1:5":"ودعا الله النور نهارا, والظلمة دعاها ليلا. وكان مساء وكان صباح يوما واحدا.","1:6":"وقال الله: «ليكن جلد في وسط المياه. وليكن فاصلا بين مياه ومياه».","1:7":"فعمل الله الجلد, وفصل بين المياه التي تحت الجلد والمياه التي فوق الجلد. وكان كذلك.","1:8":"ودعا الله الجلد سماء. وكان مساء وكان صباح يوما ثانيا.","1:9":"وقال الله: «لتجتمع المياه تحت السماء إلى مكان واحد, ولتظهر اليابسة». وكان كذلك.","1:10":"ودعا الله اليابسة أرضا, ومجتمع المياه دعاه بحارا. ورأى الله ذلك أنه حسن.","1:11":"وقال الله: «لتنبت الأرض عشبا وبقلا يبزر بزرا, وشجرا ذا ثمر يعمل ثمرا كجنسه, بزره فيه على الأرض». وكان كذلك.","1:12":"فأخرجت الأرض عشبا وبقلا يبزر بزرا كجنسه, وشجرا يعمل ثمرا بزره فيه كجنسه. ورأى الله ذلك أنه حسن.","1:13":"وكان مساء وكان صباح يوما ثالثا.","1:14":"وقال الله: «لتكن أنوار في جلد السماء لتفصل بين النهار والليل, وتكون لآيات وأوقات وأيام وسنين.","1:15":"وتكون أنوارا في جلد السماء لتنير على الأرض». وكان كذلك.","1:16":"فعمل الله النورين العظيمين: النور الأكبر لحكم النهار, والنور الأصغر لحكم الليل, والنجوم.","1:17":"وجعلها الله في جلد السماء لتنير على الأرض,","1:18":"ولتحكم على النهار والليل, ولتفصل بين النور والظلمة. ورأى الله ذلك أنه حسن.","1:19":"وكان مساء وكان صباح يوما رابعا.","1:20":"وقال الله: «لتفض المياه زحافات ذات نفس حية, وليطر طير فوق الأرض على وجه جلد السماء».","1:21":"فخلق الله التنانين العظام, وكل ذوات الأنفس الحية الدبابة التي فاضت بها المياه كأجناسها, وكل طائر ذي جناح كجنسه. ورأى الله ذلك أنه حسن.","1:22":"وباركها الله قائلا: «أثمري واكثري واملإي المياه في البحار. وليكثر الطير على الأرض».","1:23":"وكان مساء وكان صباح يوما خامسا.","1:24":"وقال الله: «لتخرج الأرض ذوات أنفس حية كجنسها: بهائم, ودبابات, ووحوش أرض كأجناسها». وكان كذلك.","1:25":"فعمل الله وحوش الأرض كأجناسها, والبهائم كأجناسها, وجميع دبابات الأرض كأجناسها. ورأى الله ذلك أنه حسن.","1:26":"وقال الله: «نعمل الإنسان على صورتنا كشبهنا, فيتسلطون على سمك البحر وعلى طير السماء وعلى البهائم, وعلى كل الأرض, وعلى جميع الدبابات التي تدب على الأرض».","1:27":"فخلق الله الإنسان على صورته. على صورة الله خلقه. ذكرا وأنثى خلقهم.","1:28":"وباركهم الله وقال لهم: «أثمروا واكثروا واملأوا الأرض, وأخضعوها, وتسلطوا على سمك البحر وعلى طير السماء وعلى كل حيوان يدب على الأرض».","1:29":"وقال الله: «إني قد أعطيتكم كل بقل يبزر بزرا على وجه كل الأرض, وكل شجر فيه ثمر شجر يبزر بزرا لكم يكون طعاما.","1:30":"ولكل حيوان الأرض وكل طير السماء وكل دبابة على الأرض فيها نفس حية, أعطيت كل عشب أخضر طعاما». وكان كذلك.","1:31":"ورأى الله كل ما عمله فإذا هو حسن جدا. وكان مساء وكان صباح يوما سادسا.","2:1":"فأكملت السماوات والأرض وكل جندها.","2:2":"وفرغ الله في اليوم السابع من عمله الذي عمل. فاستراح في اليوم السابع من جميع عمله الذي عمل.","2:3":"وبارك الله اليوم السابع وقدسه, لأنه فيه استراح من جميع عمله الذي عمل الله خالقا.","2:4":"هذه مبادئ السماوات والأرض حين خلقت, يوم عمل الرب الإله الأرض والسماوات.","2:5":"كل شجر البرية لم يكن بعد في الأرض, وكل عشب البرية لم ينبت بعد, لأن الرب الإله لم يكن قد أمطر على الأرض, ولا كان إنسان ليعمل الأرض.","2:6":"ثم كان ضباب يطلع من الأرض ويسقي كل وجه الأرض.","2:7":"وجبل الرب الإله آدم ترابا من الأرض, ونفخ في أنفه نسمة حياة. فصار آدم نفسا حية.","2:8":"وغرس الرب الإله جنة في عدن شرقا, ووضع هناك آدم الذي جبله.","2:9":"وأنبت الرب الإله من الأرض كل شجرة شهية للنظر وجيدة للأكل, وشجرة الحياة في وسط الجنة, وشجرة معرفة الخير والشر.","2:10":"وكان نهر يخرج من عدن ليسقي الجنة, ومن هناك ينقسم فيصير أربعة رؤوس:","2:11":"اسم الواحد فيشون, وهو المحيط بجميع أرض الحويلة حيث الذهب.","2:12":"وذهب تلك الأرض جيد. هناك المقل وحجر الجزع.","2:13":"واسم النهر الثاني جيحون, وهو المحيط بجميع أرض كوش.","2:14":"واسم النهر الثالث حداقل, وهو الجاري شرقي أشور. والنهر الرابع الفرات.","2:15":"وأخذ الرب الإله آدم ووضعه في جنة عدن ليعملها ويحفظها.","2:16":"وأوصى الرب الإله آدم قائلا: «من جميع شجر الجنة تأكل أكلا,","2:17":"وأما شجرة معرفة الخير والشر فلا تأكل منها, لأنك يوم تأكل منها موتا تموت».","2:18":"وقال الرب الإله: «ليس جيدا أن يكون آدم وحده, فأصنع له معينا نظيره».","2:19":"وجبل الرب الإله من الأرض كل حيوانات البرية وكل طيور السماء, فأحضرها إلى آدم ليرى ماذا يدعوها, وكل ما دعا به آدم ذات نفس حية فهو اسمها.","2:20":"فدعا آدم بأسماء جميع البهائم وطيور السماء وجميع حيوانات البرية. وأما لنفسه فلم يجد معينا نظيره.","2:21":"فأوقع الرب الإله سباتا على آدم فنام, فأخذ واحدة من أضلاعه وملأ مكانها لحما.","2:22":"وبنى الرب الإله الضلع التي أخذها من آدم امرأة وأحضرها إلى آدم.","2:23":"فقال آدم: «هذه الآن عظم من عظامي ولحم من لحمي. هذه تدعى امرأة لأنها من امرء أخذت».","2:24":"لذلك يترك الرجل أباه وأمه ويلتصق بامرأته ويكونان جسدا واحدا.","2:25":"وكانا كلاهما عريانين, آدم وامرأته, وهما لا يخجلان.","3:1":"وكانت الحية أحيل جميع حيوانات البرية التي عملها الرب الإله, فقالت للمرأة: «أحقا قال الله لا تأكلا من كل شجر الجنة؟»","3:2":"فقالت المرأة للحية: «من ثمر شجر الجنة نأكل,","3:3":"وأما ثمر الشجرة التي في وسط الجنة فقال الله: لا تأكلا منه ولا تمساه لئلا تموتا».","3:4":"فقالت الحية للمرأة: «لن تموتا!","3:5":"بل الله عالم أنه يوم تأكلان منه تنفتح أعينكما وتكونان كالله عارفين الخير والشر».","3:6":"فرأت المرأة أن الشجرة جيدة للأكل, وأنها بهجة للعيون, وأن الشجرة شهية للنظر. فأخذت من ثمرها وأكلت, وأعطت رجلها أيضا معها فأكل.","3:7":"فانفتحت أعينهما وعلما أنهما عريانان. فخاطا أوراق تين وصنعا لأنفسهما مآزر.","3:8":"وسمعا صوت الرب الإله ماشيا في الجنة عند هبوب ريح النهار, فاختبأ آدم وامرأته من وجه الرب الإله في وسط شجر الجنة.","3:9":"فنادى الرب الإله آدم وقال له: «أين أنت؟».","3:10":"فقال: «سمعت صوتك في الجنة فخشيت, لأني عريان فاختبأت».","3:11":"فقال: «من أعلمك أنك عريان؟ هل أكلت من الشجرة التي أوصيتك أن لا تأكل منها؟»","3:12":"فقال آدم: «المرأة التي جعلتها معي هي أعطتني من الشجرة فأكلت».","3:13":"فقال الرب الإله للمرأة: «ما هذا الذي فعلت؟» فقالت المرأة: «الحية غرتني فأكلت».","3:14":"فقال الرب الإله للحية: «لأنك فعلت هذا, ملعونة أنت من جميع البهائم ومن جميع وحوش البرية. على بطنك تسعين وترابا تأكلين كل أيام حياتك.","3:15":"وأضع عداوة بينك وبين المرأة, وبين نسلك ونسلها. هو يسحق رأسك, وأنت تسحقين عقبه».","3:16":"وقال للمرأة: «تكثيرا أكثر أتعاب حبلك, بالوجع تلدين أولادا. وإلى رجلك يكون اشتياقك وهو يسود عليك».","3:17":"وقال لآدم: «لأنك سمعت لقول امرأتك وأكلت من الشجرة التي أوصيتك قائلا: لا تأكل منها, ملعونة الأرض بسببك. بالتعب تأكل منها كل أيام حياتك.","3:18":"وشوكا وحسكا تنبت لك, وتأكل عشب الحقل.","3:19":"بعرق وجهك تأكل خبزا حتى تعود إلى الأرض التي أخذت منها. لأنك تراب, وإلى تراب تعود».","3:20":"ودعا آدم اسم امرأته «حواء» لأنها أم كل حي.","3:21":"وصنع الرب الإله لآدم وامرأته أقمصة من جلد وألبسهما.","3:22":"وقال الرب الإله: «هوذا الإنسان قد صار كواحد منا عارفا الخير والشر. والآن لعله يمد يده ويأخذ من شجرة الحياة أيضا ويأكل ويحيا إلى الأبد».","3:23":"فأخرجه الرب الإله من جنة عدن ليعمل الأرض التي أخذ منها.","3:24":"فطرد الإنسان, وأقام شرقي جنة عدن الكروبيم, ولهيب سيف متقلب لحراسة طريق شجرة الحياة.","4:1":"وعرف آدم حواء امرأته فحبلت وولدت قايين. وقالت: «اقتنيت رجلا من عند الرب».","4:2":"ثم عادت فولدت أخاه هابيل. وكان هابيل راعيا للغنم, وكان قايين عاملا في الأرض.","4:3":"وحدث من بعد أيام أن قايين قدم من أثمار الأرض قربانا للرب,","4:4":"وقدم هابيل أيضا من أبكار غنمه ومن سمانها. فنظر الرب إلى هابيل وقربانه,","4:5":"ولكن إلى قايين وقربانه لم ينظر. فاغتاظ قايين جدا وسقط وجهه.","4:6":"فقال الرب لقايين: «لماذا اغتظت؟ ولماذا سقط وجهك؟","4:7":"إن أحسنت أفلا رفع؟ وإن لم تحسن فعند الباب خطية رابضة, وإليك اشتياقها وأنت تسود عليها».","4:8":"وكلم قايين هابيل أخاه. وحدث إذ كانا في الحقل أن قايين قام على هابيل أخيه وقتله.","4:9":"فقال الرب لقايين: «أين هابيل أخوك؟» فقال: «لا أعلم! أحارس أنا لأخي؟»","4:10":"فقال: «ماذا فعلت؟ صوت دم أخيك صارخ إلي من الأرض.","4:11":"فالآن ملعون أنت من الأرض التي فتحت فاها لتقبل دم أخيك من يدك.","4:12":"متى عملت الأرض لا تعود تعطيك قوتها. تائها وهاربا تكون في الأرض».","4:13":"فقال قايين للرب: «ذنبي أعظم من أن يحتمل.","4:14":"إنك قد طردتني اليوم عن وجه الأرض, ومن وجهك أختفي وأكون تائها وهاربا في الأرض, فيكون كل من وجدني يقتلني».","4:15":"فقال له الرب: «لذلك كل من قتل قايين فسبعة أضعاف ينتقم منه». وجعل الرب لقايين علامة لكي لا يقتله كل من وجده.","4:16":"فخرج قايين من لدن الرب, وسكن في أرض نود شرقي عدن.","4:17":"وعرف قايين امرأته فحبلت وولدت حنوك. وكان يبني مدينة, فدعا اسم المدينة كاسم ابنه حنوك.","4:18":"وولد لحنوك عيراد. وعيراد ولد محويائيل. ومحويائيل ولد متوشائيل. ومتوشائيل ولد لامك.","4:19":"واتخذ لامك لنفسه امرأتين: اسم الواحدة عادة, واسم الأخرى صلة.","4:20":"فولدت عادة يابال الذي كان أبا لساكني الخيام ورعاة المواشي.","4:21":"واسم أخيه يوبال الذي كان أبا لكل ضارب بالعود والمزمار.","4:22":"وصلة أيضا ولدت توبال قايين الضارب كل آلة من نحاس وحديد. وأخت توبال قايين نعمة.","4:23":"وقال لامك لامرأتيه عادة وصلة: «اسمعا قولي يا امرأتي لامك, وأصغيا لكلامي. فإني قتلت رجلا لجرحي, وفتى لشدخي.","4:24":"إنه ينتقم لقايين سبعة أضعاف, وأما للامك فسبعة وسبعين».","4:25":"وعرف آدم امرأته أيضا, فولدت ابنا ودعت اسمه شيثا, قائلة: «لأن الله قد وضع لي نسلا آخر عوضا عن هابيل». لأن قايين كان قد قتله.","4:26":"ولشيث أيضا ولد ابن فدعا اسمه أنوش. حينئذ ابتدئ أن يدعى باسم الرب.","5:1":"هذا كتاب مواليد آدم, يوم خلق الله الإنسان. على شبه الله عمله.","5:2":"ذكرا وأنثى خلقه, وباركه ودعا اسمه آدم يوم خلق.","5:3":"وعاش آدم مئة وثلاثين سنة, وولد ولدا على شبهه كصورته ودعا اسمه شيثا.","5:4":"وكانت أيام آدم بعد ما ولد شيثا ثماني مئة سنة, وولد بنين وبنات.","5:5":"فكانت كل أيام آدم التي عاشها تسع مئة وثلاثين سنة, ومات.","5:6":"وعاش شيث مئة وخمس سنين, وولد أنوش.","5:7":"وعاش شيث بعد ما ولد أنوش ثماني مئة وسبع سنين, وولد بنين وبنات.","5:8":"فكانت كل أيام شيث تسع مئة واثنتي عشرة سنة, ومات.","5:9":"وعاش أنوش تسعين سنة, وولد قينان.","5:10":"وعاش أنوش بعد ما ولد قينان ثماني مئة وخمس عشرة سنة, وولد بنين وبنات.","5:11":"فكانت كل أيام أنوش تسع مئة وخمس سنين, ومات.","5:12":"وعاش قينان سبعين سنة, وولد مهللئيل.","5:13":"وعاش قينان بعد ما ولد مهللئيل ثماني مئة وأربعين سنة, وولد بنين وبنات.","5:14":"فكانت كل أيام قينان تسع مئة وعشر سنين, ومات.","5:15":"وعاش مهللئيل خمسا وستين سنة, وولد يارد.","5:16":"وعاش مهللئيل بعد ما ولد يارد ثماني مئة وثلاثين سنة, وولد بنين وبنات.","5:17":"فكانت كل أيام مهللئيل ثماني مئة وخمسا وتسعين سنة, ومات.","5:18":"وعاش يارد مئة واثنتين وستين سنة, وولد أخنوخ.","5:19":"وعاش يارد بعد ما ولد أخنوخ ثماني مئة سنة, وولد بنين وبنات.","5:20":"فكانت كل أيام يارد تسع مئة واثنتين وستين سنة, ومات.","5:21":"وعاش أخنوخ خمسا وستين سنة, وولد متوشالح.","5:22":"وسار أخنوخ مع الله بعد ما ولد متوشالح ثلاث مئة سنة, وولد بنين وبنات.","5:23":"فكانت كل أيام أخنوخ ثلاث مئة وخمسا وستين سنة.","5:24":"وسار أخنوخ مع الله, ولم يوجد لأن الله أخذه.","5:25":"وعاش متوشالح مئة وسبعا وثمانين سنة, وولد لامك.","5:26":"وعاش متوشالح بعد ما ولد لامك سبع مئة واثنتين وثمانين سنة, وولد بنين وبنات.","5:27":"فكانت كل أيام متوشالح تسع مئة وتسعا وستين سنة, ومات.","5:28":"وعاش لامك مئة واثنتين وثمانين سنة, وولد ابنا.","5:29":"ودعا اسمه نوحا, قائلا: «هذا يعزينا عن عملنا وتعب أيدينا من قبل الأرض التي لعنها الرب».","5:30":"وعاش لامك بعد ما ولد نوحا خمس مئة وخمسا وتسعين سنة, وولد بنين وبنات.","5:31":"فكانت كل أيام لامك سبع مئة وسبعا وسبعين سنة, ومات.","5:32":"وكان نوح ابن خمس مئة سنة. وولد نوح: ساما, وحاما, ويافث.","6:1":"وحدث لما ابتدأ الناس يكثرون على الأرض, وولد لهم بنات,","6:2":"أن أبناء الله رأوا بنات الناس أنهن حسنات. فاتخذوا لأنفسهم نساء من كل ما اختاروا.","6:3":"فقال الرب: «لا يدين روحي في الإنسان إلى الأبد, لزيغانه, هو بشر. وتكون أيامه مئة وعشرين سنة».","6:4":"كان في الأرض طغاة في تلك الأيام. وبعد ذلك أيضا إذ دخل بنو الله على بنات الناس وولدن لهم أولادا, هؤلاء هم الجبابرة الذين منذ الدهر ذوو اسم.","6:5":"ورأى الرب أن شر الإنسان قد كثر في الأرض, وأن كل تصور أفكار قلبه إنما هو شرير كل يوم.","6:6":"فحزن الرب أنه عمل الإنسان في الأرض, وتأسف في قلبه.","6:7":"فقال الرب: «أمحو عن وجه الأرض الإنسان الذي خلقته, الإنسان مع بهائم ودبابات وطيور السماء, لأني حزنت أني عملتهم».","6:8":"وأما نوح فوجد نعمة في عيني الرب.","6:9":"هذه مواليد نوح: كان نوح رجلا بارا كاملا في أجياله. وسار نوح مع الله.","6:10":"وولد نوح ثلاثة بنين: ساما, وحاما, ويافث.","6:11":"وفسدت الأرض أمام الله, وامتلأت الأرض ظلما.","6:12":"ورأى الله الأرض فإذا هي قد فسدت, إذ كان كل بشر قد أفسد طريقه على الأرض.","6:13":"فقال الله لنوح: «نهاية كل بشر قد أتت أمامي, لأن الأرض امتلأت ظلما منهم. فها أنا مهلكهم مع الأرض.","6:14":"اصنع لنفسك فلكا من خشب جفر. تجعل الفلك مساكن, وتطليه من داخل ومن خارج بالقار.","6:15":"وهكذا تصنعه: ثلاث مئة ذراع يكون طول الفلك, وخمسين ذراعا عرضه, وثلاثين ذراعا ارتفاعه.","6:16":"وتصنع كوا للفلك, وتكمله إلى حد ذراع من فوق. وتضع باب الفلك في جانبه. مساكن سفلية ومتوسطة وعلوية تجعله.","6:17":"فها أنا آت بطوفان الماء على الأرض لأهلك كل جسد فيه روح حياة من تحت السماء. كل ما في الأرض يموت.","6:18":"ولكن أقيم عهدي معك, فتدخل الفلك أنت وبنوك وامرأتك ونساء بنيك معك.","6:19":"ومن كل حي من كل ذي جسد, اثنين من كل تدخل إلى الفلك لاستبقائها معك. تكون ذكرا وأنثى.","6:20":"من الطيور كأجناسها, ومن البهائم كأجناسها, ومن كل دبابات الأرض كأجناسها. اثنين من كل تدخل إليك لاستبقائها.","6:21":"وأنت, فخذ لنفسك من كل طعام يؤكل واجمعه عندك, فيكون لك ولها طعاما».","6:22":"ففعل نوح حسب كل ما أمره به الله. هكذا فعل.","7:1":"وقال الرب لنوح: «ادخل أنت وجميع بيتك إلى الفلك, لأني إياك رأيت بارا لدي في هذا الجيل.","7:2":"من جميع البهائم الطاهرة تأخذ معك سبعة سبعة ذكرا وأنثى. ومن البهائم التي ليست بطاهرة اثنين: ذكرا وأنثى.","7:3":"ومن طيور السماء أيضا سبعة سبعة: ذكرا وأنثى. لاستبقاء نسل على وجه كل الأرض.","7:4":"لأني بعد سبعة أيام أيضا أمطر على الأرض أربعين يوما وأربعين ليلة. وأمحو عن وجه الأرض كل قائم عملته».","7:5":"ففعل نوح حسب كل ما أمره به الرب.","7:6":"ولما كان نوح ابن ست مئة سنة صار طوفان الماء على الأرض,","7:7":"فدخل نوح وبنوه وامرأته ونساء بنيه معه إلى الفلك من وجه مياه الطوفان.","7:8":"ومن البهائم الطاهرة والبهائم التي ليست بطاهرة, ومن الطيور وكل ما يدب على الأرض:","7:9":"دخل اثنان اثنان إلى نوح إلى الفلك, ذكرا وأنثى, كما أمر الله نوحا.","7:10":"وحدث بعد السبعة الأيام أن مياه الطوفان صارت على الأرض.","7:11":"في سنة ست مئة من حياة نوح, في الشهر الثاني, في اليوم السابع عشر من الشهر في ذلك اليوم, انفجرت كل ينابيع الغمر العظيم, وانفتحت طاقات السماء.","7:12":"وكان المطر على الأرض أربعين يوما وأربعين ليلة.","7:13":"في ذلك اليوم عينه دخل نوح, وسام وحام ويافث بنو نوح, وامرأة نوح, وثلاث نساء بنيه معهم إلى الفلك.","7:14":"هم وكل الوحوش كأجناسها, وكل البهائم كأجناسها, وكل الدبابات التي تدب على الأرض كأجناسها, وكل الطيور كأجناسها: كل عصفور, كل ذي جناح.","7:15":"ودخلت إلى نوح إلى الفلك, اثنين اثنين من كل جسد فيه روح حياة.","7:16":"والداخلات دخلت ذكرا وأنثى, من كل ذي جسد, كما أمره الله. وأغلق الرب عليه.","7:17":"وكان الطوفان أربعين يوما على الأرض. وتكاثرت المياه ورفعت الفلك, فارتفع عن الأرض.","7:18":"وتعاظمت المياه وتكاثرت جدا على الأرض, فكان الفلك يسير على وجه المياه.","7:19":"وتعاظمت المياه كثيرا جدا على الأرض, فتغطت جميع الجبال الشامخة التي تحت كل السماء.","7:20":"خمس عشرة ذراعا في الارتفاع تعاظمت المياه, فتغطت الجبال.","7:21":"فمات كل ذي جسد كان يدب على الأرض من الطيور والبهائم والوحوش, وكل الزحافات التي كانت تزحف على الأرض, وجميع الناس.","7:22":"كل ما في أنفه نسمة روح حياة من كل ما في اليابسة مات.","7:23":"فمحا الله كل قائم كان على وجه الأرض: الناس, والبهائم, والدبابات, وطيور السماء. فانمحت من الأرض. وتبقى نوح والذين معه في الفلك فقط.","7:24":"وتعاظمت المياه على الأرض مئة وخمسين يوما.","8:1":"ثم ذكر الله نوحا وكل الوحوش وكل البهائم التي معه في الفلك. وأجاز الله ريحا على الأرض فهدأت المياه.","8:2":"وانسدت ينابيع الغمر وطاقات السماء, فامتنع المطر من السماء.","8:3":"ورجعت المياه عن الأرض رجوعا متواليا. وبعد مئة وخمسين يوما نقصت المياه,","8:4":"واستقر الفلك في الشهر السابع, في اليوم السابع عشر من الشهر, على جبال أراراط.","8:5":"وكانت المياه تنقص نقصا متواليا إلى الشهر العاشر. وفي العاشر في أول الشهر, ظهرت رؤوس الجبال.","8:6":"وحدث من بعد أربعين يوما أن نوحا فتح طاقة الفلك التي كان قد عملها","8:7":"وأرسل الغراب, فخرج مترددا حتى نشفت المياه عن الأرض.","8:8":"ثم أرسل الحمامة من عنده ليرى هل قلت المياه عن وجه الأرض,","8:9":"فلم تجد الحمامة مقرا لرجلها, فرجعت إليه إلى الفلك لأن مياها كانت على وجه كل الأرض. فمد يده وأخذها وأدخلها عنده إلى الفلك.","8:10":"فلبث أيضا سبعة أيام أخر وعاد فأرسل الحمامة من الفلك,","8:11":"فأتت إليه الحمامة عند المساء, وإذا ورقة زيتون خضراء في فمها. فعلم نوح أن المياه قد قلت عن الأرض.","8:12":"فلبث أيضا سبعة أيام أخر وأرسل الحمامة فلم تعد ترجع إليه أيضا.","8:13":"وكان في السنة الواحدة والست مئة, في الشهر الأول في أول الشهر, أن المياه نشفت عن الأرض. فكشف نوح الغطاء عن الفلك ونظر, فإذا وجه الأرض قد نشف.","8:14":"وفي الشهر الثاني, في اليوم السابع والعشرين من الشهر, جفت الأرض.","8:15":"وكلم الله نوحا قائلا:","8:16":"«اخرج من الفلك أنت وامرأتك وبنوك ونساء بنيك معك.","8:17":"وكل الحيوانات التي معك من كل ذي جسد: الطيور, والبهائم, وكل الدبابات التي تدب على الأرض, أخرجها معك. ولتتوالد في الأرض وتثمر وتكثر على الأرض».","8:18":"فخرج نوح وبنوه وامرأته ونساء بنيه معه.","8:19":"وكل الحيوانات, كل الدبابات, وكل الطيور, كل ما يدب على الأرض, كأنواعها خرجت من الفلك.","8:20":"وبنى نوح مذبحا للرب. وأخذ من كل البهائم الطاهرة ومن كل الطيور الطاهرة وأصعد محرقات على المذبح,","8:21":"فتنسم الرب رائحة الرضا. وقال الرب في قلبه: «لا أعود ألعن الأرض أيضا من أجل الإنسان, لأن تصور قلب الإنسان شرير منذ حداثته. ولا أعود أيضا أميت كل حي كما فعلت.","8:22":"مدة كل أيام الأرض: زرع وحصاد, وبرد وحر, وصيف وشتاء, ونهار وليل, لا تزال».","9:1":"وبارك الله نوحا وبنيه وقال لهم: «أثمروا واكثروا واملأوا الأرض.","9:2":"ولتكن خشيتكم ورهبتكم على كل حيوانات الأرض وكل طيور السماء, مع كل ما يدب على الأرض, وكل أسماك البحر. قد دفعت إلى أيديكم.","9:3":"كل دابة حية تكون لكم طعاما. كالعشب الأخضر دفعت إليكم الجميع.","9:4":"غير أن لحما بحياته, دمه, لا تأكلوه.","9:5":"وأطلب أنا دمكم لأنفسكم فقط. من يد كل حيوان أطلبه. ومن يد الإنسان أطلب نفس الإنسان, من يد الإنسان أخيه.","9:6":"سافك دم الإنسان بالإنسان يسفك دمه. لأن الله على صورته عمل الإنسان.","9:7":"فأثمروا أنتم واكثروا وتوالدوا في الأرض وتكاثروا فيها».","9:8":"وكلم الله نوحا وبنيه معه قائلا:","9:9":"«وها أنا مقيم ميثاقي معكم ومع نسلكم من بعدكم,","9:10":"ومع كل ذوات الأنفس الحية التي معكم: الطيور والبهائم وكل وحوش الأرض التي معكم, من جميع الخارجين من الفلك حتى كل حيوان الأرض.","9:11":"أقيم ميثاقي معكم فلا ينقرض كل ذي جسد أيضا بمياه الطوفان. ولا يكون أيضا طوفان ليخرب الأرض».","9:12":"وقال الله: «هذه علامة الميثاق الذي أنا واضعه بيني وبينكم, وبين كل ذوات الأنفس الحية التي معكم إلى أجيال الدهر:","9:13":"وضعت قوسي في السحاب فتكون علامة ميثاق بيني وبين الأرض.","9:14":"فيكون متى أنشر سحابا على الأرض, وتظهر القوس في السحاب,","9:15":"أني أذكر ميثاقي الذي بيني وبينكم وبين كل نفس حية في كل جسد. فلا تكون أيضا المياه طوفانا لتهلك كل ذي جسد.","9:16":"فمتى كانت القوس في السحاب, أبصرها لأذكر ميثاقا أبديا بين الله وبين كل نفس حية في كل جسد على الأرض».","9:17":"وقال الله لنوح: «هذه علامة الميثاق الذي أنا أقمته بيني وبين كل ذي جسد على الأرض».","9:18":"وكان بنو نوح الذين خرجوا من الفلك ساما وحاما ويافث. وحام هو أبو كنعان.","9:19":"هؤلاء الثلاثة هم بنو نوح. ومن هؤلاء تشعبت كل الأرض.","9:20":"وابتدأ نوح يكون فلاحا وغرس كرما.","9:21":"وشرب من الخمر فسكر وتعرى داخل خبائه.","9:22":"فأبصر حام أبو كنعان عورة أبيه, وأخبر أخويه خارجا.","9:23":"فأخذ سام ويافث الرداء ووضعاه على أكتافهما ومشيا إلى الوراء, وسترا عورة أبيهما ووجهاهما إلى الوراء. فلم يبصرا عورة أبيهما.","9:24":"فلما استيقظ نوح من خمره, علم ما فعل به ابنه الصغير,","9:25":"فقال: «ملعون كنعان! عبد العبيد يكون لإخوته».","9:26":"وقال: «مبارك الرب إله سام. وليكن كنعان عبدا لهم.","9:27":"ليفتح الله ليافث فيسكن في مساكن سام, وليكن كنعان عبدا لهم».","9:28":"وعاش نوح بعد الطوفان ثلاث مئة وخمسين سنة.","9:29":"فكانت كل أيام نوح تسع مئة وخمسين سنة, ومات.","10:1":"وهذه مواليد بني نوح: سام وحام ويافث. وولد لهم بنون بعد الطوفان.","10:2":"بنو يافث: جومر وماجوج وماداي وياوان وتوبال وماشك وتيراس.","10:3":"وبنو جومر: أشكناز وريفاث وتوجرمة.","10:4":"وبنو ياوان: أليشة وترشيش وكتيم ودودانيم.","10:5":"من هؤلاء تفرقت جزائر الأمم بأراضيهم, كل إنسان كلسانه حسب قبائلهم بأممهم.","10:6":"وبنو حام: كوش ومصرايم وفوط وكنعان.","10:7":"وبنو كوش: سبا وحويلة وسبتة ورعمة وسبتكا. وبنو رعمة: شبا وددان.","10:8":"وكوش ولد نمرود الذي ابتدأ يكون جبارا في الأرض,","10:9":"الذي كان جبار صيد أمام الرب. لذلك يقال: «كنمرود جبار صيد أمام الرب».","10:10":"وكان ابتداء مملكته بابل وأرك وأكد وكلنة, في أرض شنعار.","10:11":"من تلك الأرض خرج أشور وبنى نينوى ورحوبوت عير وكالح","10:12":"ورسن, بين نينوى وكالح, هي المدينة الكبيرة.","10:13":"ومصرايم ولد: لوديم وعناميم ولهابيم ونفتوحيم","10:14":"وفتروسيم وكسلوحيم. الذين خرج منهم فلشتيم وكفتوريم.","10:15":"وكنعان ولد: صيدون بكره, وحثا","10:16":"واليبوسي والأموري والجرجاشي","10:17":"والحوي والعرقي والسيني","10:18":"والأروادي والصماري والحماتي. وبعد ذلك تفرقت قبائل الكنعاني.","10:19":"وكانت تخوم الكنعاني من صيدون, حينما تجيء نحو جرار إلى غزة, وحينما تجيء نحو سدوم وعمورة وأدمة وصبوييم إلى لاشع.","10:20":"هؤلاء بنو حام حسب قبائلهم كألسنتهم بأراضيهم وأممهم.","10:21":"وسام أبو كل بني عابر, أخو يافث الكبير, ولد له أيضا بنون.","10:22":"بنو سام: عيلام وأشور وأرفكشاد ولود وأرام.","10:23":"وبنو أرام: عوص وحول وجاثر وماش.","10:24":"وأرفكشاد ولد شالح, وشالح ولد عابر.","10:25":"ولعابر ولد ابنان: اسم الواحد فالج لأن في أيامه قسمت الأرض. واسم أخيه يقطان.","10:26":"ويقطان ولد: ألموداد وشالف وحضرموت ويارح","10:27":"وهدورام وأوزال ودقلة","10:28":"وعوبال وأبيمايل وشبا","10:29":"وأوفير وحويلة ويوباب. جميع هؤلاء بنو يقطان.","10:30":"وكان مسكنهم من ميشا حينما تجيء نحو سفار جبل المشرق.","10:31":"هؤلاء بنو سام حسب قبائلهم كألسنتهم بأراضيهم حسب أممهم.","10:32":"هؤلاء قبائل بني نوح حسب مواليدهم بأممهم. ومن هؤلاء تفرقت الأمم في الأرض بعد الطوفان.","11:1":"وكانت الأرض كلها لسانا واحدا ولغة واحدة.","11:2":"وحدث في ارتحالهم شرقا أنهم وجدوا بقعة في أرض شنعار وسكنوا هناك.","11:3":"وقال بعضهم لبعض: «هلم نصنع لبنا ونشويه شيا». فكان لهم اللبن مكان الحجر, وكان لهم الحمر مكان الطين.","11:4":"وقالوا: «هلم نبن لأنفسنا مدينة وبرجا رأسه بالسماء. ونصنع لأنفسنا اسما لئلا نتبدد على وجه كل الأرض».","11:5":"فنزل الرب لينظر المدينة والبرج اللذين كان بنو آدم يبنونهما.","11:6":"وقال الرب: «هوذا شعب واحد ولسان واحد لجميعهم, وهذا ابتداؤهم بالعمل. والآن لا يمتنع عليهم كل ما ينوون أن يعملوه.","11:7":"هلم ننزل ونبلبل هناك لسانهم حتى لا يسمع بعضهم لسان بعض».","11:8":"فبددهم الرب من هناك على وجه كل الأرض, فكفوا عن بنيان المدينة,","11:9":"لذلك دعي اسمها «بابل» لأن الرب هناك بلبل لسان كل الأرض. ومن هناك بددهم الرب على وجه كل الأرض.","11:10":"هذه مواليد سام: لما كان سام ابن مئة سنة ولد أرفكشاد, بعد الطوفان بسنتين.","11:11":"وعاش سام بعد ما ولد أرفكشاد خمس مئة سنة, وولد بنين وبنات.","11:12":"وعاش أرفكشاد خمسا وثلاثين سنة وولد شالح.","11:13":"وعاش أرفكشاد بعد ما ولد شالح أربع مئة وثلاث سنين, وولد بنين وبنات.","11:14":"وعاش شالح ثلاثين سنة وولد عابر.","11:15":"وعاش شالح بعد ما ولد عابر أربع مئة وثلاث سنين, وولد بنين وبنات.","11:16":"وعاش عابر أربعا وثلاثين سنة وولد فالج.","11:17":"وعاش عابر بعد ما ولد فالج أربع مئة وثلاثين سنة, وولد بنين وبنات.","11:18":"وعاش فالج ثلاثين سنة وولد رعو.","11:19":"وعاش فالج بعد ما ولد رعو مئتين وتسع سنين, وولد بنين وبنات.","11:20":"وعاش رعو اثنتين وثلاثين سنة وولد سروج.","11:21":"وعاش رعو بعد ما ولد سروج مئتين وسبع سنين, وولد بنين وبنات.","11:22":"وعاش سروج ثلاثين سنة وولد ناحور.","11:23":"وعاش سروج بعد ما ولد ناحور مئتي سنة, وولد بنين وبنات.","11:24":"وعاش ناحور تسعا وعشرين سنة وولد تارح.","11:25":"وعاش ناحور بعد ما ولد تارح مئة وتسع عشرة سنة, وولد بنين وبنات.","11:26":"وعاش تارح سبعين سنة, وولد أبرام وناحور وهاران.","11:27":"وهذه مواليد تارح: ولد تارح أبرام وناحور وهاران. وولد هاران لوطا.","11:28":"ومات هاران قبل تارح أبيه في أرض ميلاده في أور الكلدانيين.","11:29":"واتخذ أبرام وناحور لأنفسهما امرأتين: اسم امرأة أبرام ساراي, واسم امرأة ناحور ملكة بنت هاران, أبي ملكة وأبي يسكة.","11:30":"وكانت ساراي عاقرا ليس لها ولد.","11:31":"وأخذ تارح أبرام ابنه, ولوطا بن هاران, ابن ابنه, وساراي كنته امرأة أبرام ابنه, فخرجوا معا من أور الكلدانيين ليذهبوا إلى أرض كنعان. فأتوا إلى حاران وأقاموا هناك.","11:32":"وكانت أيام تارح مئتين وخمس سنين. ومات تارح في حاران.","12:1":"وقال الرب لأبرام: «اذهب من أرضك ومن عشيرتك ومن بيت أبيك إلى الأرض التي أريك.","12:2":"فأجعلك أمة عظيمة وأباركك وأعظم اسمك, وتكون بركة.","12:3":"وأبارك مباركيك, ولاعنك ألعنه. وتتبارك فيك جميع قبائل الأرض».","12:4":"فذهب أبرام كما قال له الرب وذهب معه لوط. وكان أبرام ابن خمس وسبعين سنة لما خرج من حاران.","12:5":"فأخذ أبرام ساراي امرأته, ولوطا ابن أخيه, وكل مقتنياتهما التي اقتنيا والنفوس التي امتلكا في حاران. وخرجوا ليذهبوا إلى أرض كنعان. فأتوا إلى أرض كنعان.","12:6":"واجتاز أبرام في الأرض إلى مكان شكيم إلى بلوطة مورة. وكان الكنعانيون حينئذ في الأرض.","12:7":"وظهر الرب لأبرام وقال: «لنسلك أعطي هذه الأرض». فبنى هناك مذبحا للرب الذي ظهر له.","12:8":"ثم نقل من هناك إلى الجبل شرقي بيت إيل ونصب خيمته. وله بيت إيل من المغرب وعاي من المشرق. فبنى هناك مذبحا للرب ودعا باسم الرب.","12:9":"ثم ارتحل أبرام ارتحالا متواليا نحو الجنوب.","12:10":"وحدث جوع في الأرض, فانحدر أبرام إلى مصر ليتغرب هناك, لأن الجوع في الأرض كان شديدا.","12:11":"وحدث لما قرب أن يدخل مصر أنه قال لساراي امرأته: «إني قد علمت أنك امرأة حسنة المنظر.","12:12":"فيكون إذا رآك المصريون أنهم يقولون: هذه امرأته. فيقتلونني ويستبقونك.","12:13":"قولي إنك أختي, ليكون لي خير بسببك وتحيا نفسي من أجلك».","12:14":"فحدث لما دخل أبرام إلى مصر أن المصريين رأوا المرأة أنها حسنة جدا.","12:15":"ورآها رؤساء فرعون ومدحوها لدى فرعون, فأخذت المرأة إلى بيت فرعون,","12:16":"فصنع إلى أبرام خيرا بسببها, وصار له غنم وبقر وحمير وعبيد وإماء وأتن وجمال.","12:17":"فضرب الرب فرعون وبيته ضربات عظيمة بسبب ساراي امرأة أبرام.","12:18":"فدعا فرعون أبرام وقال: «ما هذا الذي صنعت بي؟ لماذا لم تخبرني أنها امرأتك؟","12:19":"لماذا قلت: هي أختي, حتى أخذتها لي لتكون زوجتي؟ والآن هوذا امرأتك! خذها واذهب!».","12:20":"فأوصى عليه فرعون رجالا فشيعوه وامرأته وكل ما كان له.","13:1":"فصعد أبرام من مصر هو وامرأته وكل ما كان له, ولوط معه إلى الجنوب.","13:2":"وكان أبرام غنيا جدا في المواشي والفضة والذهب.","13:3":"وسار في رحلاته من الجنوب إلى بيت إيل, إلى المكان الذي كانت خيمته فيه في البداءة, بين بيت إيل وعاي,","13:4":"إلى مكان المذبح الذي عمله هناك أولا. ودعا هناك أبرام باسم الرب.","13:5":"ولوط السائر مع أبرام, كان له أيضا غنم وبقر وخيام.","13:6":"ولم تحتملهما الأرض أن يسكنا معا, إذ كانت أملاكهما كثيرة, فلم يقدرا أن يسكنا معا.","13:7":"فحدثت مخاصمة بين رعاة مواشي أبرام ورعاة مواشي لوط. وكان الكنعانيون والفرزيون حينئذ ساكنين في الأرض.","13:8":"فقال أبرام للوط: «لا تكن مخاصمة بيني وبينك, وبين رعاتي ورعاتك, لأننا نحن أخوان.","13:9":"أليست كل الأرض أمامك؟ اعتزل عني. إن ذهبت شمالا فأنا يمينا, وإن يمينا فأنا شمالا».","13:10":"فرفع لوط عينيه ورأى كل دائرة الأردن أن جميعها سقي, قبلما أخرب الرب سدوم وعمورة, كجنة الرب, كأرض مصر. حينما تجيء إلى صوغر.","13:11":"فاختار لوط لنفسه كل دائرة الأردن, وارتحل لوط شرقا. فاعتزل الواحد عن الآخر.","13:12":"أبرام سكن في أرض كنعان, ولوط سكن في مدن الدائرة, ونقل خيامه إلى سدوم.","13:13":"وكان أهل سدوم أشرارا وخطاة لدى الرب جدا.","13:14":"وقال الرب لأبرام, بعد اعتزال لوط عنه: «ارفع عينيك وانظر من الموضع الذي أنت فيه شمالا وجنوبا وشرقا وغربا,","13:15":"لأن جميع الأرض التي أنت ترى لك أعطيها ولنسلك إلى الأبد.","13:16":"وأجعل نسلك كتراب الأرض, حتى إذا استطاع أحد أن يعد تراب الأرض فنسلك أيضا يعد.","13:17":"قم امش في الأرض طولها وعرضها, لأني لك أعطيها».","13:18":"فنقل أبرام خيامه وأتى وأقام عند بلوطات ممرا التي في حبرون, وبنى هناك مذبحا للرب.","14:1":"وحدث في أيام أمرافل ملك شنعار, وأريوك ملك ألاسار, وكدرلعومر ملك عيلام, وتدعال ملك جوييم,","14:2":"أن هؤلاء صنعوا حربا مع بارع ملك سدوم, وبرشاع ملك عمورة, وشنآب ملك أدمة, وشمئيبر ملك صبوييم, وملك بالع التي هي صوغر.","14:3":"جميع هؤلاء اجتمعوا متعاهدين إلى عمق السديم الذي هو بحر الملح.","14:4":"اثنتي عشرة سنة استعبدوا لكدرلعومر, والسنة الثالثة عشرة عصوا عليه.","14:5":"وفي السنة الرابعة عشرة أتى كدرلعومر والملوك الذين معه وضربوا الرفائيين في عشتاروث قرنايم, والزوزيين في هام, والإيميين في شوى قريتايم,","14:6":"والحوريين في جبلهم سعير إلى بطمة فاران التي عند البرية.","14:7":"ثم رجعوا وجاءوا إلى عين مشفاط التي هي قادش. وضربوا كل بلاد العمالقة, وأيضا الأموريين الساكنين في حصون تامار.","14:8":"فخرج ملك سدوم, وملك عمورة, وملك أدمة, وملك صبوييم, وملك بالع, التي هي صوغر, ونظموا حربا معهم في عمق السديم.","14:9":"مع كدرلعومر ملك عيلام, وتدعال ملك جوييم, وأمرافل ملك شنعار, وأريوك ملك ألاسار. أربعة ملوك مع خمسة.","14:10":"وعمق السديم كان فيه آبار حمر كثيرة. فهرب ملكا سدوم وعمورة وسقطا هناك, والباقون هربوا إلى الجبل.","14:11":"فأخذوا جميع أملاك سدوم وعمورة وجميع أطعمتهم ومضوا.","14:12":"وأخذوا لوطا ابن أخي أبرام وأملاكه ومضوا, إذ كان ساكنا في سدوم.","14:13":"فأتى من نجا وأخبر أبرام العبراني. وكان ساكنا عند بلوطات ممرا الأموري, أخي أشكول وأخي عانر. وكانوا أصحاب عهد مع أبرام.","14:14":"فلما سمع أبرام, أن أخاه سبي جر غلمانه المتمرنين, ولدان بيته, ثلاث مئة وثمانية عشر, وتبعهم إلى دان.","14:15":"وانقسم عليهم ليلا هو وعبيده فكسرهم وتبعهم إلى حوبة التي عن شمال دمشق.","14:16":"واسترجع كل الأملاك, واسترجع لوطا أخاه أيضا وأملاكه, والنساء أيضا والشعب.","14:17":"فخرج ملك سدوم لاستقباله, بعد رجوعه من كسرة كدرلعومر والملوك الذين معه إلى عمق شوى, الذي هو عمق الملك.","14:18":"وملكي صادق, ملك شاليم, أخرج خبزا وخمرا. وكان كاهنا لله العلي.","14:19":"وباركه وقال: «مبارك أبرام من الله العلي مالك السماوات والأرض,","14:20":"ومبارك الله العلي الذي أسلم أعداءك في يدك». فأعطاه عشرا من كل شيء.","14:21":"وقال ملك سدوم لأبرام: «أعطني النفوس, وأما الأملاك فخذها لنفسك».","14:22":"فقال أبرام لملك سدوم: «رفعت يدي إلى الرب الإله العلي مالك السماء والأرض,","14:23":"لا آخذن لا خيطا ولا شراك نعل ولا من كل ما هو لك, فلا تقول: أنا أغنيت أبرام.","14:24":"ليس لي غير الذي أكله الغلمان, وأما نصيب الرجال الذين ذهبوا معي: عانر وأشكول وممرا, فهم يأخذون نصيبهم».","15:1":"بعد هذه الأمور صار كلام الرب إلى أبرام في الرؤيا قائلا: «لا تخف يا أبرام. أنا ترس لك. أجرك كثير جدا».","15:2":"فقال أبرام: «أيها السيد الرب, ماذا تعطيني وأنا ماض عقيما, ومالك بيتي هو أليعازر الدمشقي؟»","15:3":"وقال أبرام أيضا: «إنك لم تعطني نسلا, وهوذا ابن بيتي وارث لي».","15:4":"فإذا كلام الرب إليه قائلا: «لا يرثك هذا, بل الذي يخرج من أحشائك هو يرثك».","15:5":"ثم أخرجه إلى خارج وقال: «انظر إلى السماء وعد النجوم إن استطعت أن تعدها». وقال له: «هكذا يكون نسلك».","15:6":"فآمن بالرب فحسبه له برا.","15:7":"وقال له: «أنا الرب الذي أخرجك من أور الكلدانيين ليعطيك هذه الأرض لترثها».","15:8":"فقال: «أيها السيد الرب, بماذا أعلم أني أرثها؟»","15:9":"فقال له: «خذ لي عجلة ثلاثية, وعنزة ثلاثية, وكبشا ثلاثيا, ويمامة وحمامة».","15:10":"فأخذ هذه كلها وشقها من الوسط, وجعل شق كل واحد مقابل صاحبه. وأما الطير فلم يشقه.","15:11":"فنزلت الجوارح على الجثث, وكان أبرام يزجرها.","15:12":"ولما صارت الشمس إلى المغيب, وقع على أبرام سبات, وإذا رعبة مظلمة عظيمة واقعة عليه.","15:13":"فقال لأبرام: «اعلم يقينا أن نسلك سيكون غريبا في أرض ليست لهم, ويستعبدون لهم. فيذلونهم أربع مئة سنة.","15:14":"ثم الأمة التي يستعبدون لها أنا أدينها, وبعد ذلك يخرجون بأملاك جزيلة.","15:15":"وأما أنت فتمضي إلى آبائك بسلام وتدفن بشيبة صالحة.","15:16":"وفي الجيل الرابع يرجعون إلى ههنا, لأن ذنب الأموريين ليس إلى الآن كاملا».","15:17":"ثم غابت الشمس فصارت العتمة, وإذا تنور دخان ومصباح نار يجوز بين تلك القطع.","15:18":"في ذلك اليوم قطع الرب مع أبرام ميثاقا قائلا: «لنسلك أعطي هذه الأرض, من نهر مصر إلى النهر الكبير, نهر الفرات.","15:19":"القينيين والقنزيين والقدمونيين","15:20":"والحثيين والفرزيين والرفائيين","15:21":"والأموريين والكنعانيين والجرجاشيين واليبوسيين».","16:1":"وأما ساراي امرأة أبرام فلم تلد له. وكانت لها جارية مصرية اسمها هاجر,","16:2":"فقالت ساراي لأبرام: «هوذا الرب قد أمسكني عن الولادة. ادخل على جاريتي لعلي أرزق منها بنين». فسمع أبرام لقول ساراي.","16:3":"فأخذت ساراي امرأة أبرام هاجر المصرية جاريتها, من بعد عشر سنين لإقامة أبرام في أرض كنعان, وأعطتها لأبرام رجلها زوجة له.","16:4":"فدخل على هاجر فحبلت. ولما رأت أنها حبلت صغرت مولاتها في عينيها.","16:5":"فقالت ساراي لأبرام: «ظلمي عليك! أنا دفعت جاريتي إلى حضنك, فلما رأت أنها حبلت صغرت في عينيها. يقضي الرب بيني وبينك».","16:6":"فقال أبرام لساراي: «هوذا جاريتك في يدك. افعلي بها ما يحسن في عينيك». فأذلتها ساراي, فهربت من وجهها.","16:7":"فوجدها ملاك الرب على عين الماء في البرية, على العين التي في طريق شور.","16:8":"وقال: «يا هاجر جارية ساراي, من أين أتيت؟ وإلى أين تذهبين؟». فقالت: «أنا هاربة من وجه مولاتي ساراي».","16:9":"فقال لها ملاك الرب: «ارجعي إلى مولاتك واخضعي تحت يديها».","16:10":"وقال لها ملاك الرب: «تكثيرا أكثر نسلك فلا يعد من الكثرة».","16:11":"وقال لها ملاك الرب: «ها أنت حبلى, فتلدين ابنا وتدعين اسمه إسماعيل, لأن الرب قد سمع لمذلتك.","16:12":"وإنه يكون إنسانا وحشيا, يده على كل واحد, ويد كل واحد عليه, وأمام جميع إخوته يسكن».","16:13":"فدعت اسم الرب الذي تكلم معها: «أنت إيل رئي». لأنها قالت: «أههنا أيضا رأيت بعد رؤية؟»","16:14":"لذلك دعيت البئر «بئر لحي رئي». ها هي بين قادش وبارد.","16:15":"فولدت هاجر لأبرام ابنا. ودعا أبرام اسم ابنه الذي ولدته هاجر «إسماعيل».","16:16":"كان أبرام ابن ست وثمانين سنة لما ولدت هاجر إسماعيل لأبرام.","17:1":"ولما كان أبرام ابن تسع وتسعين سنة ظهر الرب لأبرام وقال له: «أنا الله القدير. سر أمامي وكن كاملا,","17:2":"فأجعل عهدي بيني وبينك, وأكثرك كثيرا جدا».","17:3":"فسقط أبرام على وجهه. وتكلم الله معه قائلا:","17:4":"«أما أنا فهوذا عهدي معك, وتكون أبا لجمهور من الأمم,","17:5":"فلا يدعى اسمك بعد أبرام بل يكون اسمك إبراهيم, لأني أجعلك أبا لجمهور من الأمم.","17:6":"وأثمرك كثيرا جدا, وأجعلك أمما, وملوك منك يخرجون.","17:7":"وأقيم عهدي بيني وبينك, وبين نسلك من بعدك في أجيالهم, عهدا أبديا, لأكون إلها لك ولنسلك من بعدك.","17:8":"وأعطي لك ولنسلك من بعدك أرض غربتك, كل أرض كنعان ملكا أبديا. وأكون إلههم».","17:9":"وقال الله لإبراهيم: «وأما أنت فتحفظ عهدي, أنت ونسلك من بعدك في أجيالهم.","17:10":"هذا هو عهدي الذي تحفظونه بيني وبينكم, وبين نسلك من بعدك: يختن منكم كل ذكر,","17:11":"فتختنون في لحم غرلتكم, فيكون علامة عهد بيني وبينكم.","17:12":"ابن ثمانية أيام يختن منكم كل ذكر في أجيالكم: وليد البيت, والمبتاع بفضة من كل ابن غريب ليس من نسلك.","17:13":"يختن ختانا وليد بيتك والمبتاع بفضتك, فيكون عهدي في لحمكم عهدا أبديا.","17:14":"وأما الذكر الأغلف الذي لا يختن في لحم غرلته فتقطع تلك النفس من شعبها. إنه قد نكث عهدي».","17:15":"وقال الله لإبراهيم: «ساراي امرأتك لا تدعو اسمها ساراي, بل اسمها سارة.","17:16":"وأباركها وأعطيك أيضا منها ابنا. أباركها فتكون أمما, وملوك شعوب منها يكونون».","17:17":"فسقط إبراهيم على وجهه وضحك, وقال في قلبه: «هل يولد لابن مئة سنة؟ وهل تلد سارة وهي بنت تسعين سنة؟».","17:18":"وقال إبراهيم لله: «ليت إسماعيل يعيش أمامك!».","17:19":"فقال الله: «بل سارة امرأتك تلد لك ابنا وتدعو اسمه إسحاق. وأقيم عهدي معه عهدا أبديا لنسله من بعده.","17:20":"وأما إسماعيل فقد سمعت لك فيه. ها أنا أباركه وأثمره وأكثره كثيرا جدا. اثني عشر رئيسا يلد, وأجعله أمة كبيرة.","17:21":"ولكن عهدي أقيمه مع إسحاق الذي تلده لك سارة في هذا الوقت في السنة الآتية».","17:22":"فلما فرغ من الكلام معه صعد الله عن إبراهيم.","17:23":"فأخذ إبراهيم إسماعيل ابنه, وجميع ولدان بيته, وجميع المبتاعين بفضته, كل ذكر من أهل بيت إبراهيم, وختن لحم غرلتهم في ذلك اليوم عينه كما كلمه الله.","17:24":"وكان إبراهيم ابن تسع وتسعين سنة حين ختن في لحم غرلته,","17:25":"وكان إسماعيل ابنه ابن ثلاث عشرة سنة حين ختن في لحم غرلته.","17:26":"في ذلك اليوم عينه ختن إبراهيم وإسماعيل ابنه.","17:27":"وكل رجال بيته ولدان البيت والمبتاعين بالفضة من ابن الغريب ختنوا معه.","18:1":"وظهر له الرب عند بلوطات ممرا وهو جالس في باب الخيمة وقت حر النهار,","18:2":"فرفع عينيه ونظر وإذا ثلاثة رجال واقفون لديه. فلما نظر ركض لاستقبالهم من باب الخيمة وسجد إلى الأرض,","18:3":"وقال: «يا سيد, إن كنت قد وجدت نعمة في عينيك فلا تتجاوز عبدك.","18:4":"ليؤخذ قليل ماء واغسلوا أرجلكم واتكئوا تحت الشجرة,","18:5":"فآخذ كسرة خبز, فتسندون قلوبكم ثم تجتازون, لأنكم قد مررتم على عبدكم». فقالوا: «هكذا تفعل كما تكلمت».","18:6":"فأسرع إبراهيم إلى الخيمة إلى سارة, وقال: «أسرعي بثلاث كيلات دقيقا سميذا. اعجني واصنعي خبز ملة».","18:7":"ثم ركض إبراهيم إلى البقر وأخذ عجلا رخصا وجيدا وأعطاه للغلام فأسرع ليعمله.","18:8":"ثم أخذ زبدا ولبنا, والعجل الذي عمله, ووضعها قدامهم. وإذ كان هو واقفا لديهم تحت الشجرة أكلوا.","18:9":"وقالوا له: «أين سارة امرأتك؟» فقال: «ها هي في الخيمة».","18:10":"فقال: «إني أرجع إليك نحو زمان الحياة ويكون لسارة امرأتك ابن». وكانت سارة سامعة في باب الخيمة وهو وراءه.","18:11":"وكان إبراهيم وسارة شيخين متقدمين في الأيام, وقد انقطع أن يكون لسارة عادة كالنساء.","18:12":"فضحكت سارة في باطنها قائلة: «أبعد فنائي يكون لي تنعم, وسيدي قد شاخ؟»","18:13":"فقال الرب لإبراهيم: «لماذا ضحكت سارة قائلة: أفبالحقيقة ألد وأنا قد شخت؟","18:14":"هل يستحيل على الرب شيء؟ في الميعاد أرجع إليك نحو زمان الحياة ويكون لسارة ابن».","18:15":"فأنكرت سارة قائلة: «لم أضحك». لأنها خافت. فقال: «لا! بل ضحكت».","18:16":"ثم قام الرجال من هناك وتطلعوا نحو سدوم. وكان إبراهيم ماشيا معهم ليشيعهم.","18:17":"فقال الرب: «هل أخفي عن إبراهيم ما أنا فاعله,","18:18":"وإبراهيم يكون أمة كبيرة وقوية, ويتبارك به جميع أمم الأرض؟","18:19":"لأني عرفته لكي يوصي بنيه وبيته من بعده أن يحفظوا طريق الرب, ليعملوا برا وعدلا, لكي يأتي الرب لإبراهيم بما تكلم به».","18:20":"وقال الرب: «إن صراخ سدوم وعمورة قد كثر, وخطيتهم قد عظمت جدا.","18:21":"أنزل وأرى هل فعلوا بالتمام حسب صراخها الآتي إلي, وإلا فأعلم».","18:22":"وانصرف الرجال من هناك وذهبوا نحو سدوم, وأما إبراهيم فكان لم يزل قائما أمام الرب.","18:23":"فتقدم إبراهيم وقال: «أفتهلك البار مع الأثيم؟","18:24":"عسى أن يكون خمسون بارا في المدينة. أفتهلك المكان ولا تصفح عنه من أجل الخمسين بارا الذين فيه؟","18:25":"حاشا لك أن تفعل مثل هذا الأمر, أن تميت البار مع الأثيم, فيكون البار كالأثيم. حاشا لك! أديان كل الأرض لا يصنع عدلا؟»","18:26":"فقال الرب: «إن وجدت في سدوم خمسين بارا في المدينة, فإني أصفح عن المكان كله من أجلهم».","18:27":"فأجاب إبراهيم وقال: «إني قد شرعت أكلم المولى وأنا تراب ورماد.","18:28":"ربما نقص الخمسون بارا خمسة. أتهلك كل المدينة بالخمسة؟» فقال: «لا أهلك إن وجدت هناك خمسة وأربعين».","18:29":"فعاد يكلمه أيضا وقال: «عسى أن يوجد هناك أربعون». فقال: «لا أفعل من أجل الأربعين».","18:30":"فقال: «لا يسخط المولى فأتكلم. عسى أن يوجد هناك ثلاثون». فقال: «لا أفعل إن وجدت هناك ثلاثين».","18:31":"فقال: «إني قد شرعت أكلم المولى. عسى أن يوجد هناك عشرون». فقال: «لا أهلك من أجل العشرين».","18:32":"فقال: «لا يسخط المولى فأتكلم هذه المرة فقط. عسى أن يوجد هناك عشرة». فقال: «لا أهلك من أجل العشرة».","18:33":"وذهب الرب عندما فرغ من الكلام مع إبراهيم, ورجع إبراهيم إلى مكانه.","19:1":"فجاء الملاكان إلى سدوم مساء, وكان لوط جالسا في باب سدوم. فلما رآهما لوط قام لاستقبالهما, وسجد بوجهه إلى الأرض.","19:2":"وقال: «يا سيدي, ميلا إلى بيت عبدكما وبيتا واغسلا أرجلكما, ثم تبكران وتذهبان في طريقكما». فقالا: «لا, بل في الساحة نبيت».","19:3":"فألح عليهما جدا, فمالا إليه ودخلا بيته, فصنع لهما ضيافة وخبز فطيرا فأكلا.","19:4":"وقبلما اضطجعا أحاط بالبيت رجال المدينة, رجال سدوم, من الحدث إلى الشيخ, كل الشعب من أقصاها.","19:5":"فنادوا لوطا وقالوا له: «أين الرجلان اللذان دخلا إليك الليلة؟ أخرجهما إلينا لنعرفهما».","19:6":"فخرج إليهم لوط إلى الباب وأغلق الباب وراءه","19:7":"وقال: «لا تفعلوا شرا يا إخوتي.","19:8":"هوذا لي ابنتان لم تعرفا رجلا. أخرجهما إليكم فافعلوا بهما كما يحسن في عيونكم. وأما هذان الرجلان فلا تفعلوا بهما شيئا, لأنهما قد دخلا تحت ظل سقفي».","19:9":"فقالوا: «ابعد إلى هناك». ثم قالوا: «جاء هذا الإنسان ليتغرب, وهو يحكم حكما. الآن نفعل بك شرا أكثر منهما». فألحوا على الرجل لوط جدا وتقدموا ليكسروا الباب,","19:10":"فمد الرجلان أيديهما وأدخلا لوطا إليهما إلى البيت وأغلقا الباب.","19:11":"وأما الرجال الذين على باب البيت فضرباهم بالعمى, من الصغير إلى الكبير, فعجزوا عن أن يجدوا الباب.","19:12":"وقال الرجلان للوط: «من لك أيضا ههنا؟ أصهارك وبنيك وبناتك وكل من لك في المدينة, أخرج من المكان,","19:13":"لأننا مهلكان هذا المكان, إذ قد عظم صراخهم أمام الرب, فأرسلنا الرب لنهلكه».","19:14":"فخرج لوط وكلم أصهاره الآخذين بناته وقال: «قوموا اخرجوا من هذا المكان, لأن الرب مهلك المدينة». فكان كمازح في أعين أصهاره.","19:15":"ولما طلع الفجر كان الملاكان يعجلان لوطا قائلين: «قم خذ امرأتك وابنتيك الموجودتين لئلا تهلك بإثم المدينة».","19:16":"ولما توانى, أمسك الرجلان بيده وبيد امرأته وبيد ابنتيه, لشفقة الرب عليه, وأخرجاه ووضعاه خارج المدينة.","19:17":"وكان لما أخرجاهم إلى خارج أنه قال: «اهرب لحياتك. لا تنظر إلى ورائك, ولا تقف في كل الدائرة. اهرب إلى الجبل لئلا تهلك».","19:18":"فقال لهما لوط: «لا يا سيد.","19:19":"هوذا عبدك قد وجد نعمة في عينيك, وعظمت لطفك الذي صنعت إلي باستبقاء نفسي, وأنا لا أقدر أن أهرب إلى الجبل لعل الشر يدركني فأموت.","19:20":"هوذا المدينة هذه قريبة للهرب إليها وهي صغيرة. أهرب إلى هناك. أليست هي صغيرة؟ فتحيا نفسي».","19:21":"فقال له: «إني قد رفعت وجهك في هذا الأمر أيضا, أن لا أقلب المدينة التي تكلمت عنها.","19:22":"أسرع اهرب إلى هناك لأني لا أستطيع أن أفعل شيئا حتى تجيء إلى هناك». لذلك دعي اسم المدينة «صوغر».","19:23":"وإذ أشرقت الشمس على الأرض دخل لوط إلى صوغر,","19:24":"فأمطر الرب على سدوم وعمورة كبريتا ونارا من عند الرب من السماء.","19:25":"وقلب تلك المدن, وكل الدائرة, وجميع سكان المدن, ونبات الأرض.","19:26":"ونظرت امرأته من ورائه فصارت عمود ملح.","19:27":"وبكر إبراهيم في الغد إلى المكان الذي وقف فيه أمام الرب,","19:28":"وتطلع نحو سدوم وعمورة, ونحو كل أرض الدائرة, ونظر وإذا دخان الأرض يصعد كدخان الأتون.","19:29":"وحدث لما أخرب الله مدن الدائرة أن الله ذكر إبراهيم, وأرسل لوطا من وسط الانقلاب. حين قلب المدن التي سكن فيها لوط.","19:30":"وصعد لوط من صوغر وسكن في الجبل, وابنتاه معه, لأنه خاف أن يسكن في صوغر. فسكن في المغارة هو وابنتاه.","19:31":"وقالت البكر للصغيرة: «أبونا قد شاخ, وليس في الأرض رجل ليدخل علينا كعادة كل الأرض.","19:32":"هلم نسقي أبانا خمرا ونضطجع معه, فنحيي من أبينا نسلا».","19:33":"فسقتا أباهما خمرا في تلك الليلة, ودخلت البكر واضطجعت مع أبيها, ولم يعلم باضطجاعها ولا بقيامها.","19:34":"وحدث في الغد أن البكر قالت للصغيرة: «إني قد اضطجعت البارحة مع أبي. نسقيه خمرا الليلة أيضا فادخلي اضطجعي معه, فنحيي من أبينا نسلا».","19:35":"فسقتا أباهما خمرا في تلك الليلة أيضا, وقامت الصغيرة واضطجعت معه, ولم يعلم باضطجاعها ولا بقيامها,","19:36":"فحبلت ابنتا لوط من أبيهما.","19:37":"فولدت البكر ابنا ودعت اسمه «موآب», وهو أبو الموآبيين إلى اليوم.","19:38":"والصغيرة أيضا ولدت ابنا ودعت اسمه «بن عمي», وهو أبو بني عمون إلى اليوم.","20:1":"وانتقل إبراهيم من هناك إلى أرض الجنوب, وسكن بين قادش وشور, وتغرب في جرار.","20:2":"وقال إبراهيم عن سارة امرأته: «هي أختي». فأرسل أبيمالك ملك جرار وأخذ سارة.","20:3":"فجاء الله إلى أبيمالك في حلم الليل وقال له: «ها أنت ميت من أجل المرأة التي أخذتها, فإنها متزوجة ببعل».","20:4":"ولكن لم يكن أبيمالك قد اقترب إليها, فقال: «يا سيد, أأمة بارة تقتل؟","20:5":"ألم يقل هو لي: إنها أختي, وهي أيضا نفسها قالت: هو أخي؟ بسلامة قلبي ونقاوة يدي فعلت هذا».","20:6":"فقال له الله في الحلم: «أنا أيضا علمت أنك بسلامة قلبك فعلت هذا. وأنا أيضا أمسكتك عن أن تخطئ إلي, لذلك لم أدعك تمسها.","20:7":"فالآن رد امرأة الرجل, فإنه نبي, فيصلي لأجلك فتحيا. وإن كنت لست تردها, فاعلم أنك موتا تموت, أنت وكل من لك».","20:8":"فبكر أبيمالك في الغد ودعا جميع عبيده, وتكلم بكل هذا الكلام في مسامعهم, فخاف الرجال جدا.","20:9":"ثم دعا أبيمالك إبراهيم وقال له: «ماذا فعلت بنا؟ وبماذا أخطأت إليك حتى جلبت علي وعلى مملكتي خطية عظيمة؟ أعمالا لا تعمل عملت بي».","20:10":"وقال أبيمالك لإبراهيم: «ماذا رأيت حتى عملت هذا الشيء؟»","20:11":"فقال إبراهيم: «إني قلت: ليس في هذا الموضع خوف الله البتة, فيقتلونني لأجل امرأتي.","20:12":"وبالحقيقة أيضا هي أختي ابنة أبي, غير أنها ليست ابنة أمي, فصارت لي زوجة.","20:13":"وحدث لما أتاهني الله من بيت أبي أني قلت لها: هذا معروفك الذي تصنعين إلي: في كل مكان نأتي إليه قولي عني: هو أخي».","20:14":"فأخذ أبيمالك غنما وبقرا وعبيدا وإماء وأعطاها لإبراهيم, ورد إليه سارة امرأته.","20:15":"وقال أبيمالك: «هوذا أرضي قدامك. اسكن في ما حسن في عينيك».","20:16":"وقال لسارة: «إني قد أعطيت أخاك ألفا من الفضة. ها هو لك غطاء عين من جهة كل ما عندك وعند كل واحد, فأنصفت».","20:17":"فصلى إبراهيم إلى الله, فشفى الله أبيمالك وامرأته وجواريه فولدن.","20:18":"لأن الرب كان قد أغلق كل رحم لبيت أبيمالك بسبب سارة امرأة إبراهيم.","21:1":"وافتقد الرب سارة كما قال, وفعل الرب لسارة كما تكلم.","21:2":"فحبلت سارة وولدت لإبراهيم ابنا في شيخوخته, في الوقت الذي تكلم الله عنه.","21:3":"ودعا إبراهيم اسم ابنه المولود له, الذي ولدته له سارة «إسحاق».","21:4":"وختن إبراهيم إسحاق ابنه وهو ابن ثمانية أيام كما أمره الله.","21:5":"وكان إبراهيم ابن مئة سنة حين ولد له إسحاق ابنه.","21:6":"وقالت سارة: «قد صنع إلي الله ضحكا. كل من يسمع يضحك لي».","21:7":"وقالت: «من قال لإبراهيم: سارة ترضع بنين؟ حتى ولدت ابنا في شيخوخته!».","21:8":"فكبر الولد وفطم. وصنع إبراهيم وليمة عظيمة يوم فطام إسحاق.","21:9":"ورأت سارة ابن هاجر المصرية الذي ولدته لإبراهيم يمزح,","21:10":"فقالت لإبراهيم: «اطرد هذه الجارية وابنها, لأن ابن هذه الجارية لا يرث مع ابني إسحاق».","21:11":"فقبح الكلام جدا في عيني إبراهيم لسبب ابنه.","21:12":"فقال الله لإبراهيم: «لا يقبح في عينيك من أجل الغلام ومن أجل جاريتك. في كل ما تقول لك سارة اسمع لقولها, لأنه بإسحاق يدعى لك نسل.","21:13":"وابن الجارية أيضا سأجعله أمة لأنه نسلك».","21:14":"فبكر إبراهيم صباحا وأخذ خبزا وقربة ماء وأعطاهما لهاجر, واضعا إياهما على كتفها, والولد, وصرفها. فمضت وتاهت في برية بئر سبع.","21:15":"ولما فرغ الماء من القربة طرحت الولد تحت إحدى الأشجار,","21:16":"ومضت وجلست مقابله بعيدا نحو رمية قوس, لأنها قالت: «لا أنظر موت الولد». فجلست مقابله ورفعت صوتها وبكت.","21:17":"فسمع الله صوت الغلام, ونادى ملاك الله هاجر من السماء وقال لها: «ما لك يا هاجر؟ لا تخافي, لأن الله قد سمع لصوت الغلام حيث هو.","21:18":"قومي احملي الغلام وشدي يدك به, لأني سأجعله أمة عظيمة».","21:19":"وفتح الله عينيها فأبصرت بئر ماء, فذهبت وملأت القربة ماء وسقت الغلام.","21:20":"وكان الله مع الغلام فكبر, وسكن في البرية, وكان ينمو رامي قوس.","21:21":"وسكن في برية فاران, وأخذت له أمه زوجة من أرض مصر.","21:22":"وحدث في ذلك الزمان أن أبيمالك وفيكول رئيس جيشه كلما إبراهيم قائلين: «الله معك في كل ما أنت صانع.","21:23":"فالآن احلف لي بالله ههنا أنك لا تغدر بي ولا بنسلي وذريتي, كالمعروف الذي صنعت إليك تصنع إلي وإلى الأرض التي تغربت فيها».","21:24":"فقال إبراهيم: «أنا أحلف».","21:25":"وعاتب إبراهيم أبيمالك لسبب بئر الماء التي اغتصبها عبيد أبيمالك.","21:26":"فقال أبيمالك: «لم أعلم من فعل هذا الأمر. أنت لم تخبرني, ولا أنا سمعت سوى اليوم».","21:27":"فأخذ إبراهيم غنما وبقرا وأعطى أبيمالك, فقطعا كلاهما ميثاقا.","21:28":"وأقام إبراهيم سبع نعاج من الغنم وحدها.","21:29":"فقال أبيمالك لإبراهيم: «ما هي هذه السبع النعاج التي أقمتها وحدها؟»","21:30":"فقال: «إنك سبع نعاج تأخذ من يدي, لكي تكون لي شهادة بأني حفرت هذه البئر».","21:31":"لذلك دعا ذلك الموضع «بئر سبع», لأنهما هناك حلفا كلاهما.","21:32":"فقطعا ميثاقا في بئر سبع, ثم قام أبيمالك وفيكول رئيس جيشه ورجعا إلى أرض الفلسطينيين.","21:33":"وغرس إبراهيم أثلا في بئر سبع, ودعا هناك باسم الرب الإله السرمدي.","21:34":"وتغرب إبراهيم في أرض الفلسطينيين أياما كثيرة.","22:1":"وحدث بعد هذه الأمور أن الله امتحن إبراهيم, فقال له: «يا إبراهيم!». فقال: «هأنذا».","22:2":"فقال: «خذ ابنك وحيدك, الذي تحبه, إسحاق, واذهب إلى أرض المريا, وأصعده هناك محرقة على أحد الجبال الذي أقول لك».","22:3":"فبكر إبراهيم صباحا وشد على حماره, وأخذ اثنين من غلمانه معه, وإسحاق ابنه, وشقق حطبا لمحرقة, وقام وذهب إلى الموضع الذي قال له الله.","22:4":"وفي اليوم الثالث رفع إبراهيم عينيه وأبصر الموضع من بعيد,","22:5":"فقال إبراهيم لغلاميه: «اجلسا أنتما ههنا مع الحمار, وأما أنا والغلام فنذهب إلى هناك ونسجد, ثم نرجع إليكما».","22:6":"فأخذ إبراهيم حطب المحرقة ووضعه على إسحاق ابنه, وأخذ بيده النار والسكين. فذهبا كلاهما معا.","22:7":"وكلم إسحاق إبراهيم أباه وقال: «يا أبي!». فقال: «هأنذا يا ابني». فقال: «هوذا النار والحطب, ولكن أين الخروف للمحرقة؟»","22:8":"فقال إبراهيم: «الله يرى له الخروف للمحرقة يا ابني». فذهبا كلاهما معا.","22:9":"فلما أتيا إلى الموضع الذي قال له الله, بنى هناك إبراهيم المذبح ورتب الحطب وربط إسحاق ابنه ووضعه على المذبح فوق الحطب.","22:10":"ثم مد إبراهيم يده وأخذ السكين ليذبح ابنه.","22:11":"فناداه ملاك الرب من السماء وقال: «إبراهيم! إبراهيم!». فقال: «هأنذا»","22:12":"فقال: «لا تمد يدك إلى الغلام ولا تفعل به شيئا, لأني الآن علمت أنك خائف الله, فلم تمسك ابنك وحيدك عني».","22:13":"فرفع إبراهيم عينيه ونظر وإذا كبش وراءه ممسكا في الغابة بقرنيه, فذهب إبراهيم وأخذ الكبش وأصعده محرقة عوضا عن ابنه.","22:14":"فدعا إبراهيم اسم ذلك الموضع «يهوه يرأه». حتى إنه يقال اليوم: «في جبل الرب يرى».","22:15":"ونادى ملاك الرب إبراهيم ثانية من السماء","22:16":"وقال: «بذاتي أقسمت يقول الرب, أني من أجل أنك فعلت هذا الأمر, ولم تمسك ابنك وحيدك,","22:17":"أباركك مباركة, وأكثر نسلك تكثيرا كنجوم السماء وكالرمل الذي على شاطئ البحر, ويرث نسلك باب أعدائه,","22:18":"ويتبارك في نسلك جميع أمم الأرض, من أجل أنك سمعت لقولي».","22:19":"ثم رجع إبراهيم إلى غلاميه, فقاموا وذهبوا معا إلى بئر سبع. وسكن إبراهيم في بئر سبع.","22:20":"وحدث بعد هذه الأمور أن إبراهيم أخبر وقيل له: «هوذا ملكة قد ولدت هي أيضا بنين لناحور أخيك:","22:21":"عوصا بكره, وبوزا أخاه, وقموئيل أبا أرام,","22:22":"وكاسد وحزوا وفلداش ويدلاف وبتوئيل».","22:23":"وولد بتوئيل رفقة. هؤلاء الثمانية ولدتهم ملكة لناحور أخي إبراهيم.","22:24":"وأما سريته, واسمها رؤومة, فولدت هي أيضا: طابح وجاحم وتاحش ومعكة.","23:1":"وكانت حياة سارة مئة وسبعا وعشرين سنة, سني حياة سارة.","23:2":"وماتت سارة في قرية أربع, التي هي حبرون, في أرض كنعان. فأتى إبراهيم ليندب سارة ويبكي عليها.","23:3":"وقام إبراهيم من أمام ميته وكلم بني حث قائلا:","23:4":"«أنا غريب ونزيل عندكم. أعطوني ملك قبر معكم لأدفن ميتي من أمامي».","23:5":"فأجاب بنو حث إبراهيم قائلين له:","23:6":"«اسمعنا يا سيدي. أنت رئيس من الله بيننا. في أفضل قبورنا ادفن ميتك, لا يمنع أحد منا قبره عنك حتى لا تدفن ميتك».","23:7":"فقام إبراهيم وسجد لشعب الأرض, لبني حث,","23:8":"وكلمهم قائلا: «إن كان في نفوسكم أن أدفن ميتي من أمامي, فاسمعوني والتمسوا لي من عفرون بن صوحر","23:9":"أن يعطيني مغارة المكفيلة التي له, التي في طرف حقله. بثمن كامل يعطيني إياها في وسطكم ملك قبر».","23:10":"وكان عفرون جالسا بين بني حث, فأجاب عفرون الحثي إبراهيم في مسامع بني حث, لدى جميع الداخلين باب مدينته قائلا:","23:11":"«لا يا سيدي, اسمعني. الحقل وهبتك إياه, والمغارة التي فيه لك وهبتها. لدى عيون بني شعبي وهبتك إياها. ادفن ميتك».","23:12":"فسجد إبراهيم أمام شعب الأرض,","23:13":"وكلم عفرون في مسامع شعب الأرض قائلا: «بل إن كنت أنت إياه فليتك تسمعني. أعطيك ثمن الحقل. خذ مني فأدفن ميتي هناك».","23:14":"فأجاب عفرون إبراهيم قائلا له:","23:15":"«يا سيدي, اسمعني. أرض بأربع مئة شاقل فضة, ما هي بيني وبينك؟ فادفن ميتك».","23:16":"فسمع إبراهيم لعفرون, ووزن إبراهيم لعفرون الفضة التي ذكرها في مسامع بني حث. أربع مئة شاقل فضة جائزة عند التجار.","23:17":"فوجب حقل عفرون الذي في المكفيلة التي أمام ممرا, الحقل والمغارة التي فيه, وجميع الشجر الذي في الحقل الذي في جميع حدوده حواليه,","23:18":"لإبراهيم ملكا لدى عيون بني حث, بين جميع الداخلين باب مدينته.","23:19":"وبعد ذلك دفن إبراهيم سارة امرأته في مغارة حقل المكفيلة أمام ممرا, التي هي حبرون, في أرض كنعان,","23:20":"فوجب الحقل والمغارة التي فيه لإبراهيم ملك قبر من عند بني حث.","24:1":"وشاخ إبراهيم وتقدم في الأيام. وبارك الرب إبراهيم في كل شيء.","24:2":"وقال إبراهيم لعبده كبير بيته المستولي على كل ما كان له: «ضع يدك تحت فخذي,","24:3":"فأستحلفك بالرب إله السماء وإله الأرض أن لا تأخذ زوجة لابني من بنات الكنعانيين الذين أنا ساكن بينهم,","24:4":"بل إلى أرضي وإلى عشيرتي تذهب وتأخذ زوجة لابني إسحاق».","24:5":"فقال له العبد: «ربما لا تشاء المرأة أن تتبعني إلى هذه الأرض. هل أرجع بابنك إلى الأرض التي خرجت منها؟»","24:6":"فقال له إبراهيم: «احترز من أن ترجع بابني إلى هناك.","24:7":"الرب إله السماء الذي أخذني من بيت أبي ومن أرض ميلادي, والذي كلمني والذي أقسم لي قائلا: لنسلك أعطي هذه الأرض, هو يرسل ملاكه أمامك, فتأخذ زوجة لابني من هناك.","24:8":"وإن لم تشإ المرأة أن تتبعك, تبرأت من حلفي هذا. أما ابني فلا ترجع به إلى هناك».","24:9":"فوضع العبد يده تحت فخذ إبراهيم مولاه, وحلف له على هذا الأمر.","24:10":"ثم أخذ العبد عشرة جمال من جمال مولاه, ومضى وجميع خيرات مولاه في يده. فقام وذهب إلى أرام النهرين إلى مدينة ناحور.","24:11":"وأناخ الجمال خارج المدينة عند بئر الماء وقت المساء, وقت خروج المستقيات.","24:12":"وقال: «أيها الرب إله سيدي إبراهيم, يسر لي اليوم واصنع لطفا إلى سيدي إبراهيم.","24:13":"ها أنا واقف على عين الماء, وبنات أهل المدينة خارجات ليستقين ماء.","24:14":"فليكن أن الفتاة التي أقول لها: أميلي جرتك لأشرب, فتقول: اشرب وأنا أسقي جمالك أيضا, هي التي عينتها لعبدك إسحاق. وبها أعلم أنك صنعت لطفا إلى سيدي».","24:15":"وإذ كان لم يفرغ بعد من الكلام, إذا رفقة التي ولدت لبتوئيل ابن ملكة امرأة ناحور أخي إبراهيم, خارجة وجرتها على كتفها.","24:16":"وكانت الفتاة حسنة المنظر جدا, وعذراء لم يعرفها رجل. فنزلت إلى العين وملأت جرتها وطلعت.","24:17":"فركض العبد للقائها وقال: «اسقيني قليل ماء من جرتك».","24:18":"فقالت: «اشرب يا سيدي». وأسرعت وأنزلت جرتها على يدها وسقته.","24:19":"ولما فرغت من سقيه قالت: «أستقي لجمالك أيضا حتى تفرغ من الشرب».","24:20":"فأسرعت وأفرغت جرتها في المسقاة, وركضت أيضا إلى البئر لتستقي, فاستقت لكل جماله.","24:21":"والرجل يتفرس فيها صامتا ليعلم: أأنجح الرب طريقه أم لا.","24:22":"وحدث عندما فرغت الجمال من الشرب أن الرجل أخذ خزامة ذهب وزنها نصف شاقل وسوارين على يديها وزنهما عشرة شواقل ذهب.","24:23":"وقال: «بنت من أنت؟ أخبريني: هل في بيت أبيك مكان لنا لنبيت؟»","24:24":"فقالت له: «أنا بنت بتوئيل ابن ملكة الذي ولدته لناحور».","24:25":"وقالت له: «عندنا تبن وعلف كثير, ومكان لتبيتوا أيضا».","24:26":"فخر الرجل وسجد للرب,","24:27":"وقال: «مبارك الرب إله سيدي إبراهيم الذي لم يمنع لطفه وحقه عن سيدي. إذ كنت أنا في الطريق, هداني الرب إلى بيت إخوة سيدي».","24:28":"فركضت الفتاة وأخبرت بيت أمها بحسب هذه الأمور.","24:29":"وكان لرفقة أخ اسمه لابان, فركض لابان إلى الرجل خارجا إلى العين.","24:30":"وحدث أنه إذ رأى الخزامة والسوارين على يدي أخته, وإذ سمع كلام رفقة أخته قائلة: «هكذا كلمني الرجل», جاء إلى الرجل, وإذا هو واقف عند الجمال على العين.","24:31":"فقال: «ادخل يا مبارك الرب, لماذا تقف خارجا وأنا قد هيأت البيت ومكانا للجمال؟».","24:32":"فدخل الرجل إلى البيت وحل عن الجمال, فأعطى تبنا وعلفا للجمال, وماء لغسل رجليه وأرجل الرجال الذين معه.","24:33":"ووضع قدامه ليأكل. فقال: «لا آكل حتى أتكلم كلامي». فقال: «تكلم».","24:34":"فقال: «أنا عبد إبراهيم,","24:35":"والرب قد بارك مولاي جدا فصار عظيما, وأعطاه غنما وبقرا وفضة وذهبا وعبيدا وإماء وجمالا وحميرا.","24:36":"وولدت سارة امرأة سيدي ابنا لسيدي بعد ما شاخت, فقد أعطاه كل ما له.","24:37":"واستحلفني سيدي قائلا: لا تأخذ زوجة لابني من بنات الكنعانيين الذين أنا ساكن في أرضهم,","24:38":"بل إلى بيت أبي تذهب وإلى عشيرتي, وتأخذ زوجة لابني.","24:39":"فقلت لسيدي: ربما لا تتبعني المرأة.","24:40":"فقال لي: إن الرب الذي سرت أمامه يرسل ملاكه معك وينجح طريقك, فتأخذ زوجة لابني من عشيرتي ومن بيت أبي.","24:41":"حينئذ تتبرأ من حلفي حينما تجيء إلى عشيرتي. وإن لم يعطوك فتكون بريئا من حلفي.","24:42":"فجئت اليوم إلى العين, وقلت: أيها الرب إله سيدي إبراهيم, إن كنت تنجح طريقي الذي أنا سالك فيه,","24:43":"فها أنا واقف على عين الماء, وليكن أن الفتاة التي تخرج لتستقي وأقول لها: اسقيني قليل ماء من جرتك,","24:44":"فتقول لي: اشرب أنت, وأنا أستقي لجمالك أيضا, هي المرأة التي عينها الرب لابن سيدي.","24:45":"وإذ كنت أنا لم أفرغ بعد من الكلام في قلبي, إذا رفقة خارجة وجرتها على كتفها, فنزلت إلى العين واستقت. فقلت لها: اسقيني.","24:46":"فأسرعت وأنزلت جرتها عنها وقالت: اشرب وأنا أسقي جمالك أيضا. فشربت, وسقت الجمال أيضا.","24:47":"فسألتها وقلت: بنت من أنت؟ فقالت: بنت بتوئيل بن ناحور الذي ولدته له ملكة. فوضعت الخزامة في أنفها والسوارين على يديها.","24:48":"وخررت وسجدت للرب, وباركت الرب إله سيدي إبراهيم الذي هداني في طريق أمين لآخذ ابنة أخي سيدي لابنه.","24:49":"والآن إن كنتم تصنعون معروفا وأمانة إلى سيدي فأخبروني, وإلا فأخبروني لأنصرف يمينا أو شمالا».","24:50":"فأجاب لابان وبتوئيل وقالا: «من عند الرب خرج الأمر. لا نقدر أن نكلمك بشر أو خير.","24:51":"هوذا رفقة قدامك. خذها واذهب. فلتكن زوجة لابن سيدك, كما تكلم الرب».","24:52":"وكان عندما سمع عبد إبراهيم كلامهم أنه سجد للرب إلى الأرض.","24:53":"وأخرج العبد آنية فضة وآنية ذهب وثيابا وأعطاها لرفقة, وأعطى تحفا لأخيها ولأمها.","24:54":"فأكل وشرب هو والرجال الذين معه وباتوا. ثم قاموا صباحا فقال: «اصرفوني إلى سيدي».","24:55":"فقال أخوها وأمها: «لتمكث الفتاة عندنا أياما أو عشرة, بعد ذلك تمضي».","24:56":"فقال لهم: «لا تعوقوني والرب قد أنجح طريقي. اصرفوني لأذهب إلى سيدي».","24:57":"فقالوا: «ندعو الفتاة ونسألها شفاها».","24:58":"فدعوا رفقة وقالوا لها: «هل تذهبين مع هذا الرجل؟» فقالت: «أذهب».","24:59":"فصرفوا رفقة أختهم ومرضعتها وعبد إبراهيم ورجاله.","24:60":"وباركوا رفقة وقالوا لها: «أنت أختنا. صيري ألوف ربوات, وليرث نسلك باب مبغضيه».","24:61":"فقامت رفقة وفتياتها وركبن على الجمال وتبعن الرجل. فأخذ العبد رفقة ومضى.","24:62":"وكان إسحاق قد أتى من ورود بئر لحي رئي, إذ كان ساكنا في أرض الجنوب.","24:63":"وخرج إسحاق ليتأمل في الحقل عند إقبال المساء, فرفع عينيه ونظر وإذا جمال مقبلة.","24:64":"ورفعت رفقة عينيها فرأت إسحاق فنزلت عن الجمل.","24:65":"وقالت للعبد: «من هذا الرجل الماشي في الحقل للقائنا؟» فقال العبد: «هو سيدي». فأخذت البرقع وتغطت.","24:66":"ثم حدث العبد إسحاق بكل الأمور التي صنع,","24:67":"فأدخلها إسحاق إلى خباء سارة أمه, وأخذ رفقة فصارت له زوجة وأحبها. فتعزى إسحاق بعد موت أمه.","25:1":"وعاد إبراهيم فأخذ زوجة اسمها قطورة,","25:2":"فولدت له: زمران ويقشان ومدان ومديان ويشباق وشوحا.","25:3":"وولد يقشان: شبا وددان. وكان بنو ددان: أشوريم ولطوشيم ولأميم.","25:4":"وبنو مديان: عيفة وعفر وحنوك وأبيداع وألدعة. جميع هؤلاء بنو قطورة.","25:5":"وأعطى إبراهيم إسحاق كل ما كان له.","25:6":"وأما بنو السراري اللواتي كانت لإبراهيم فأعطاهم إبراهيم عطايا, وصرفهم عن إسحاق ابنه شرقا إلى أرض المشرق, وهو بعد حي.","25:7":"وهذه أيام سني حياة إبراهيم التي عاشها: مئة وخمس وسبعون سنة.","25:8":"وأسلم إبراهيم روحه ومات بشيبة صالحة, شيخا وشبعان أياما, وانضم إلى قومه.","25:9":"ودفنه إسحاق وإسماعيل ابناه في مغارة المكفيلة في حقل عفرون بن صوحر الحثي الذي أمام ممرا,","25:10":"الحقل الذي اشتراه إبراهيم من بني حث. هناك دفن إبراهيم وسارة امرأته.","25:11":"وكان بعد موت إبراهيم أن الله بارك إسحاق ابنه. وسكن إسحاق عند بئر لحي رئي.","25:12":"وهذه مواليد إسماعيل بن إبراهيم, الذي ولدته هاجر المصرية جارية سارة لإبراهيم.","25:13":"وهذه أسماء بني إسماعيل بأسمائهم حسب مواليدهم: نبايوت بكر إسماعيل, وقيدار, وأدبئيل ومبسام","25:14":"ومشماع ودومة ومسا","25:15":"وحدار وتيما ويطور ونافيش وقدمة.","25:16":"هؤلاء هم بنو إسماعيل, وهذه أسماؤهم بديارهم وحصونهم. اثنا عشر رئيسا حسب قبائلهم.","25:17":"وهذه سنو حياة إسماعيل: مئة وسبع وثلاثون سنة, وأسلم روحه ومات وانضم إلى قومه.","25:18":"وسكنوا من حويلة إلى شور التي أمام مصر حينما تجيء نحو أشور. أمام جميع إخوته نزل.","25:19":"وهذه مواليد إسحاق بن إبراهيم: ولد إبراهيم إسحاق.","25:20":"وكان إسحاق ابن أربعين سنة لما اتخذ لنفسه زوجة, رفقة بنت بتوئيل الأرامي, أخت لابان الأرامي من فدان أرام.","25:21":"وصلى إسحاق إلى الرب لأجل امرأته لأنها كانت عاقرا, فاستجاب له الرب, فحبلت رفقة امرأته.","25:22":"وتزاحم الولدان في بطنها, فقالت: «إن كان هكذا فلماذا أنا؟» فمضت لتسأل الرب.","25:23":"فقال لها الرب: «في بطنك أمتان, ومن أحشائك يفترق شعبان: شعب يقوى على شعب, وكبير يستعبد لصغير».","25:24":"فلما كملت أيامها لتلد إذا في بطنها توأمان.","25:25":"فخرج ألأول أحمر, كله كفروة شعر, فدعوا اسمه «عيسو».","25:26":"وبعد ذلك خرج أخوه ويده قابضة بعقب عيسو, فدعي اسمه «يعقوب». وكان إسحاق ابن ستين سنة لما ولدتهما.","25:27":"فكبر الغلامان, وكان عيسو إنسانا يعرف الصيد, إنسان البرية, ويعقوب إنسانا كاملا يسكن الخيام.","25:28":"فأحب إسحاق عيسو لأن في فمه صيدا, وأما رفقة فكانت تحب يعقوب.","25:29":"وطبخ يعقوب طبيخا, فأتى عيسو من الحقل وهو قد أعيا.","25:30":"فقال عيسو ليعقوب: «أطعمني من هذا الأحمر لأني قد أعييت». لذلك دعي اسمه «أدوم».","25:31":"فقال يعقوب: «بعني اليوم بكوريتك».","25:32":"فقال عيسو: «ها أنا ماض إلى الموت, فلماذا لي بكورية؟»","25:33":"فقال يعقوب: «احلف لي اليوم». فحلف له, فباع بكوريته ليعقوب.","25:34":"فأعطى يعقوب عيسو خبزا وطبيخ عدس, فأكل وشرب وقام ومضى. فاحتقر عيسو البكورية.","26:1":"وكان في الأرض جوع غير الجوع الأول الذي كان في أيام إبراهيم, فذهب إسحاق إلى أبيمالك ملك الفلسطينيين, إلى جرار.","26:2":"وظهر له الرب وقال: «لا تنزل إلى مصر. اسكن في الأرض التي أقول لك.","26:3":"تغرب في هذه الأرض فأكون معك وأباركك, لأني لك ولنسلك أعطي جميع هذه البلاد, وأفي بالقسم الذي أقسمت لإبراهيم أبيك.","26:4":"وأكثر نسلك كنجوم السماء, وأعطي نسلك جميع هذه البلاد, وتتبارك في نسلك جميع أمم الأرض,","26:5":"من أجل أن إبراهيم سمع لقولي وحفظ ما يحفظ لي: أوامري وفرائضي وشرائعي».","26:6":"فأقام إسحاق في جرار.","26:7":"وسأله أهل المكان عن امرأته, فقال: «هي أختي». لأنه خاف أن يقول: «امرأتي» لعل أهل المكان: «يقتلونني من أجل رفقة» لأنها كانت حسنة المنظر.","26:8":"وحدث إذ طالت له الأيام هناك أن أبيمالك ملك الفلسطينيين أشرف من الكوة ونظر, وإذا إسحاق يلاعب رفقة امرأته.","26:9":"فدعا أبيمالك إسحاق وقال: «إنما هي امرأتك! فكيف قلت: هي أختي؟» فقال له إسحاق: «لأني قلت: لعلي أموت بسببها».","26:10":"فقال أبيمالك: «ما هذا الذي صنعت بنا؟ لولا قليل لاضطجع أحد الشعب مع امرأتك فجلبت علينا ذنبا».","26:11":"فأوصى أبيمالك جميع الشعب قائلا: «الذي يمس هذا الرجل أو امرأته موتا يموت».","26:12":"وزرع إسحاق في تلك الأرض فأصاب في تلك السنة مئة ضعف, وباركه الرب.","26:13":"فتعاظم الرجل وكان يتزايد في التعاظم حتى صار عظيما جدا.","26:14":"فكان له مواش من الغنم ومواش من البقر وعبيد كثيرون. فحسده الفلسطينيون.","26:15":"وجميع الآبار, التي حفرها عبيد أبيه في أيام إبراهيم أبيه, طمها الفلسطينيون وملأوها ترابا.","26:16":"وقال أبيمالك لإسحاق: «اذهب من عندنا لأنك صرت أقوى منا جدا».","26:17":"فمضى إسحاق من هناك, ونزل في وادي جرار وأقام هناك.","26:18":"فعاد إسحاق ونبش آبار الماء التي حفروها في أيام إبراهيم أبيه, وطمها الفلسطينيون بعد موت أبيه, ودعاها بأسماء كالأسماء التي دعاها بها أبوه.","26:19":"وحفر عبيد إسحاق في الوادي فوجدوا هناك بئر ماء حي.","26:20":"فخاصم رعاة جرار رعاة إسحاق قائلين: «لنا الماء». فدعا اسم البئر «عسق» لأنهم نازعوه.","26:21":"ثم حفروا بئرا أخرى وتخاصموا عليها أيضا, فدعا اسمها «سطنة».","26:22":"ثم نقل من هناك وحفر بئرا أخرى ولم يتخاصموا عليها, فدعا اسمها «رحوبوت», وقال: «إنه الآن قد أرحب لنا الرب وأثمرنا في الأرض».","26:23":"ثم صعد من هناك إلى بئر سبع.","26:24":"فظهر له الرب في تلك الليلة وقال: «أنا إله إبراهيم أبيك. لا تخف لأني معك, وأباركك وأكثر نسلك من أجل إبراهيم عبدي».","26:25":"فبنى هناك مذبحا ودعا باسم الرب. ونصب هناك خيمته, وحفر هناك عبيد إسحاق بئرا.","26:26":"وذهب إليه من جرار أبيمالك وأحزات من أصحابه وفيكول رئيس جيشه.","26:27":"فقال لهم إسحاق: «ما بالكم أتيتم إلي وأنتم قد أبغضتموني وصرفتموني من عندكم؟»","26:28":"فقالوا: «إننا قد رأينا أن الرب كان معك, فقلنا: ليكن بيننا حلف, بيننا وبينك, ونقطع معك عهدا:","26:29":"أن لا تصنع بنا شرا, كما لم نمسك وكما لم نصنع بك إلا خيرا وصرفناك بسلام. أنت الآن مبارك الرب».","26:30":"فصنع لهم ضيافة, فأكلوا وشربوا.","26:31":"ثم بكروا في الغد وحلفوا بعضهم لبعض, وصرفهم إسحاق. فمضوا من عنده بسلام.","26:32":"وحدث في ذلك اليوم أن عبيد إسحاق جاءوا وأخبروه عن البئر التي حفروا, وقالوا له: «قد وجدنا ماء».","26:33":"فدعاها «شبعة», لذلك اسم المدينة بئر سبع إلى هذا اليوم.","26:34":"ولما كان عيسو ابن أربعين سنة اتخذ زوجة: يهوديت ابنة بيري الحثي, وبسمة ابنة إيلون الحثي.","26:35":"فكانتا مرارة نفس لإسحاق ورفقة.","27:1":"وحدث لما شاخ إسحاق وكلت عيناه عن النظر, أنه دعا عيسو ابنه الأكبر وقال له: «يا ابني». فقال له: «هأنذا».","27:2":"فقال: «إنني قد شخت ولست أعرف يوم وفاتي.","27:3":"فالآن خذ عدتك: جعبتك وقوسك, واخرج إلى البرية وتصيد لي صيدا,","27:4":"واصنع لي أطعمة كما أحب, وأتني بها لآكل حتى تباركك نفسي قبل أن أموت».","27:5":"وكانت رفقة سامعة إذ تكلم إسحاق مع عيسو ابنه. فذهب عيسو إلى البرية كي يصطاد صيدا ليأتي به.","27:6":"وأما رفقة فكلمت يعقوب ابنها قائلة: «إني قد سمعت أباك يكلم عيسو أخاك قائلا:","27:7":"ائتني بصيد واصنع لي أطعمة لآكل وأباركك أمام الرب قبل وفاتي.","27:8":"فالآن يا ابني اسمع لقولي في ما أنا آمرك به:","27:9":"اذهب إلى الغنم وخذ لي من هناك جديين جيدين من المعزى, فأصنعهما أطعمة لأبيك كما يحب,","27:10":"فتحضرها إلى أبيك ليأكل حتى يباركك قبل وفاته».","27:11":"فقال يعقوب لرفقة أمه: «هوذا عيسو أخي رجل أشعر وأنا رجل أملس.","27:12":"ربما يجسني أبي فأكون في عينيه كمتهاون, وأجلب على نفسي لعنة لا بركة».","27:13":"فقالت له أمه: «لعنتك علي يا ابني. اسمع لقولي فقط واذهب خذ لي».","27:14":"فذهب وأخذ وأحضر لأمه, فصنعت أمه أطعمة كما كان أبوه يحب.","27:15":"وأخذت رفقة ثياب عيسو ابنها الأكبر الفاخرة التي كانت عندها في البيت وألبست يعقوب ابنها الأصغر,","27:16":"وألبست يديه وملاسة عنقه جلود جديي المعزى.","27:17":"وأعطت الأطعمة والخبز التي صنعت في يد يعقوب ابنها.","27:18":"فدخل إلى أبيه وقال: «يا أبي». فقال: «هأنذا. من أنت يا ابني؟»","27:19":"فقال يعقوب لأبيه: «أنا عيسو بكرك. قد فعلت كما كلمتني. قم اجلس وكل من صيدي لكي تباركني نفسك».","27:20":"فقال إسحاق لابنه: «ما هذا الذي أسرعت لتجد يا ابني؟» فقال: «إن الرب إلهك قد يسر لي».","27:21":"فقال إسحاق ليعقوب: «تقدم لأجسك يا ابني. أأنت هو ابني عيسو أم لا؟».","27:22":"فتقدم يعقوب إلى إسحاق أبيه, فجسه وقال: «الصوت صوت يعقوب, ولكن اليدين يدا عيسو».","27:23":"ولم يعرفه لأن يديه كانتا مشعرتين كيدي عيسو أخيه, فباركه.","27:24":"وقال: «هل أنت هو ابني عيسو؟» فقال: «أنا هو».","27:25":"فقال: «قدم لي لآكل من صيد ابني حتى تباركك نفسي». فقدم له فأكل, وأحضر له خمرا فشرب.","27:26":"فقال له إسحاق أبوه: «تقدم وقبلني يا ابني».","27:27":"فتقدم وقبله, فشم رائحة ثيابه وباركه, وقال: «انظر! رائحة ابني كرائحة حقل قد باركه الرب.","27:28":"فليعطك الله من ندى السماء ومن دسم الأرض. وكثرة حنطة وخمر.","27:29":"ليستعبد لك شعوب, وتسجد لك قبائل. كن سيدا لإخوتك, وليسجد لك بنو أمك. ليكن لاعنوك ملعونين, ومباركوك مباركين».","27:30":"وحدث عندما فرغ إسحاق من بركة يعقوب, ويعقوب قد خرج من لدن إسحاق أبيه, أن عيسو أخاه أتى من صيده,","27:31":"فصنع هو أيضا أطعمة ودخل بها إلى أبيه وقال لأبيه: «ليقم أبي ويأكل من صيد ابنه حتى تباركني نفسك».","27:32":"فقال له إسحاق أبوه: «من أنت؟» فقال: «أنا ابنك بكرك عيسو».","27:33":"فارتعد إسحاق ارتعادا عظيما جدا وقال: «فمن هو الذي اصطاد صيدا وأتى به إلي فأكلت من الكل قبل أن تجيء, وباركته؟ نعم, ويكون مباركا».","27:34":"فعندما سمع عيسو كلام أبيه صرخ صرخة عظيمة ومرة جدا, وقال لأبيه: «باركني أنا أيضا يا أبي».","27:35":"فقال: «قد جاء أخوك بمكر وأخذ بركتك».","27:36":"فقال: «ألا إن اسمه دعي يعقوب, فقد تعقبني الآن مرتين! أخذ بكوريتي, وهوذا الآن قد أخذ بركتي». ثم قال: «أما أبقيت لي بركة؟»","27:37":"فأجاب إسحاق وقال لعيسو: «إني قد جعلته سيدا لك, ودفعت إليه جميع إخوته عبيدا, وعضدته بحنطة وخمر. فماذا أصنع إليك يا ابني؟»","27:38":"فقال عيسو لأبيه: «ألك بركة واحدة فقط يا أبي؟ باركني أنا أيضا يا أبي». ورفع عيسو صوته وبكى.","27:39":"فأجاب إسحاق أبوه: «هوذا بلا دسم الأرض يكون مسكنك, وبلا ندى السماء من فوق.","27:40":"وبسيفك تعيش, ولأخيك تستعبد, ولكن يكون حينما تجمح أنك تكسر نيره عن عنقك».","27:41":"فحقد عيسو على يعقوب من أجل البركة التي باركه بها أبوه. وقال عيسو في قلبه: «قربت أيام مناحة أبي, فأقتل يعقوب أخي».","27:42":"فأخبرت رفقة بكلام عيسو ابنها الأكبر, فأرسلت ودعت يعقوب ابنها الأصغر وقالت له: «هوذا عيسو أخوك متسل من جهتك بأنه يقتلك.","27:43":"فالآن يا ابني اسمع لقولي, وقم اهرب إلى أخي لابان إلى حاران,","27:44":"وأقم عنده أياما قليلة حتى يرتد سخط أخيك.","27:45":"حتى يرتد غضب أخيك عنك, وينسى ما صنعت به. ثم أرسل فآخذك من هناك. لماذا أعدم اثنيكما في يوم واحد؟».","27:46":"وقالت رفقة لإسحاق: «مللت حياتي من أجل بنات حث. إن كان يعقوب يأخذ زوجة من بنات حث مثل هؤلاء من بنات الأرض, فلماذا لي حياة؟».","28:1":"فدعا إسحاق يعقوب وباركه, وأوصاه وقال له: «لا تأخذ زوجة من بنات كنعان.","28:2":"قم اذهب إلى فدان أرام, إلى بيت بتوئيل أبي أمك, وخذ لنفسك زوجة من هناك, من بنات لابان أخي أمك.","28:3":"والله القدير يباركك, ويجعلك مثمرا, ويكثرك فتكون جمهورا من الشعوب.","28:4":"ويعطيك بركة إبراهيم لك ولنسلك معك, لترث أرض غربتك التي أعطاها الله لإبراهيم».","28:5":"فصرف إسحاق يعقوب فذهب إلى فدان أرام, إلى لابان بن بتوئيل الأرامي, أخي رفقة أم يعقوب وعيسو.","28:6":"فلما رأى عيسو أن إسحاق بارك يعقوب وأرسله إلى فدان أرام ليأخذ لنفسه من هناك زوجة, إذ باركه وأوصاه قائلا: «لا تأخذ زوجة من بنات كنعان».","28:7":"وأن يعقوب سمع لأبيه وأمه وذهب إلى فدان أرام,.","28:8":"رأى عيسو أن بنات كنعان شريرات في عيني إسحاق أبيه,","28:9":"فذهب عيسو إلى إسماعيل وأخذ محلة بنت إسماعيل بن إبراهيم, أخت نبايوت, زوجة له على نسائه.","28:10":"فخرج يعقوب من بئر سبع وذهب نحو حاران.","28:11":"وصادف مكانا وبات هناك لأن الشمس كانت قد غابت, وأخذ من حجارة المكان ووضعه تحت رأسه, فاضطجع في ذلك المكان.","28:12":"ورأى حلما, وإذا سلم منصوبة على الأرض ورأسها يمس السماء, وهوذا ملائكة الله صاعدة ونازلة عليها.","28:13":"وهوذا الرب واقف عليها, فقال: «أنا الرب إله إبراهيم أبيك وإله إسحاق. الأرض التي أنت مضطجع عليها أعطيها لك ولنسلك.","28:14":"ويكون نسلك كتراب الأرض, وتمتد غربا وشرقا وشمالا وجنوبا, ويتبارك فيك وفي نسلك جميع قبائل الأرض.","28:15":"وها أنا معك, وأحفظك حيثما تذهب, وأردك إلى هذه الأرض, لأني لا أتركك حتى أفعل ما كلمتك به».","28:16":"فاستيقظ يعقوب من نومه وقال: «حقا إن الرب في هذا المكان وأنا لم أعلم!».","28:17":"وخاف وقال: «ما أرهب هذا المكان! ما هذا إلا بيت الله, وهذا باب السماء».","28:18":"وبكر يعقوب في الصباح وأخذ الحجر الذي وضعه تحت رأسه وأقامه عمودا, وصب زيتا على رأسه.","28:19":"ودعا اسم ذلك المكان «بيت إيل», ولكن اسم المدينة أولا كان لوز.","28:20":"ونذر يعقوب نذرا قائلا: «إن كان الله معي, وحفظني في هذا الطريق الذي أنا سائر فيه, وأعطاني خبزا لآكل وثيابا لألبس,","28:21":"ورجعت بسلام إلى بيت أبي, يكون الرب لي إلها,","28:22":"وهذا الحجر الذي أقمته عمودا يكون بيت الله, وكل ما تعطيني فإني أعشره لك».","29:1":"ثم رفع يعقوب رجليه وذهب إلى أرض بني المشرق.","29:2":"ونظر وإذا في الحقل بئر وهناك ثلاثة قطعان غنم رابضة عندها, لأنهم كانوا من تلك البئر يسقون القطعان, والحجر على فم البئر كان كبيرا.","29:3":"فكان يجتمع إلى هناك جميع القطعان فيدحرجون الحجر عن فم البئر ويسقون الغنم, ثم يردون الحجر على فم البئر إلى مكانه.","29:4":"فقال لهم يعقوب: «يا إخوتي, من أين أنتم؟» فقالوا: «نحن من حاران».","29:5":"فقال لهم: «هل تعرفون لابان ابن ناحور؟» فقالوا: «نعرفه».","29:6":"فقال لهم: «هل له سلامة؟» فقالوا: «له سلامة. وهوذا راحيل ابنته آتية مع الغنم».","29:7":"فقال: «هوذا النهار بعد طويل. ليس وقت اجتماع المواشي. اسقوا الغنم واذهبوا ارعوا».","29:8":"فقالوا: «لا نقدر حتى تجتمع جميع القطعان ويدحرجوا الحجر عن فم البئر, ثم نسقي الغنم».","29:9":"وإذ هو بعد يتكلم معهم أتت راحيل مع غنم أبيها, لأنها كانت ترعى.","29:10":"فكان لما أبصر يعقوب راحيل بنت لابان خاله, وغنم لابان خاله, أن يعقوب تقدم ودحرج الحجر عن فم البئر وسقى غنم لابان خاله.","29:11":"وقبل يعقوب راحيل ورفع صوته وبكى.","29:12":"وأخبر يعقوب راحيل أنه أخو أبيها, وأنه ابن رفقة, فركضت وأخبرت أباها.","29:13":"فكان حين سمع لابان خبر يعقوب ابن أخته أنه ركض للقائه وعانقه وقبله وأتى به إلى بيته. فحدث لابان بجميع هذه الأمور.","29:14":"فقال له لابان: «إنما أنت عظمي ولحمي». فأقام عنده شهرا من الزمان.","29:15":"ثم قال لابان ليعقوب: «ألأنك أخي تخدمني مجانا؟ أخبرني ما أجرتك».","29:16":"وكان للابان ابنتان, اسم الكبرى ليئة واسم الصغرى راحيل.","29:17":"وكانت عينا ليئة ضعيفتين, وأما راحيل فكانت حسنة الصورة وحسنة المنظر.","29:18":"وأحب يعقوب راحيل, فقال: «أخدمك سبع سنين براحيل ابنتك الصغرى».","29:19":"فقال لابان: «أن أعطيك إياها أحسن من أن أعطيها لرجل آخر. أقم عندي».","29:20":"فخدم يعقوب براحيل سبع سنين, وكانت في عينيه كأيام قليلة بسبب محبته لها.","29:21":"ثم قال يعقوب للابان: «أعطني امرأتي لأن أيامي قد كملت, فأدخل عليها».","29:22":"فجمع لابان جميع أهل المكان وصنع وليمة.","29:23":"وكان في المساء أنه أخذ ليئة ابنته وأتى بها إليه, فدخل عليها.","29:24":"وأعطى لابان زلفة جاريته لليئة ابنته جارية.","29:25":"وفي الصباح إذا هي ليئة, فقال للابان: «ما هذا الذي صنعت بي؟ أليس براحيل خدمت عندك؟ فلماذا خدعتني؟».","29:26":"فقال لابان: «لا يفعل هكذا في مكاننا أن تعطى الصغيرة قبل البكر.","29:27":"أكمل أسبوع هذه, فنعطيك تلك أيضا, بالخدمة التي تخدمني أيضا سبع سنين أخر».","29:28":"ففعل يعقوب هكذا. فأكمل أسبوع هذه, فأعطاه راحيل ابنته زوجة له.","29:29":"وأعطى لابان راحيل ابنته بلهة جاريته جارية لها.","29:30":"فدخل على راحيل أيضا, وأحب أيضا راحيل أكثر من ليئة. وعاد فخدم عنده سبع سنين أخر.","29:31":"ورأى الرب أن ليئة مكروهة ففتح رحمها, وأما راحيل فكانت عاقرا.","29:32":"فحبلت ليئة وولدت ابنا ودعت اسمه «رأوبين», لأنها قالت: «إن الرب قد نظر إلى مذلتي. إنه الآن يحبني رجلي».","29:33":"وحبلت أيضا وولدت ابنا, وقالت: «إن الرب قد سمع أني مكروهة فأعطاني هذا أيضا». فدعت اسمه «شمعون».","29:34":"وحبلت أيضا وولدت ابنا, وقالت: «الآن هذه المرة يقترن بي رجلي, لأني ولدت له ثلاثة بنين». لذلك دعي اسمه «لاوي».","29:35":"وحبلت أيضا وولدت ابنا وقالت: «هذه المرة أحمد الرب». لذلك دعت اسمه «يهوذا». ثم توقفت عن الولادة.","30:1":"فلما رأت راحيل أنها لم تلد ليعقوب, غارت راحيل من أختها, وقالت ليعقوب: «هب لي بنين, وإلا فأنا أموت!».","30:2":"فحمي غضب يعقوب على راحيل وقال: «ألعلي مكان الله الذي منع عنك ثمرة البطن؟».","30:3":"فقالت: «هوذا جاريتي بلهة, ادخل عليها فتلد على ركبتي, وأرزق أنا أيضا منها بنين».","30:4":"فأعطته بلهة جاريتها زوجة, فدخل عليها يعقوب,","30:5":"فحبلت بلهة وولدت ليعقوب ابنا,","30:6":"فقالت راحيل: «قد قضى لي الله وسمع أيضا لصوتي وأعطاني ابنا». لذلك دعت اسمه «دانا».","30:7":"وحبلت أيضا بلهة جارية راحيل وولدت ابنا ثانيا ليعقوب,","30:8":"فقالت راحيل: «مصارعات الله قد صارعت أختي وغلبت». فدعت اسمه «نفتالي».","30:9":"ولما رأت ليئة أنها توقفت عن الولادة, أخذت زلفة جاريتها وأعطتها ليعقوب زوجة,","30:10":"فولدت زلفة جارية ليئة ليعقوب ابنا.","30:11":"فقالت ليئة: «بسعد». فدعت اسمه «جادا».","30:12":"وولدت زلفة جارية ليئة ابنا ثانيا ليعقوب,","30:13":"فقالت ليئة: «بغبطتي, لأنه تغبطني بنات». فدعت اسمه «أشير».","30:14":"ومضى رأوبين في أيام حصاد الحنطة فوجد لفاحا في الحقل وجاء به إلى ليئة أمه. فقالت راحيل لليئة: «أعطيني من لفاح ابنك».","30:15":"فقالت لها: «أقليل أنك أخذت رجلي فتأخذين لفاح ابني أيضا؟» فقالت راحيل: «إذا يضطجع معك الليلة عوضا عن لفاح ابنك».","30:16":"فلما أتى يعقوب من الحقل في المساء, خرجت ليئة لملاقاته وقالت: «إلي تجيء لأني قد استأجرتك بلفاح ابني». فاضطجع معها تلك الليلة.","30:17":"وسمع الله لليئة فحبلت وولدت ليعقوب ابنا خامسا.","30:18":"فقالت ليئة: «قد أعطاني الله أجرتي, لأني أعطيت جاريتي لرجلي». فدعت اسمه «يساكر».","30:19":"وحبلت أيضا ليئة وولدت ابنا سادسا ليعقوب,","30:20":"فقالت ليئة: «قد وهبني الله هبة حسنة. الآن يساكنني رجلي, لأني ولدت له ستة بنين». فدعت اسمه «زبولون».","30:21":"ثم ولدت ابنة ودعت اسمها «دينة».","30:22":"وذكر الله راحيل, وسمع لها الله وفتح رحمها,","30:23":"فحبلت وولدت ابنا فقالت: «قد نزع الله عاري».","30:24":"ودعت اسمه «يوسف» قائلة: «يزيدني الرب ابنا آخر».","30:25":"وحدث لما ولدت راحيل يوسف أن يعقوب قال للابان: «اصرفني لأذهب إلى مكاني وإلى أرضي.","30:26":"أعطني نسائي وأولادي الذين خدمتك بهم فأذهب, لأنك أنت تعلم خدمتي التي خدمتك».","30:27":"فقال له لابان: «ليتني أجد نعمة في عينيك. قد تفاءلت فباركني الرب بسببك».","30:28":"وقال: «عين لي أجرتك فأعطيك».","30:29":"فقال له: «أنت تعلم ماذا خدمتك, وماذا صارت مواشيك معي,","30:30":"لأن ما كان لك قبلي قليل فقد اتسع إلى كثير, وباركك الرب في أثري. والآن متى أعمل أنا أيضا لبيتي؟»","30:31":"فقال: «ماذا أعطيك؟» فقال يعقوب: «لا تعطيني شيئا. إن صنعت لي هذا الأمر أعود أرعى غنمك وأحفظها:","30:32":"أجتاز بين غنمك كلها اليوم, واعزل أنت منها كل شاة رقطاء وبلقاء, وكل شاة سوداء بين الخرفان, وبلقاء ورقطاء بين المعزى. فيكون مثل ذلك أجرتي.","30:33":"ويشهد في بري يوم غد إذا جئت من أجل أجرتي قدامك. كل ما ليس أرقط أو أبلق بين المعزى وأسود بين الخرفان فهو مسروق عندي».","30:34":"فقال لابان: «هوذا ليكن بحسب كلامك».","30:35":"فعزل في ذلك اليوم التيوس المخططة والبلقاء, وكل العناز الرقطاء والبلقاء, كل ما فيه بياض وكل أسود بين الخرفان, ودفعها إلى أيدي بنيه.","30:36":"وجعل مسيرة ثلاثة أيام بينه وبين يعقوب, وكان يعقوب يرعى غنم لابان الباقية.","30:37":"فأخذ يعقوب لنفسه قضبانا خضرا من لبنى ولوز ودلب, وقشر فيها خطوطا بيضا, كاشطا عن البياض الذي على القضبان.","30:38":"وأوقف القضبان التي قشرها في الأجران في مساقي الماء حيث كانت الغنم تجيء لتشرب, تجاه الغنم, لتتوحم عند مجيئها لتشرب.","30:39":"فتوحمت الغنم عند القضبان, وولدت الغنم مخططات ورقطا وبلقا.","30:40":"وأفرز يعقوب الخرفان وجعل وجوه الغنم إلى المخطط وكل أسود بين غنم لابان. وجعل له قطعانا وحده ولم يجعلها مع غنم لابان.","30:41":"وحدث كلما توحمت الغنم القوية أن يعقوب وضع القضبان أمام عيون الغنم في الأجران لتتوحم بين القضبان.","30:42":"وحين استضعفت الغنم لم يضعها, فصارت الضعيفة للابان والقوية ليعقوب.","30:43":"فاتسع الرجل كثيرا جدا, وكان له غنم كثير وجوار وعبيد وجمال وحمير.","31:1":"فسمع كلام بني لابان قائلين: «أخذ يعقوب كل ما كان لأبينا, ومما لأبينا صنع كل هذا المجد».","31:2":"ونظر يعقوب وجه لابان وإذا هو ليس معه كأمس وأول من أمس.","31:3":"وقال الرب ليعقوب: «ارجع إلى أرض آبائك وإلى عشيرتك, فأكون معك».","31:4":"فأرسل يعقوب ودعا راحيل وليئة إلى الحقل إلى غنمه,","31:5":"وقال لهما: «أنا أرى وجه أبيكما أنه ليس نحوي كأمس وأول من أمس. ولكن إله أبي كان معي.","31:6":"وأنتما تعلمان أني بكل قوتي خدمت أباكما,","31:7":"وأما أبوكما فغدر بي وغير أجرتي عشر مرات. لكن الله لم يسمح له أن يصنع بي شرا.","31:8":"إن قال هكذا: الرقط تكون أجرتك, ولدت كل الغنم رقطا. وإن قال هكذا: المخططة تكون أجرتك, ولدت كل الغنم مخططة.","31:9":"فقد سلب الله مواشي أبيكما وأعطاني.","31:10":"وحدث في وقت توحم الغنم أني رفعت عيني ونظرت في حلم, وإذا الفحول الصاعدة على الغنم مخططة ورقطاء ومنمرة.","31:11":"وقال لي ملاك الله في الحلم: يا يعقوب. فقلت: هأنذا.","31:12":"فقال: ارفع عينيك وانظر. جميع الفحول الصاعدة على الغنم مخططة ورقطاء ومنمرة, لأني قد رأيت كل ما يصنع بك لابان.","31:13":"أنا إله بيت إيل حيث مسحت عمودا, حيث نذرت لي نذرا. الآن قم اخرج من هذه الأرض وارجع إلى أرض ميلادك».","31:14":"فأجابت راحيل وليئة وقالتا له: «ألنا أيضا نصيب وميراث في بيت أبينا؟","31:15":"ألم نحسب منه أجنبيتين, لأنه باعنا وقد أكل أيضا ثمننا؟","31:16":"إن كل الغنى الذي سلبه الله من أبينا هو لنا ولأولادنا, فالآن كل ما قال لك الله افعل».","31:17":"فقام يعقوب وحمل أولاده ونساءه على الجمال,","31:18":"وساق كل مواشيه وجميع مقتناه الذي كان قد اقتنى: مواشي اقتنائه التي اقتنى في فدان أرام, ليجيء إلى إسحاق أبيه إلى أرض كنعان.","31:19":"وأما لابان فكان قد مضى ليجز غنمه, فسرقت راحيل أصنام أبيها.","31:20":"وخدع يعقوب قلب لابان الأرامي إذ لم يخبره بأنه هارب.","31:21":"فهرب هو وكل ما كان له, وقام وعبر النهر وجعل وجهه نحو جبل جلعاد.","31:22":"فأخبر لابان في اليوم الثالث بأن يعقوب قد هرب.","31:23":"فأخذ إخوته معه وسعى وراءه مسيرة سبعة أيام, فأدركه في جبل جلعاد.","31:24":"وأتى الله إلى لابان الأرامي في حلم الليل وقال له: «احترز من أن تكلم يعقوب بخير أو شر».","31:25":"فلحق لابان يعقوب, ويعقوب قد ضرب خيمته في الجبل. فضرب لابان مع إخوته في جبل جلعاد.","31:26":"وقال لابان ليعقوب: «ماذا فعلت, وقد خدعت قلبي, وسقت بناتي كسبايا السيف؟","31:27":"لماذا هربت خفية وخدعتني ولم تخبرني حتى أشيعك بالفرح والأغاني, بالدف والعود,","31:28":"ولم تدعني أقبل بني وبناتي؟ الآن بغباوة فعلت!","31:29":"في قدرة يدي أن أصنع بكم شرا, ولكن إله أبيكم كلمني البارحة قائلا: احترز من أن تكلم يعقوب بخير أو شر.","31:30":"والآن أنت ذهبت لأنك قد اشتقت إلى بيت أبيك, ولكن لماذا سرقت آلهتي؟».","31:31":"فأجاب يعقوب وقال للابان: «إني خفت لأني قلت لعلك تغتصب ابنتيك مني.","31:32":"الذي تجد آلهتك معه لا يعيش. قدام إخوتنا انظر ماذا معي وخذه لنفسك». ولم يكن يعقوب يعلم أن راحيل سرقتها.","31:33":"فدخل لابان خباء يعقوب وخباء ليئة وخباء الجاريتين ولم يجد. وخرج من خباء ليئة ودخل خباء راحيل.","31:34":"وكانت راحيل قد أخذت الأصنام ووضعتها في حداجة الجمل وجلست عليها. فجس لابان كل الخباء ولم يجد.","31:35":"وقالت لأبيها: «لا يغتظ سيدي أني لا أستطيع أن أقوم أمامك لأن علي عادة النساء». ففتش ولم يجد الأصنام.","31:36":"فاغتاظ يعقوب وخاصم لابان. وأجاب يعقوب وقال للابان: «ما جرمي؟ ما خطيتي حتى حميت ورائي؟","31:37":"إنك جسست جميع أثاثي. ماذا وجدت من جميع أثاث بيتك؟ ضعه ههنا قدام إخوتي وإخوتك, فلينصفوا بيننا الاثنين.","31:38":"الآن عشرين سنة أنا معك. نعاجك وعنازك لم تسقط, وكباش غنمك لم آكل.","31:39":"فريسة لم أحضر إليك. أنا كنت أخسرها. من يدي كنت تطلبها. مسروقة النهار أو مسروقة الليل.","31:40":"كنت في النهار يأكلني الحر وفي الليل الجليد, وطار نومي من عيني.","31:41":"الآن لي عشرون سنة في بيتك. خدمتك أربع عشرة سنة بابنتيك, وست سنين بغنمك. وقد غيرت أجرتي عشر مرات.","31:42":"لولا أن إله أبي إله إبراهيم وهيبة إسحاق كان معي, لكنت الآن قد صرفتني فارغا. مشقتي وتعب يدي قد نظر الله, فوبخك البارحة».","31:43":"فأجاب لابان وقال ليعقوب: «البنات بناتي, والبنون بني, والغنم غنمي, وكل ما أنت ترى فهو لي. فبناتي ماذا أصنع بهن اليوم أو بأولادهن الذين ولدن؟","31:44":"فالآن هلم نقطع عهدا أنا وأنت, فيكون شاهدا بيني وبينك».","31:45":"فأخذ يعقوب حجرا وأوقفه عمودا,","31:46":"وقال يعقوب لإخوته: «التقطوا حجارة». فأخذوا حجارة وعملوا رجمة وأكلوا هناك على الرجمة.","31:47":"ودعاها لابان «يجر سهدوثا» وأما يعقوب فدعاها «جلعيد».","31:48":"وقال لابان: «هذه الرجمة هي شاهدة بيني وبينك اليوم». لذلك دعي اسمها «جلعيد».","31:49":"و «المصفاة», لأنه قال: «ليراقب الرب بيني وبينك حينما نتوارى بعضنا عن بعض.","31:50":"إنك لا تذل بناتي, ولا تأخذ نساء على بناتي. ليس إنسان معنا. انظر, الله شاهد بيني وبينك».","31:51":"وقال لابان ليعقوب: «هوذا هذه الرجمة, وهوذا العمود الذي وضعت بيني وبينك.","31:52":"شاهدة هذه الرجمة وشاهد العمود أني لا أتجاوز هذه الرجمة إليك, وأنك لا تتجاوز هذه الرجمة وهذا العمود إلي للشر.","31:53":"إله إبراهيم وآلهة ناحور, آلهة أبيهما, يقضون بيننا». وحلف يعقوب بهيبة أبيه إسحاق.","31:54":"وذبح يعقوب ذبيحة في الجبل ودعا إخوته ليأكلوا طعاما, فأكلوا طعاما وباتوا في الجبل.","31:55":"ثم بكر لابان صباحا وقبل بنيه وبناته وباركهم ومضى. ورجع لابان إلى مكانه.","32:1":"وأما يعقوب فمضى في طريقه ولاقاه ملائكة الله.","32:2":"وقال يعقوب إذ رآهم: «هذا جيش الله!». فدعا اسم ذلك المكان «محنايم».","32:3":"وأرسل يعقوب رسلا قدامه إلى عيسو أخيه إلى أرض سعير بلاد أدوم,","32:4":"وأمرهم قائلا: «هكذا تقولون لسيدي عيسو: هكذا قال عبدك يعقوب: تغربت عند لابان ولبثت إلى الآن.","32:5":"وقد صار لي بقر وحمير وغنم وعبيد وإماء. وأرسلت لأخبر سيدي لكي أجد نعمة في عينيك».","32:6":"فرجع الرسل إلى يعقوب قائلين: «أتينا إلى أخيك, إلى عيسو, وهو أيضا قادم للقائك, وأربع مئة رجل معه».","32:7":"فخاف يعقوب جدا وضاق به الأمر, فقسم القوم الذين معه والغنم والبقر والجمال إلى جيشين.","32:8":"وقال: «إن جاء عيسو إلى الجيش الواحد وضربه, يكون الجيش الباقي ناجيا».","32:9":"وقال يعقوب: «يا إله أبي إبراهيم وإله أبي إسحاق, الرب الذي قال لي: ارجع إلى أرضك وإلى عشيرتك فأحسن إليك.","32:10":"صغير أنا عن جميع ألطافك وجميع الأمانة التي صنعت إلى عبدك. فإني بعصاي عبرت هذا الأردن, والآن قد صرت جيشين.","32:11":"نجني من يد أخي, من يد عيسو, لأني خائف منه أن يأتي ويضربني الأم مع البنين.","32:12":"وأنت قد قلت: إني أحسن إليك وأجعل نسلك كرمل البحر الذي لا يعد للكثرة».","32:13":"وبات هناك تلك الليلة وأخذ مما أتى بيده هدية لعيسو أخيه:","32:14":"مئتي عنز وعشرين تيسا, مئتي نعجة وعشرين كبشا,","32:15":"ثلاثين ناقة مرضعة وأولادها, أربعين بقرة وعشرة ثيران, عشرين أتانا وعشرة حمير,","32:16":"ودفعها إلى يد عبيده قطيعا قطيعا على حدة. وقال لعبيده: «اجتازوا قدامي واجعلوا فسحة بين قطيع وقطيع».","32:17":"وأمر الأول قائلا: «إذا صادفك عيسو أخي وسألك قائلا: لمن أنت؟ وإلى أين تذهب؟ ولمن هذا الذي قدامك؟","32:18":"تقول: لعبدك يعقوب. هو هدية مرسلة لسيدي عيسو, وها هو أيضا وراءنا».","32:19":"وأمر أيضا الثاني والثالث وجميع السائرين وراء القطعان: «بمثل هذا الكلام تكلمون عيسو حينما تجدونه,","32:20":"وتقولون: هوذا عبدك يعقوب أيضا وراءنا». لأنه قال: «أستعطف وجهه بالهدية السائرة أمامي, وبعد ذلك أنظر وجهه, عسى أن يرفع وجهي».","32:21":"فاجتازت الهدية قدامه, وأما هو فبات تلك الليلة في المحلة.","32:22":"ثم قام في تلك الليلة وأخذ امرأتيه وجاريتيه وأولاده الأحد عشر وعبر مخاضة يبوق.","32:23":"أخذهم وأجازهم الوادي, وأجاز ما كان له.","32:24":"فبقي يعقوب وحده, وصارعه إنسان حتى طلوع الفجر.","32:25":"ولما رأى أنه لا يقدر عليه, ضرب حق فخذه, فانخلع حق فخذ يعقوب في مصارعته معه.","32:26":"وقال: «أطلقني, لأنه قد طلع الفجر». فقال: «لا أطلقك إن لم تباركني».","32:27":"فقال له: «ما اسمك؟» فقال: «يعقوب».","32:28":"فقال: «لا يدعى اسمك في ما بعد يعقوب بل إسرائيل, لأنك جاهدت مع الله والناس وقدرت».","32:29":"وسأل يعقوب وقال: «أخبرني باسمك». فقال: «لماذا تسأل عن اسمي؟» وباركه هناك.","32:30":"فدعا يعقوب اسم المكان «فنيئيل» قائلا: «لأني نظرت الله وجها لوجه, ونجيت نفسي».","32:31":"وأشرقت له الشمس إذ عبر فنوئيل وهو يخمع على فخذه.","32:32":"لذلك لا يأكل بنو إسرائيل عرق النسا الذي على حق الفخذ إلى هذا اليوم, لأنه ضرب حق فخذ يعقوب على عرق النسا.","33:1":"ورفع يعقوب عينيه ونظر وإذا عيسو مقبل ومعه أربع مئة رجل, فقسم الأولاد على ليئة وعلى راحيل وعلى الجاريتين.","33:2":"ووضع الجاريتين وأولادهما أولا, وليئة وأولادها وراءهم, وراحيل ويوسف أخيرا.","33:3":"وأما هو فاجتاز قدامهم وسجد إلى الأرض سبع مرات حتى اقترب إلى أخيه.","33:4":"فركض عيسو للقائه وعانقه ووقع على عنقه وقبله, وبكيا.","33:5":"ثم رفع عينيه وأبصر النساء والأولاد وقال: «ما هؤلاء منك؟» فقال: «الأولاد الذين أنعم الله بهم على عبدك».","33:6":"فاقتربت الجاريتان هما وأولادهما وسجدتا.","33:7":"ثم اقتربت ليئة أيضا وأولادها وسجدوا. وبعد ذلك اقترب يوسف وراحيل وسجدا.","33:8":"فقال: «ماذا منك كل هذا الجيش الذي صادفته؟» فقال: «لأجد نعمة في عيني سيدي».","33:9":"فقال عيسو: «لي كثير, يا أخي. ليكن لك الذي لك».","33:10":"فقال يعقوب: «لا. إن وجدت نعمة في عينيك تأخذ هديتي من يدي, لأني رأيت وجهك كما يرى وجه الله, فرضيت علي.","33:11":"خذ بركتي التي أتي بها إليك, لأن الله قد أنعم علي ولي كل شيء». وألح عليه فأخذ.","33:12":"ثم قال: «لنرحل ونذهب, وأذهب أنا قدامك».","33:13":"فقال له: «سيدي عالم أن الأولاد رخصة, والغنم والبقر التي عندي مرضعة, فإن استكدوها يوما واحدا ماتت كل الغنم.","33:14":"ليجتز سيدي قدام عبده, وأنا أستاق على مهلي في إثر الأملاك التي قدامي, وفي إثر الأولاد, حتى أجيء إلى سيدي إلى سعير».","33:15":"فقال عيسو: «أترك عندك من القوم الذين معي». فقال: «لماذا؟ دعني أجد نعمة في عيني سيدي».","33:16":"فرجع عيسو ذلك اليوم في طريقه إلى سعير.","33:17":"وأما يعقوب فارتحل إلى سكوت, وبنى لنفسه بيتا, وصنع لمواشيه مظلات. لذلك دعا اسم المكان «سكوت».","33:18":"ثم أتى يعقوب سالما إلى مدينة شكيم التي في أرض كنعان, حين جاء من فدان أرام. ونزل أمام المدينة.","33:19":"وابتاع قطعة الحقل التي نصب فيها خيمته من يد بني حمور أبي شكيم بمئة قسيطة.","33:20":"وأقام هناك مذبحا ودعاه «إيل إله إسرائيل».","34:1":"وخرجت دينة ابنة ليئة التي ولدتها ليعقوب لتنظر بنات الأرض,","34:2":"فرآها شكيم ابن حمور الحوي رئيس الأرض, وأخذها واضطجع معها وأذلها.","34:3":"وتعلقت نفسه بدينة ابنة يعقوب, وأحب الفتاة ولاطف الفتاة.","34:4":"فكلم شكيم حمور أباه قائلا: «خذ لي هذه الصبية زوجة».","34:5":"وسمع يعقوب أنه نجس دينة ابنته. وأما بنوه فكانوا مع مواشيه في الحقل, فسكت يعقوب حتى جاءوا.","34:6":"فخرج حمور أبو شكيم إلى يعقوب ليتكلم معه.","34:7":"وأتى بنو يعقوب من الحقل حين سمعوا. وغضب الرجال واغتاظوا جدا لأنه صنع قباحة في إسرائيل بمضاجعة ابنة يعقوب, وهكذا لا يصنع.","34:8":"وتكلم حمور معهم قائلا: «شكيم ابني قد تعلقت نفسه بابنتكم. أعطوه إياها زوجة","34:9":"وصاهرونا. تعطوننا بناتكم, وتأخذون لكم بناتنا.","34:10":"وتسكنون معنا, وتكون الأرض قدامكم. اسكنوا واتجروا فيها وتملكوا بها».","34:11":"ثم قال شكيم لأبيها ولإخوتها: «دعوني أجد نعمة في أعينكم. فالذي تقولون لي أعطي.","34:12":"كثروا علي جدا مهرا وعطية, فأعطي كما تقولون لي. وأعطوني الفتاة زوجة».","34:13":"فأجاب بنو يعقوب شكيم وحمور أباه بمكر وتكلموا. لأنه كان قد نجس دينة أختهم,","34:14":"فقالوا لهما: «لا نستطيع أن نفعل هذا الأمر أن نعطي أختنا لرجل أغلف, لأنه عار لنا.","34:15":"غير أننا بهذا نواتيكم: إن صرتم مثلنا بختنكم كل ذكر.","34:16":"نعطيكم بناتنا ونأخذ لنا بناتكم, ونسكن معكم ونصير شعبا واحدا.","34:17":"وإن لم تسمعوا لنا, أن تختتنوا, نأخذ ابنتنا ونمضي».","34:18":"فحسن كلامهم في عيني حمور وفي عيني شكيم بن حمور.","34:19":"ولم يتأخر الغلام أن يفعل الأمر, لأنه كان مسرورا بابنة يعقوب. وكان أكرم جميع بيت أبيه.","34:20":"فأتى حمور وشكيم ابنه إلى باب مدينتهما, وكلما أهل مدينتهما قائلين:","34:21":"«هؤلاء القوم مسالمون لنا. فليسكنوا في الأرض ويتجروا فيها. وهوذا الأرض واسعة الطرفين أمامهم. نأخذ لنا بناتهم زوجات ونعطيهم بناتنا.","34:22":"غير أنه بهذا فقط يواتينا القوم على السكن معنا لنصير شعبا واحدا: بختننا كل ذكر كما هم مختونون.","34:23":"ألا تكون مواشيهم ومقتناهم وكل بهائمهم لنا؟ نواتيهم فقط فيسكنون معنا».","34:24":"فسمع لحمور وشكيم ابنه جميع الخارجين من باب المدينة, واختتن كل ذكر. كل الخارجين من باب المدينة.","34:25":"فحدث في اليوم الثالث إذ كانوا متوجعين أن ابني يعقوب, شمعون ولاوي أخوي دينة, أخذا كل واحد سيفه وأتيا على المدينة بأمن وقتلا كل ذكر.","34:26":"وقتلا حمور وشكيم ابنه بحد السيف, وأخذا دينة من بيت شكيم وخرجا.","34:27":"ثم أتى بنو يعقوب على القتلى ونهبوا المدينة, لأنهم نجسوا أختهم.","34:28":"غنمهم وبقرهم وحميرهم وكل ما في المدينة وما في الحقل أخذوه.","34:29":"وسبوا ونهبوا كل ثروتهم وكل أطفالهم, ونساءهم وكل ما في البيوت.","34:30":"فقال يعقوب لشمعون ولاوي: «كدرتماني بتكريهكما إياي عند سكان الأرض الكنعانيين والفرزيين, وأنا نفر قليل. فيجتمعون علي ويضربونني, فأبيد أنا وبيتي».","34:31":"فقالا: «أنظير زانية يفعل بأختنا؟».","35:1":"ثم قال الله ليعقوب: «قم اصعد إلى بيت إيل وأقم هناك, واصنع هناك مذبحا لله الذي ظهر لك حين هربت من وجه عيسو أخيك».","35:2":"فقال يعقوب لبيته ولكل من كان معه: «اعزلوا الآلهة الغريبة التي بينكم وتطهروا وأبدلوا ثيابكم.","35:3":"ولنقم ونصعد إلى بيت إيل, فأصنع هناك مذبحا لله الذي استجاب لي في يوم ضيقتي, وكان معي في الطريق الذي ذهبت فيه».","35:4":"فأعطوا يعقوب كل الآلهة الغريبة التي في أيديهم والأقراط التي في آذانهم, فطمرها يعقوب تحت البطمة التي عند شكيم.","35:5":"ثم رحلوا, وكان خوف الله على المدن التي حولهم, فلم يسعوا وراء بني يعقوب.","35:6":"فأتى يعقوب إلى لوز التي في أرض كنعان, وهي بيت إيل. هو وجميع القوم الذين معه.","35:7":"وبنى هناك مذبحا, ودعا المكان «إيل بيت إيل» لأنه هناك ظهر له الله حين هرب من وجه أخيه.","35:8":"وماتت دبورة مرضعة رفقة ودفنت تحت بيت إيل تحت البلوطة, فدعا اسمها «ألون باكوت».","35:9":"وظهر الله ليعقوب أيضا حين جاء من فدان أرام وباركه.","35:10":"وقال له الله: «اسمك يعقوب. لا يدعى اسمك فيما بعد يعقوب, بل يكون اسمك إسرائيل». فدعا اسمه «إسرائيل».","35:11":"وقال له الله: «أنا الله القدير. أثمر واكثر. أمة وجماعة أمم تكون منك, وملوك سيخرجون من صلبك.","35:12":"والأرض التي أعطيت إبراهيم وإسحاق, لك أعطيها, ولنسلك من بعدك أعطي الأرض».","35:13":"ثم صعد الله عنه في المكان الذي فيه تكلم معه.","35:14":"فنصب يعقوب عمودا في المكان الذي فيه تكلم معه, عمودا من حجر, وسكب عليه سكيبا, وصب عليه زيتا.","35:15":"ودعا يعقوب اسم المكان الذي فيه تكلم الله معه «بيت إيل».","35:16":"ثم رحلوا من بيت إيل. ولما كان مسافة من الأرض بعد حتى يأتوا إلى أفراتة, ولدت راحيل وتعسرت ولادتها.","35:17":"وحدث حين تعسرت ولادتها أن القابلة قالت لها: «لا تخافي, لأن هذا أيضا ابن لك».","35:18":"وكان عند خروج نفسها, لأنها ماتت, أنها دعت اسمه «بن أوني». وأما أبوه فدعاه «بنيامين».","35:19":"فماتت راحيل ودفنت في طريق أفراتة, التي هي بيت لحم.","35:20":"فنصب يعقوب عمودا على قبرها, وهو «عمود قبر راحيل» إلى اليوم.","35:21":"ثم رحل إسرائيل ونصب خيمته وراء مجدل عدر.","35:22":"وحدث إذ كان إسرائيل ساكنا في تلك الأرض, أن رأوبين ذهب واضطجع مع بلهة سرية أبيه, وسمع إسرائيل. وكان بنو يعقوب اثني عشر:","35:23":"بنو ليئة: رأوبين بكر يعقوب, وشمعون ولاوي ويهوذا ويساكر وزبولون.","35:24":"وابنا راحيل: يوسف وبنيامين.","35:25":"وابنا بلهة جارية راحيل: دان ونفتالي.","35:26":"وابنا زلفة جارية ليئة: جاد وأشير. هؤلاء بنو يعقوب الذين ولدوا له في فدان أرام.","35:27":"وجاء يعقوب إلى إسحاق أبيه إلى ممرا, قرية أربع, التي هي حبرون, حيث تغرب إبراهيم وإسحاق.","35:28":"وكانت أيام إسحاق مئة وثمانين سنة.","35:29":"فأسلم إسحاق روحه ومات وانضم إلى قومه, شيخا وشبعان أياما. ودفنه عيسو ويعقوب ابناه.","36:1":"وهذه مواليد عيسو, الذي هو أدوم.","36:2":"أخذ عيسو نساءه من بنات كنعان: عدا بنت إيلون الحثي, وأهوليبامة بنت عنى بنت صبعون الحوي,","36:3":"وبسمة بنت إسماعيل أخت نبايوت.","36:4":"فولدت عدا لعيسو أليفاز, وولدت بسمة رعوئيل,","36:5":"وولدت أهوليبامة: يعوش ويعلام وقورح. هؤلاء بنو عيسو الذين ولدوا له في أرض كنعان.","36:6":"ثم أخذ عيسو نساءه وبنيه وبناته وجميع نفوس بيته ومواشيه وكل بهائمه وكل مقتناه الذي اقتنى في أرض كنعان, ومضى إلى أرض أخرى من وجه يعقوب أخيه,","36:7":"لأن أملاكهما كانت كثيرة على السكنى معا, ولم تستطع أرض غربتهما أن تحملهما من أجل مواشيهما.","36:8":"فسكن عيسو في جبل سعير. وعيسو هو أدوم.","36:9":"وهذه مواليد عيسو أبي أدوم في جبل سعير.","36:10":"هذه أسماء بني عيسو: أليفاز ابن عدا امرأة عيسو, ورعوئيل ابن بسمة امرأة عيسو.","36:11":"وكان بنو أليفاز: تيمان وأومار وصفوا وجعثام وقناز.","36:12":"وكانت تمناع سرية لأليفاز بن عيسو, فولدت لأليفاز عماليق. هؤلاء بنو عدا امرأة عيسو.","36:13":"وهؤلاء بنو رعوئيل: نحث وزارح وشمة ومزة. هؤلاء كانوا بني بسمة امرأة عيسو.","36:14":"وهؤلاء كانوا بني أهوليبامة بنت عنى بنت صبعون امرأة عيسو, ولدت لعيسو: يعوش ويعلام وقورح.","36:15":"هؤلاء أمراء بني عيسو: بنو أليفاز بكر عيسو: أمير تيمان وأمير أومار وأمير صفو وأمير قناز","36:16":"وأمير قورح وأمير جعثام وأمير عماليق. هؤلاء أمراء أليفاز في أرض أدوم. هؤلاء بنو عدا.","36:17":"وهؤلاء بنو رعوئيل بن عيسو: أمير نحث وأمير زارح وأمير شمة وأمير مزة. هؤلاء أمراء رعوئيل في أرض أدوم. هؤلاء بنو بسمة امرأة عيسو.","36:18":"وهؤلاء بنو أهوليبامة امرأة عيسو: أمير يعوش وأمير يعلام وأمير قورح. هؤلاء أمراء أهوليبامة بنت عنى امرأة عيسو.","36:19":"هؤلاء بنو عيسو الذي هو أدوم, وهؤلاء أمراؤهم.","36:20":"هؤلاء بنو سعير الحوري سكان الأرض: لوطان وشوبال وصبعون وعنى","36:21":"وديشون وإيصر وديشان. هؤلاء أمراء الحوريين بنو سعير في أرض أدوم.","36:22":"وكان ابنا لوطان: حوري وهيمام. وكانت تمناع أخت لوطان.","36:23":"وهؤلاء بنو شوبال: علوان ومناحة وعيبال وشفو وأونام.","36:24":"وهذان ابنا صبعون: أية وعنى. هذا هو عنى الذي وجد الحمائم في البرية إذ كان يرعى حمير صبعون أبيه.","36:25":"وهذا ابن عنى: ديشون. وأهوليبامة هي بنت عنى.","36:26":"وهؤلاء بنو ديشان: حمدان وأشبان ويثران وكران.","36:27":"هؤلاء بنو إيصر: بلهان وزعوان وعقان.","36:28":"هذان ابنا ديشان: عوص وأران.","36:29":"هؤلاء أمراء الحوريين: أمير لوطان وأمير شوبال وأمير صبعون وأمير عنى","36:30":"وأمير ديشون وأمير إيصر وأمير ديشان. هؤلاء أمراء الحوريين بأمرائهم في أرض سعير.","36:31":"وهؤلاء هم الملوك الذين ملكوا في أرض أدوم, قبلما ملك ملك لبني إسرائيل.","36:32":"ملك في أدوم بالع بن بعور, وكان اسم مدينته دنهابة.","36:33":"ومات بالع, فملك مكانه يوباب بن زارح من بصرة.","36:34":"ومات يوباب, فملك مكانه حوشام من أرض التيماني.","36:35":"ومات حوشام, فملك مكانه هداد بن بداد الذي كسر مديان في بلاد موآب, وكان اسم مدينته عويت.","36:36":"ومات هداد, فملك مكانه سملة من مسريقة.","36:37":"ومات سملة, فملك مكانه شأول من رحوبوت النهر.","36:38":"ومات شأول, فملك مكانه بعل حانان بن عكبور.","36:39":"ومات بعل حانان بن عكبور, فملك مكانه هدار وكان اسم مدينته فاعو, واسم امرأته مهيطبئيل بنت مطرد بنت ماء ذهب.","36:40":"وهذه أسماء أمراء عيسو, حسب قبائلهم وأماكنهم بأسمائهم: أمير تمناع وأمير علوة وأمير يتيت","36:41":"وأمير أهوليبامة وأمير إيلة وأمير فينون","36:42":"وأمير قناز وأمير تيمان وأمير مبصار","36:43":"وأمير مجديئيل وأمير عيرام. هؤلاء أمراء أدوم حسب مساكنهم في أرض ملكهم. هذا هو عيسو أبو أدوم.","37:1":"وسكن يعقوب في أرض غربة أبيه, في أرض كنعان.","37:2":"هذه مواليد يعقوب: يوسف إذ كان ابن سبع عشرة سنة, كان يرعى مع إخوته الغنم وهو غلام عند بني بلهة وبني زلفة امرأتي أبيه, وأتى يوسف بنميمتهم الرديئة إلى أبيهم.","37:3":"وأما إسرائيل فأحب يوسف أكثر من سائر بنيه لأنه ابن شيخوخته, فصنع له قميصا ملونا.","37:4":"فلما رأى إخوته أن أباهم أحبه أكثر من جميع إخوته أبغضوه, ولم يستطيعوا أن يكلموه بسلام.","37:5":"وحلم يوسف حلما وأخبر إخوته, فازدادوا أيضا بغضا له.","37:6":"فقال لهم: «اسمعوا هذا الحلم الذي حلمت:","37:7":"فها نحن حازمون حزما في الحقل, وإذا حزمتي قامت وانتصبت, فاحتاطت حزمكم وسجدت لحزمتي».","37:8":"فقال له إخوته: «ألعلك تملك علينا ملكا أم تتسلط علينا تسلطا؟» وازدادوا أيضا بغضا له من أجل أحلامه ومن أجل كلامه.","37:9":"ثم حلم أيضا حلما آخر وقصه على إخوته, فقال: «إني قد حلمت؟ حلما أيضا, وإذا الشمس والقمر وأحد عشر كوكبا ساجدة لي».","37:10":"وقصه على أبيه وعلى إخوته, فانتهره أبوه وقال له: «ما هذا الحلم الذي حلمت؟ هل نأتي أنا وأمك وإخوتك لنسجد لك إلى الأرض؟»","37:11":"فحسده إخوته, وأما أبوه فحفظ الأمر.","37:12":"ومضى إخوته ليرعوا غنم أبيهم عند شكيم.","37:13":"فقال إسرائيل ليوسف: «أليس إخوتك يرعون عند شكيم؟ تعال فأرسلك إليهم». فقال له: «هأنذا».","37:14":"فقال له: «اذهب انظر سلامة إخوتك وسلامة الغنم ورد لي خبرا». فأرسله من وطاء حبرون فأتى إلى شكيم.","37:15":"فوجده رجل وإذا هو ضال في الحقل. فسأله الرجل قائلا: «ماذا تطلب؟»","37:16":"فقال: «أنا طالب إخوتي. أخبرني أين يرعون؟».","37:17":"فقال الرجل: «قد ارتحلوا من هنا, لأني سمعتهم يقولون: لنذهب إلى دوثان». فذهب يوسف وراء إخوته فوجدهم في دوثان.","37:18":"فلما أبصروه من بعيد, قبلما اقترب إليهم, احتالوا له ليميتوه.","37:19":"فقال بعضهم لبعض: «هوذا هذا صاحب الأحلام قادم.","37:20":"فالآن هلم نقتله ونطرحه في إحدى الآبار ونقول: وحش رديء أكله. فنرى ماذا تكون أحلامه».","37:21":"فسمع رأوبين وأنقذه من أيديهم, وقال: «لا نقتله».","37:22":"وقال لهم رأوبين: «لا تسفكوا دما. اطرحوه في هذه البئر التي في البرية ولا تمدوا إليه يدا». لكي ينقذه من أيديهم ليرده إلى أبيه.","37:23":"فكان لما جاء يوسف إلى إخوته أنهم خلعوا عن يوسف قميصه, القميص الملون الذي عليه,","37:24":"وأخذوه وطرحوه في البئر. وأما البئر فكانت فارغة ليس فيها ماء.","37:25":"ثم جلسوا ليأكلوا طعاما. فرفعوا عيونهم ونظروا وإذا قافلة إسماعيليين مقبلة من جلعاد, وجمالهم حاملة كثيراء وبلسانا ولاذنا, ذاهبين لينزلوا بها إلى مصر.","37:26":"فقال يهوذا لإخوته: «ما الفائدة أن نقتل أخانا ونخفي دمه؟","37:27":"تعالوا فنبيعه للإسماعيليين, ولا تكن أيدينا عليه لأنه أخونا ولحمنا». فسمع له إخوته.","37:28":"واجتاز رجال مديانيون تجار, فسحبوا يوسف وأصعدوه من البئر, وباعوا يوسف للإسماعيليين بعشرين من الفضة. فأتوا بيوسف إلى مصر.","37:29":"ورجع رأوبين إلى البئر, وإذا يوسف ليس في البئر, فمزق ثيابه.","37:30":"ثم رجع إلى إخوته وقال: «الولد ليس موجودا, وأنا إلى أين أذهب؟».","37:31":"فأخذوا قميص يوسف وذبحوا تيسا من المعزى وغمسوا القميص في الدم.","37:32":"وأرسلوا القميص الملون وأحضروه إلى أبيهم وقالوا: «وجدنا هذا. حقق أقميص ابنك هو أم لا؟»","37:33":"فتحققه وقال: «قميص ابني! وحش رديء أكله, افترس يوسف افتراسا».","37:34":"فمزق يعقوب ثيابه, ووضع مسحا على حقويه, وناح على ابنه أياما كثيرة.","37:35":"فقام جميع بنيه وجميع بناته ليعزوه, فأبى أن يتعزى وقال: «إني أنزل إلى ابني نائحا إلى الهاوية». وبكى عليه أبوه.","37:36":"وأما المديانيون فباعوه في مصر لفوطيفار خصي فرعون, رئيس الشرط.","38:1":"وحدث في ذلك الزمان أن يهوذا نزل من عند إخوته, ومال إلى رجل عدلامي اسمه حيرة.","38:2":"ونظر يهوذا هناك ابنة رجل كنعاني اسمه شوع, فأخذها ودخل عليها,","38:3":"فحبلت وولدت ابنا ودعا اسمه «عيرا».","38:4":"ثم حبلت أيضا وولدت ابنا ودعت اسمه «أونان».","38:5":"ثم عادت فولدت أيضا ابنا ودعت اسمه «شيلة». وكان في كزيب حين ولدته.","38:6":"وأخذ يهوذا زوجة لعير بكره اسمها ثامار.","38:7":"وكان عير بكر يهوذا شريرا في عيني الرب, فأماته الرب.","38:8":"فقال يهوذا لأونان: «ادخل على امرأة أخيك وتزوج بها, وأقم نسلا لأخيك».","38:9":"فعلم أونان أن النسل لا يكون له, فكان إذ دخل على امرأة أخيه أنه أفسد على الأرض, لكي لا يعطي نسلا لأخيه.","38:10":"فقبح في عيني الرب ما فعله, فأماته أيضا.","38:11":"فقال يهوذا لثامار كنته: «اقعدي أرملة في بيت أبيك حتى يكبر شيلة ابني». لأنه قال: «لعله يموت هو أيضا كأخويه». فمضت ثامار وقعدت في بيت أبيها.","38:12":"ولما طال الزمان ماتت ابنة شوع امرأة يهوذا. ثم تعزى يهوذا فصعد إلى جزاز غنمه إلى تمنة, هو وحيرة صاحبه العدلامي.","38:13":"فأخبرت ثامار وقيل لها: «هوذا حموك صاعد إلى تمنة ليجز غنمه».","38:14":"فخلعت عنها ثياب ترملها, وتغطت ببرقع وتلففت, وجلست في مدخل عينايم التي على طريق تمنة, لأنها رأت أن شيلة قد كبر وهي لم تعط له زوجة.","38:15":"فنظرها يهوذا وحسبها زانية, لأنها كانت قد غطت وجهها.","38:16":"فمال إليها على الطريق وقال: «هاتي أدخل عليك». لأنه لم يعلم أنها كنته. فقالت: «ماذا تعطيني لكي تدخل علي؟»","38:17":"فقال: «إني أرسل جدي معزى من الغنم». فقالت: «هل تعطيني رهنا حتى ترسله؟».","38:18":"فقال: «ما الرهن الذي أعطيك؟» فقالت: «خاتمك وعصابتك وعصاك التي في يدك». فأعطاها ودخل عليها, فحبلت منه.","38:19":"ثم قامت ومضت وخلعت عنها برقعها ولبست ثياب ترملها.","38:20":"فأرسل يهوذا جدي المعزى بيد صاحبه العدلامي ليأخذ الرهن من يد المرأة, فلم يجدها.","38:21":"فسأل أهل مكانها قائلا: «أين الزانية التي كانت في عينايم على الطريق؟» فقالوا: «لم تكن ههنا زانية».","38:22":"فرجع إلى يهوذا وقال: «لم أجدها. وأهل المكان أيضا قالوا: لم تكن ههنا زانية».","38:23":"فقال يهوذا: «لتأخذ لنفسها, لئلا نصير إهانة. إني قد أرسلت هذا الجدي وأنت لم تجدها».","38:24":"ولما كان نحو ثلاثة أشهر, أخبر يهوذا وقيل له: «قد زنت ثامار كنتك, وها هي حبلى أيضا من الزنا». فقال يهوذا: «أخرجوها فتحرق».","38:25":"أما هي فلما أخرجت أرسلت إلى حميها قائلة: «من الرجل الذي هذه له أنا حبلى!» وقالت: «حقق لمن الخاتم والعصابة والعصا هذه».","38:26":"فتحققها يهوذا وقال: «هي أبر مني, لأني لم أعطها لشيلة ابني». فلم يعد يعرفها أيضا.","38:27":"وفي وقت ولادتها إذا في بطنها توأمان.","38:28":"وكان في ولادتها أن أحدهما أخرج يدا فأخذت القابلة وربطت على يده قرمزا, قائلة: «هذا خرج أولا».","38:29":"ولكن حين رد يده, إذا أخوه قد خرج. فقالت: «لماذا اقتحمت؟ عليك اقتحام!». فدعي اسمه «فارص».","38:30":"وبعد ذلك خرج أخوه الذي على يده القرمز. فدعي اسمه «زارح».","39:1":"وأما يوسف فأنزل إلى مصر, واشتراه فوطيفار خصي فرعون رئيس الشرط, رجل مصري, من يد الإسماعيليين الذين أنزلوه إلى هناك.","39:2":"وكان الرب مع يوسف فكان رجلا ناجحا, وكان في بيت سيده المصري.","39:3":"ورأى سيده أن الرب معه, وأن كل ما يصنع كان الرب ينجحه بيده.","39:4":"فوجد يوسف نعمة في عينيه, وخدمه, فوكله على بيته ودفع إلى يده كل ما كان له.","39:5":"وكان من حين وكله على بيته, وعلى كل ما كان له, أن الرب بارك بيت المصري بسبب يوسف. وكانت بركة الرب على كل ما كان له في البيت وفي الحقل,","39:6":"فترك كل ما كان له في يد يوسف. ولم يكن معه يعرف شيئا إلا الخبز الذي يأكل. وكان يوسف حسن الصورة وحسن المنظر.","39:7":"وحدث بعد هذه الأمور أن امرأة سيده رفعت عينيها إلى يوسف وقالت: «اضطجع معي».","39:8":"فأبى وقال لامرأة سيده: «هوذا سيدي لا يعرف معي ما في البيت, وكل ما له قد دفعه إلى يدي.","39:9":"ليس هو في هذا البيت أعظم مني. ولم يمسك عني شيئا غيرك, لأنك امرأته. فكيف أصنع هذا الشر العظيم وأخطئ إلى الله؟».","39:10":"وكان إذ كلمت يوسف يوما فيوما أنه لم يسمع لها أن يضطجع بجانبها ليكون معها.","39:11":"ثم حدث نحو هذا الوقت أنه دخل البيت ليعمل عمله, ولم يكن إنسان من أهل البيت هناك في البيت.","39:12":"فأمسكته بثوبه قائلة: «اضطجع معي!». فترك ثوبه في يدها وهرب وخرج إلى خارج.","39:13":"وكان لما رأت أنه ترك ثوبه في يدها وهرب إلى خارج,","39:14":"أنها نادت أهل بيتها, وكلمتهم قائلة: «انظروا! قد جاء إلينا برجل عبراني ليداعبنا! دخل إلي ليضطجع معي, فصرخت بصوت عظيم.","39:15":"وكان لما سمع أني رفعت صوتي وصرخت, أنه ترك ثوبه بجانبي وهرب وخرج إلى خارج».","39:16":"فوضعت ثوبه بجانبها حتى جاء سيده إلى بيته.","39:17":"فكلمته بمثل هذا الكلام قائلة: «دخل إلي العبد العبراني الذي جئت به إلينا ليداعبني.","39:18":"وكان لما رفعت صوتي وصرخت, أنه ترك ثوبه بجانبي وهرب إلى خارج».","39:19":"فكان لما سمع سيده كلام امرأته الذي كلمته به قائلة: «بحسب هذا الكلام صنع بي عبدك», أن غضبه حمي.","39:20":"فأخذ يوسف سيده ووضعه في بيت السجن, المكان الذي كان أسرى الملك محبوسين فيه. وكان هناك في بيت السجن.","39:21":"ولكن الرب كان مع يوسف, وبسط إليه لطفا, وجعل نعمة له في عيني رئيس بيت السجن.","39:22":"فدفع رئيس بيت السجن إلى يد يوسف جميع الأسرى الذين في بيت السجن. وكل ما كانوا يعملون هناك كان هو العامل.","39:23":"ولم يكن رئيس بيت السجن ينظر شيئا البتة مما في يده, لأن الرب كان معه, ومهما صنع كان الرب ينجحه.","40:1":"وحدث بعد هذه الأمور أن ساقي ملك مصر والخباز أذنبا إلى سيدهما ملك مصر.","40:2":"فسخط فرعون على خصييه: رئيس السقاة ورئيس الخبازين,","40:3":"فوضعهما في حبس بيت رئيس الشرط, في بيت السجن, المكان الذي كان يوسف محبوسا فيه.","40:4":"فأقام رئيس الشرط يوسف عندهما فخدمهما. وكانا أياما في الحبس.","40:5":"وحلما كلاهما حلما في ليلة واحدة, كل واحد حلمه, كل واحد بحسب تعبير حلمه, ساقي ملك مصر وخبازه, المحبوسان في بيت السجن.","40:6":"فدخل يوسف إليهما في الصباح ونظرهما, وإذا هما مغتمان.","40:7":"فسأل خصيي فرعون اللذين معه في حبس بيت سيده قائلا: «لماذا وجهاكما مكمدان اليوم؟»","40:8":"فقالا له: «حلمنا حلما وليس من يعبره». فقال لهما يوسف: «أليست لله التعابير؟ قصا علي».","40:9":"فقص رئيس السقاة حلمه على يوسف وقال له: «كنت في حلمي وإذا كرمة أمامي.","40:10":"وفي الكرمة ثلاثة قضبان, وهي إذ أفرخت طلع زهرها, وأنضجت عناقيدها عنبا.","40:11":"وكانت كأس فرعون في يدي, فأخذت العنب وعصرته في كأس فرعون, وأعطيت الكأس في يد فرعون».","40:12":"فقال له يوسف: «هذا تعبيره: الثلاثة القضبان هي ثلاثة أيام.","40:13":"في ثلاثة أيام أيضا يرفع فرعون رأسك ويردك إلى مقامك, فتعطي كأس فرعون في يده كالعادة الأولى حين كنت ساقيه.","40:14":"وإنما إذا ذكرتني عندك حينما يصير لك خير, تصنع إلي إحسانا وتذكرني لفرعون, وتخرجني من هذا البيت.","40:15":"لأني قد سرقت من أرض العبرانيين, وهنا أيضا لم أفعل شيئا حتى وضعوني في السجن».","40:16":"فلما رأى رئيس الخبازين أنه عبر جيدا, قال ليوسف: «كنت أنا أيضا في حلمي وإذا ثلاثة سلال حواري على رأسي.","40:17":"وفي السل الأعلى من جميع طعام فرعون من صنعة الخباز. والطيور تأكله من السل عن رأسي».","40:18":"فأجاب يوسف وقال: «هذا تعبيره: الثلاثة السلال هي ثلاثة أيام.","40:19":"في ثلاثة أيام أيضا يرفع فرعون رأسك عنك, ويعلقك على خشبة, وتأكل الطيور لحمك عنك».","40:20":"فحدث في اليوم الثالث, يوم ميلاد فرعون, أنه صنع وليمة لجميع عبيده, ورفع رأس رئيس السقاة ورأس رئيس الخبازين بين عبيده.","40:21":"ورد رئيس السقاة إلى سقيه, فأعطى الكأس في يد فرعون.","40:22":"وأما رئيس الخبازين فعلقه, كما عبر لهما يوسف.","40:23":"ولكن لم يذكر رئيس السقاة يوسف بل نسيه.","41:1":"وحدث من بعد سنتين من الزمان أن فرعون رأى حلما: وإذا هو واقف عند النهر,","41:2":"وهوذا سبع بقرات طالعة من النهر حسنة المنظر وسمينة اللحم, فارتعت في روضة.","41:3":"ثم هوذا سبع بقرات أخرى طالعة وراءها من النهر قبيحة المنظر ورقيقة اللحم, فوقفت بجانب البقرات الأولى على شاطئ النهر,","41:4":"فأكلت البقرات القبيحة المنظر والرقيقة اللحم البقرات السبع الحسنة المنظر والسمينة. واستيقظ فرعون.","41:5":"ثم نام فحلم ثانية: وهوذا سبع سنابل طالعة في ساق واحد سمينة وحسنة.","41:6":"ثم هوذا سبع سنابل رقيقة وملفوحة بالريح الشرقية نابتة وراءها.","41:7":"فابتلعت السنابل الرقيقة السنابل السبع السمينة الممتلئة. واستيقظ فرعون, وإذا هو حلم.","41:8":"وكان في الصباح أن نفسه انزعجت, فأرسل ودعا جميع سحرة مصر وجميع حكمائها. وقص عليهم فرعون حلمه, فلم يكن من يعبره لفرعون.","41:9":"ثم كلم رئيس السقاة فرعون قائلا: «أنا أتذكر اليوم خطاياي.","41:10":"فرعون سخط على عبديه, فجعلني في حبس بيت رئيس الشرط أنا ورئيس الخبازين.","41:11":"فحلمنا حلما في ليلة واحدة أنا وهو. حلمنا كل واحد بحسب تعبير حلمه.","41:12":"وكان هناك معنا غلام عبراني عبد لرئيس الشرط, فقصصنا عليه, فعبر لنا حلمينا. عبر لكل واحد بحسب حلمه.","41:13":"وكما عبر لنا هكذا حدث. ردني أنا إلى مقامي, وأما هو فعلقه».","41:14":"فأرسل فرعون ودعا يوسف, فأسرعوا به من السجن. فحلق وأبدل ثيابه ودخل على فرعون.","41:15":"فقال فرعون ليوسف: «حلمت حلما وليس من يعبره. وأنا سمعت عنك قولا, إنك تسمع أحلاما لتعبرها».","41:16":"فأجاب يوسف فرعون: «ليس لي. الله يجيب بسلامة فرعون».","41:17":"فقال فرعون ليوسف: «إني كنت في حلمي واقفا على شاطئ النهر,","41:18":"وهوذا سبع بقرات طالعة من النهر سمينة اللحم وحسنة الصورة, فارتعت في روضة.","41:19":"ثم هوذا سبع بقرات أخرى طالعة وراءها مهزولة وقبيحة الصورة جدا ورقيقة اللحم. لم أنظر في كل أرض مصر مثلها في القباحة.","41:20":"فأكلت البقرات الرقيقة والقبيحة البقرات السبع الأولى السمينة.","41:21":"فدخلت أجوافها, ولم يعلم أنها دخلت في أجوافها, فكان منظرها قبيحا كما في الأول. واستيقظت.","41:22":"ثم رأيت في حلمي وهوذا سبع سنابل طالعة في ساق واحد ممتلئة وحسنة.","41:23":"ثم هوذا سبع سنابل يابسة رقيقة ملفوحة بالريح الشرقية نابتة وراءها.","41:24":"فابتلعت السنابل الرقيقة السنابل السبع الحسنة. فقلت للسحرة, ولم يكن من يخبرني».","41:25":"فقال يوسف لفرعون: «حلم فرعون واحد. قد أخبر الله فرعون بما هو صانع.","41:26":"البقرات السبع الحسنة هي سبع سنين, والسنابل السبع الحسنة هي سبع سنين. هو حلم واحد.","41:27":"والبقرات السبع الرقيقة القبيحة التي طلعت وراءها هي سبع سنين, والسنابل السبع الفارغة الملفوحة بالريح الشرقية تكون سبع سنين جوعا.","41:28":"هو الأمر الذي كلمت به فرعون. قد أظهر الله لفرعون ما هو صانع.","41:29":"هوذا سبع سنين قادمة شبعا عظيما في كل أرض مصر.","41:30":"ثم تقوم بعدها سبع سنين جوعا, فينسى كل الشبع في أرض مصر ويتلف الجوع الأرض.","41:31":"ولا يعرف الشبع في الأرض من أجل ذلك الجوع بعده, لأنه يكون شديدا جدا.","41:32":"وأما عن تكرار الحلم على فرعون مرتين, فلأن الأمر مقرر من قبل الله, والله مسرع ليصنعه.","41:33":"«فالآن لينظر فرعون رجلا بصيرا وحكيما ويجعله على أرض مصر.","41:34":"يفعل فرعون فيوكل نظارا على الأرض, ويأخذ خمس غلة أرض مصر في سبع سني الشبع,","41:35":"فيجمعون جميع طعام هذه السنين الجيدة القادمة, ويخزنون قمحا تحت يد فرعون طعاما في المدن ويحفظونه.","41:36":"فيكون الطعام ذخيرة للأرض لسبع سني الجوع التي تكون في أرض مصر, فلا تنقرض الأرض بالجوع».","41:37":"فحسن الكلام في عيني فرعون وفي عيون جميع عبيده.","41:38":"فقال فرعون لعبيده: «هل نجد مثل هذا رجلا فيه روح الله؟»","41:39":"ثم قال فرعون ليوسف: «بعد ما أعلمك الله كل هذا, ليس بصير وحكيم مثلك.","41:40":"أنت تكون على بيتي, وعلى فمك يقبل جميع شعبي إلا إن الكرسي أكون فيه أعظم منك».","41:41":"ثم قال فرعون ليوسف: «انظر, قد جعلتك على كل أرض مصر».","41:42":"وخلع فرعون خاتمه من يده وجعله في يد يوسف, وألبسه ثياب بوص, ووضع طوق ذهب في عنقه,","41:43":"وأركبه في مركبته الثانية, ونادوا أمامه «اركعوا». وجعله على كل أرض مصر.","41:44":"وقال فرعون ليوسف: «أنا فرعون. فبدونك لا يرفع إنسان يده ولا رجله في كل أرض مصر».","41:45":"ودعا فرعون اسم يوسف «صفنات فعنيح», وأعطاه أسنات بنت فوطي فارع كاهن أون زوجة. فخرج يوسف على أرض مصر.","41:46":"وكان يوسف ابن ثلاثين سنة لما وقف قدام فرعون ملك مصر. فخرج يوسف من لدن فرعون واجتاز في كل أرض مصر.","41:47":"وأثمرت الأرض في سبع سني الشبع بحزم.","41:48":"فجمع كل طعام السبع سنين التي كانت في أرض مصر, وجعل طعاما في المدن. طعام حقل المدينة الذي حواليها جعله فيها.","41:49":"وخزن يوسف قمحا كرمل البحر, كثيرا جدا حتى ترك العدد, إذ لم يكن له عدد.","41:50":"وولد ليوسف ابنان قبل أن تأتي سنة الجوع, ولدتهما له أسنات بنت فوطي فارع كاهن أون.","41:51":"ودعا يوسف اسم البكر «منسى» قائلا: «لأن الله أنساني كل تعبي وكل بيت أبي».","41:52":"ودعا اسم الثاني «أفرايم» قائلا: «لأن الله جعلني مثمرا في أرض مذلتي».","41:53":"ثم كملت سبع سني الشبع الذي كان في أرض مصر.","41:54":"وابتدأت سبع سني الجوع تأتي كما قال يوسف, فكان جوع في جميع البلدان. وأما جميع أرض مصر فكان فيها خبز.","41:55":"ولما جاعت جميع أرض مصر وصرخ الشعب إلى فرعون لأجل الخبز, قال فرعون لكل المصريين: «اذهبوا إلى يوسف, والذي يقول لكم افعلوا».","41:56":"وكان الجوع على كل وجه الأرض, وفتح يوسف جميع ما فيه طعام وباع للمصريين. واشتد الجوع في أرض مصر.","41:57":"وجاءت كل الأرض إلى مصر إلى يوسف لتشتري قمحا, لأن الجوع كان شديدا في كل الأرض.","42:1":"فلما رأى يعقوب أنه يوجد قمح في مصر, قال يعقوب لبنيه: «لماذا تنظرون بعضكم إلى بعض؟»","42:2":"وقال «إني قد سمعت أنه يوجد قمح في مصر. انزلوا إلى هناك واشتروا لنا من هناك لنحيا ولا نموت».","42:3":"فنزل عشرة من إخوة يوسف ليشتروا قمحا من مصر.","42:4":"وأما بنيامين أخو يوسف فلم يرسله يعقوب مع إخوته, لأنه قال: «لعله تصيبه أذية».","42:5":"فأتى بنو إسرائيل ليشتروا بين الذين أتوا, لأن الجوع كان في أرض كنعان.","42:6":"وكان يوسف هو المسلط على الأرض, وهو البائع لكل شعب الأرض. فأتى إخوة يوسف وسجدوا له بوجوههم إلى الأرض.","42:7":"ولما نظر يوسف إخوته عرفهم, فتنكر لهم وتكلم معهم بجفاء, وقال لهم: «من أين جئتم؟» فقالوا: «من أرض كنعان لنشتري طعاما».","42:8":"وعرف يوسف إخوته, وأما هم فلم يعرفوه.","42:9":"فتذكر يوسف الأحلام التي حلم عنهم, وقال لهم: «جواسيس أنتم! لتروا عورة الأرض جئتم»","42:10":"فقالوا له: «لا يا سيدي, بل عبيدك جاءوا ليشتروا طعاما.","42:11":"نحن جميعنا بنو رجل واحد. نحن أمناء, ليس عبيدك جواسيس».","42:12":"فقال لهم: «كلا! بل لتروا عورة الأرض جئتم».","42:13":"فقالوا: «عبيدك اثنا عشر أخا. نحن بنو رجل واحد في أرض كنعان. وهوذا الصغير عند أبينا اليوم, والواحد مفقود».","42:14":"فقال لهم يوسف: «ذلك ما كلمتكم به قائلا: جواسيس أنتم!","42:15":"بهذا تمتحنون. وحياة فرعون لا تخرجون من هنا إلا بمجيء أخيكم الصغير إلى هنا.","42:16":"أرسلوا منكم واحدا ليجيء بأخيكم, وأنتم تحبسون, فيمتحن كلامكم هل عندكم صدق. وإلا فوحياة فرعون إنكم لجواسيس!».","42:17":"فجمعهم إلى حبس ثلاثة أيام.","42:18":"ثم قال لهم يوسف في اليوم الثالث: «افعلوا هذا واحيوا. أنا خائف الله.","42:19":"إن كنتم أمناء فليحبس أخ واحد منكم في بيت حبسكم, وانطلقوا أنتم وخذوا قمحا لمجاعة بيوتكم.","42:20":"وأحضروا أخاكم الصغير إلي, فيتحقق كلامكم ولا تموتوا». ففعلوا هكذا.","42:21":"وقالوا بعضهم لبعض: «حقا إننا مذنبون إلى أخينا الذي رأينا ضيقة نفسه لما استرحمنا ولم نسمع. لذلك جاءت علينا هذه الضيقة».","42:22":"فأجابهم رأوبين قائلا: «ألم أكلمكم قائلا: لا تأثموا بالولد, وأنتم لم تسمعوا؟ فهوذا دمه يطلب».","42:23":"وهم لم يعلموا أن يوسف فاهم؛ لأن الترجمان كان بينهم.","42:24":"فتحول عنهم وبكى, ثم رجع إليهم وكلمهم, وأخذ منهم شمعون وقيده أمام عيونهم.","42:25":"ثم أمر يوسف أن تملأ أوعيتهم قمحا, وترد فضة كل واحد إلى عدله, وأن يعطوا زادا للطريق. ففعل لهم هكذا.","42:26":"فحملوا قمحهم على حميرهم ومضوا من هناك.","42:27":"فلما فتح أحدهم عدله ليعطي عليقا لحماره في المنزل, رأى فضته وإذا هي في فم عدله.","42:28":"فقال لإخوته: «ردت فضتي وها هي في عدلي». فطارت قلوبهم وارتعدوا بعضهم في بعض قائلين: «ما هذا الذي صنعه الله بنا؟».","42:29":"فجاءوا إلى يعقوب أبيهم إلى أرض كنعان, وأخبروه بكل ما أصابهم قائلين:","42:30":"«تكلم معنا الرجل سيد الأرض بجفاء, وحسبنا جواسيس الأرض.","42:31":"فقلنا له: نحن أمناء, لسنا جواسيس.","42:32":"نحن اثنا عشر أخا بنو أبينا. الواحد مفقود والصغير اليوم عند أبينا في أرض كنعان.","42:33":"فقال لنا الرجل سيد الأرض: بهذا أعرف أنكم أمناء. دعوا أخا واحدا منكم عندي, وخذوا لمجاعة بيوتكم وانطلقوا.","42:34":"وأحضروا أخاكم الصغير إلي فأعرف أنكم لستم جواسيس, بل أنكم أمناء, فأعطيكم أخاكم وتتجرون في الأرض».","42:35":"وإذ كانوا يفرغون عدالهم إذا صرة فضة كل واحد في عدله. فلما رأوا صرر فضتهم هم وأبوهم خافوا.","42:36":"فقال لهم يعقوب: «أعدمتموني الأولاد. يوسف مفقود, وشمعون مفقود, وبنيامين تأخذونه. صار كل هذا علي».","42:37":"وكلم رأوبين أباه قائلا: «اقتل ابني إن لم أجئ به إليك. سلمه بيدي وأنا أرده إليك».","42:38":"فقال: «لا ينزل ابني معكم, لأن أخاه قد مات, وهو وحده باق. فإن أصابته أذية في الطريق التي تذهبون فيها تنزلون شيبتي بحزن إلى الهاوية».","43:1":"وكان الجوع شديدا في الأرض.","43:2":"وحدث لما فرغوا من أكل القمح الذي جاءوا به من مصر, أن أباهم قال لهم: «ارجعوا اشتروا لنا قليلا من الطعام».","43:3":"فكلمه يهوذا قائلا: «إن الرجل قد أشهد علينا قائلا: لا ترون وجهي بدون أن يكون أخوكم معكم.","43:4":"إن كنت ترسل أخانا معنا, ننزل ونشتري لك طعاما,","43:5":"ولكن إن كنت لا ترسله لا ننزل. لأن الرجل قال لنا: لا ترون وجهي بدون أن يكون أخوكم معكم».","43:6":"فقال إسرائيل: «لماذا أسأتم إلي حتى أخبرتم الرجل أن لكم أخا أيضا؟»","43:7":"فقالوا: «إن الرجل قد سأل عنا وعن عشيرتنا, قائلا: هل أبوكم حي بعد؟ هل لكم أخ؟ فأخبرناه بحسب هذا الكلام. هل كنا نعلم أنه يقول: انزلوا بأخيكم؟».","43:8":"وقال يهوذا لإسرائيل أبيه: «أرسل الغلام معي لنقوم ونذهب ونحيا ولا نموت, نحن وأنت وأولادنا جميعا.","43:9":"أنا أضمنه. من يدي تطلبه. إن لم أجئ به إليك وأوقفه قدامك, أصر مذنبا إليك كل الأيام.","43:10":"لأننا لو لم نتوان لكنا قد رجعنا الآن مرتين».","43:11":"فقال لهم إسرائيل أبوهم: «إن كان هكذا فافعلوا هذا: خذوا من أفخر جنى الأرض في أوعيتكم, وأنزلوا للرجل هدية. قليلا من البلسان, وقليلا من العسل, وكثيراء ولاذنا وفستقا ولوزا.","43:12":"وخذوا فضة أخرى في أياديكم. والفضة المردودة في أفواه عدالكم ردوها في أياديكم, لعله كان سهوا.","43:13":"وخذوا أخاكم وقوموا ارجعوا إلى الرجل.","43:14":"والله القدير يعطيكم رحمة أمام الرجل حتى يطلق لكم أخاكم الآخر وبنيامين. وأنا إذا عدمت الأولاد عدمتهم».","43:15":"فأخذ الرجال هذه الهدية, وأخذوا ضعف الفضة في أياديهم, وبنيامين, وقاموا ونزلوا إلى مصر ووقفوا أمام يوسف.","43:16":"فلما رأى يوسف بنيامين معهم, قال للذي على بيته: «أدخل الرجال إلى البيت واذبح ذبيحة وهيئ, لأن الرجال يأكلون معي عند الظهر».","43:17":"ففعل الرجل كما قال يوسف. وأدخل الرجل الرجال إلى بيت يوسف.","43:18":"فخاف الرجال إذ أدخلوا إلى بيت يوسف, وقالوا: «لسبب الفضة التي رجعت أولا في عدالنا نحن قد أدخلنا ليهجم علينا ويقع بنا ويأخذنا عبيدا وحميرنا».","43:19":"فتقدموا إلى الرجل الذي على بيت يوسف, وكلموه في باب البيت","43:20":"وقالوا: «استمع يا سيدي, إننا قد نزلنا أولا لنشتري طعاما.","43:21":"وكان لما أتينا إلى المنزل أننا فتحنا عدالنا, وإذا فضة كل واحد في فم عدله. فضتنا بوزنها. فقد رددناها في أيادينا.","43:22":"وأنزلنا فضة أخرى في أيادينا لنشتري طعاما. لا نعلم من وضع فضتنا في عدالنا».","43:23":"فقال: «سلام لكم, لا تخافوا. إلهكم وإله أبيكم أعطاكم كنزا في عدالكم. فضتكم وصلت إلي». ثم أخرج إليهم شمعون.","43:24":"وأدخل الرجل الرجال إلى بيت يوسف وأعطاهم ماء ليغسلوا أرجلهم, وأعطى عليقا لحميرهم.","43:25":"وهيأوا الهدية إلى أن يجيء يوسف عند الظهر, لأنهم سمعوا أنهم هناك يأكلون طعاما.","43:26":"فلما جاء يوسف إلى البيت أحضروا إليه الهدية التي في أياديهم إلى البيت, وسجدوا له إلى الأرض.","43:27":"فسأل عن سلامتهم, وقال: «أسالم أبوكم الشيخ الذي قلتم عنه؟ أحي هو بعد؟»","43:28":"فقالوا: «عبدك أبونا سالم. هو حي بعد». وخروا وسجدوا.","43:29":"فرفع عينيه ونظر بنيامين أخاه ابن أمه, وقال: «أهذا أخوكم الصغير الذي قلتم لي عنه؟» ثم قال: «الله ينعم عليك يا ابني».","43:30":"واستعجل يوسف لأن أحشاءه حنت إلى أخيه وطلب مكانا ليبكي, فدخل المخدع وبكى هناك.","43:31":"ثم غسل وجهه وخرج وتجلد, وقال: «قدموا طعاما».","43:32":"فقدموا له وحده, ولهم وحدهم, وللمصريين الآكلين عنده وحدهم, لأن المصريين لا يقدرون أن يأكلوا طعاما مع العبرانيين, لأنه رجس عند المصريين.","43:33":"فجلسوا قدامه: البكر بحسب بكوريته, والصغير بحسب صغره, فبهت الرجال بعضهم إلى بعض.","43:34":"ورفع حصصا من قدامه إليهم, فكانت حصة بنيامين أكثر من حصص جميعهم خمسة أضعاف. وشربوا ورووا معه.","44:1":"ثم أمر الذي على بيته قائلا: «املأ عدال الرجال طعاما حسب ما يطيقون حمله, وضع فضة كل واحد في فم عدله.","44:2":"وطاسي, طاس الفضة, تضع في فم عدل الصغير, وثمن قمحه». ففعل بحسب كلام يوسف الذي تكلم به.","44:3":"فلما أضاء الصبح انصرف الرجال هم وحميرهم.","44:4":"ولما كانوا قد خرجوا من المدينة ولم يبتعدوا, قال يوسف للذي على بيته: «قم اسع وراء الرجال, ومتى أدركتهم فقل لهم: لماذا جازيتم شرا عوضا عن خير؟","44:5":"أليس هذا هو الذي يشرب سيدي فيه؟ وهو يتفاءل به. أسأتم في ما صنعتم».","44:6":"فأدركهم وقال لهم هذا الكلام.","44:7":"فقالوا له: «لماذا يتكلم سيدي مثل هذا الكلام؟ حاشا لعبيدك أن يفعلوا مثل هذا الأمر!","44:8":"هوذا الفضة التي وجدنا في أفواه عدالنا رددناها إليك من أرض كنعان. فكيف نسرق من بيت سيدك فضة أو ذهبا؟","44:9":"الذي يوجد معه من عبيدك يموت, ونحن أيضا نكون عبيدا لسيدي».","44:10":"فقال: «نعم, الآن بحسب كلامكم هكذا يكون. الذي يوجد معه يكون لي عبدا, وأما أنتم فتكونون أبرياء».","44:11":"فاستعجلوا وأنزلوا كل واحد عدله إلى الأرض, وفتحوا كل واحد عدله.","44:12":"ففتش مبتدئا من الكبير حتى انتهى إلى الصغير, فوجد الطاس في عدل بنيامين.","44:13":"فمزقوا ثيابهم وحمل كل واحد على حماره ورجعوا إلى المدينة.","44:14":"فدخل يهوذا وإخوته إلى بيت يوسف وهو بعد هناك, ووقعوا أمامه على الأرض.","44:15":"فقال لهم يوسف: «ما هذا الفعل الذي فعلتم؟ ألم تعلموا أن رجلا مثلي يتفاءل؟»","44:16":"فقال يهوذا: «ماذا نقول لسيدي؟ ماذا نتكلم؟ وبماذا نتبرر؟ الله قد وجد إثم عبيدك. ها نحن عبيد لسيدي, نحن والذي وجد الطاس في يده جميعا».","44:17":"فقال: «حاشا لي أن أفعل هذا! الرجل الذي وجد الطاس في يده هو يكون لي عبدا, وأما أنتم فاصعدوا بسلام إلى أبيكم».","44:18":"ثم تقدم إليه يهوذا وقال: «استمع يا سيدي. ليتكلم عبدك كلمة في أذني سيدي ولا يحم غضبك على عبدك, لأنك مثل فرعون.","44:19":"سيدي سأل عبيده قائلا: هل لكم أب أو أخ؟","44:20":"فقلنا لسيدي: لنا أب شيخ, وابن شيخوخة صغير, مات أخوه وبقي هو وحده لأمه, وأبوه يحبه.","44:21":"فقلت لعبيدك: انزلوا به إلي فأجعل نظري عليه.","44:22":"فقلنا لسيدي: لا يقدر الغلام أن يترك أباه, وإن ترك أباه يموت.","44:23":"فقلت لعبيدك: إن لم ينزل أخوكم الصغير معكم لا تعودوا تنظرون وجهي.","44:24":"فكان لما صعدنا إلى عبدك أبي أننا أخبرناه بكلام سيدي.","44:25":"ثم قال أبونا: ارجعوا اشتروا لنا قليلا من الطعام.","44:26":"فقلنا: لا نقدر أن ننزل, وإنما إذا كان أخونا الصغير معنا ننزل, لأننا لا نقدر أن ننظر وجه الرجل وأخونا الصغير ليس معنا.","44:27":"فقال لنا عبدك أبي: أنتم تعلمون أن امرأتي ولدت لي اثنين,","44:28":"فخرج الواحد من عندي, وقلت: إنما هو قد افترس افتراسا, ولم أنظره إلى الآن.","44:29":"فإذا أخذتم هذا أيضا من أمام وجهي وأصابته أذية, تنزلون شيبتي بشر إلى الهاوية.","44:30":"فالآن متى جئت إلى عبدك أبي, والغلام ليس معنا, ونفسه مرتبطة بنفسه,","44:31":"يكون متى رأى أن الغلام مفقود, أنه يموت, فينزل عبيدك شيبة عبدك أبينا بحزن إلى الهاوية,","44:32":"لأن عبدك ضمن الغلام لأبي قائلا: إن لم أجئ به إليك أصر مذنبا إلى أبي كل الأيام.","44:33":"فالآن ليمكث عبدك عوضا عن الغلام, عبدا لسيدي, ويصعد الغلام مع إخوته.","44:34":"لأني كيف أصعد إلى أبي والغلام ليس معي؟ لئلا أنظر الشر الذي يصيب أبي».","45:1":"فلم يستطع يوسف أن يضبط نفسه لدى جميع الواقفين عنده فصرخ: «أخرجوا كل إنسان عني». فلم يقف أحد عنده حين عرف يوسف إخوته بنفسه.","45:2":"فأطلق صوته بالبكاء, فسمع المصريون وسمع بيت فرعون.","45:3":"وقال يوسف لإخوته: «أنا يوسف. أحي أبي بعد؟» فلم يستطع إخوته أن يجيبوه, لأنهم ارتاعوا منه.","45:4":"فقال يوسف لإخوته: «تقدموا إلي». فتقدموا. فقال: «أنا يوسف أخوكم الذي بعتموه إلى مصر.","45:5":"والآن لا تتأسفوا ولا تغتاظوا لأنكم بعتموني إلى هنا, لأنه لاستبقاء حياة أرسلني الله قدامكم.","45:6":"لأن للجوع في الأرض الآن سنتين. وخمس سنين أيضا لا تكون فيها فلاحة ولا حصاد.","45:7":"فقد أرسلني الله قدامكم ليجعل لكم بقية في الأرض وليستبقي لكم نجاة عظيمة.","45:8":"فالآن ليس أنتم أرسلتموني إلى هنا بل الله. وهو قد جعلني أبا لفرعون وسيدا لكل بيته ومتسلطا على كل أرض مصر.","45:9":"أسرعوا واصعدوا إلى أبي وقولوا له: هكذا يقول ابنك يوسف: قد جعلني الله سيدا لكل مصر. انزل إلي. لا تقف.","45:10":"فتسكن في أرض جاسان وتكون قريبا مني, أنت وبنوك وبنو بنيك وغنمك وبقرك وكل ما لك.","45:11":"وأعولك هناك, لأنه يكون أيضا خمس سنين جوعا. لئلا تفتقر أنت وبيتك وكل ما لك.","45:12":"وهوذا عيونكم ترى, وعينا أخي بنيامين, أن فمي هو الذي يكلمكم.","45:13":"وتخبرون أبي بكل مجدي في مصر وبكل ما رأيتم, وتستعجلون وتنزلون بأبي إلى هنا».","45:14":"ثم وقع على عنق بنيامين أخيه وبكى, وبكى بنيامين على عنقه.","45:15":"وقبل جميع إخوته وبكى عليهم. وبعد ذلك تكلم إخوته معه.","45:16":"وسمع الخبر في بيت فرعون, وقيل: «جاء إخوة يوسف». فحسن في عيني فرعون وفي عيون عبيده.","45:17":"فقال فرعون ليوسف: «قل لإخوتك: افعلوا هذا: حملوا دوابكم وانطلقوا, اذهبوا إلى أرض كنعان.","45:18":"وخذوا أباكم وبيوتكم وتعالوا إلي, فأعطيكم خيرات أرض مصر وتأكلوا دسم الأرض.","45:19":"فأنت قد أمرت, افعلوا هذا: خذوا لكم من أرض مصر عجلات لأولادكم ونسائكم, واحملوا أباكم وتعالوا.","45:20":"ولا تحزن عيونكم على أثاثكم, لأن خيرات جميع أرض مصر لكم».","45:21":"ففعل بنو إسرائيل هكذا. وأعطاهم يوسف عجلات بحسب أمر فرعون, وأعطاهم زادا للطريق.","45:22":"وأعطى كل واحد منهم حلل ثياب, وأما بنيامين فأعطاه ثلاث مئة من الفضة وخمس حلل ثياب.","45:23":"وأرسل لأبيه هكذا: عشرة حمير حاملة من خيرات مصر, وعشر أتن حاملة حنطة, وخبزا وطعاما لأبيه لأجل الطريق.","45:24":"ثم صرف إخوته فانطلقوا, وقال لهم: «لا تتغاضبوا في الطريق».","45:25":"فصعدوا من مصر وجاءوا إلى أرض كنعان, إلى يعقوب أبيهم.","45:26":"وأخبروه قائلين: «يوسف حي بعد, وهو متسلط على كل أرض مصر». فجمد قلبه لأنه لم يصدقهم.","45:27":"ثم كلموه بكل كلام يوسف الذي كلمهم به, وأبصر العجلات التي أرسلها يوسف لتحمله. فعاشت روح يعقوب أبيهم.","45:28":"فقال إسرائيل: «كفى! يوسف ابني حي بعد. أذهب وأراه قبل أن أموت».","46:1":"فارتحل إسرائيل وكل ما كان له وأتى إلى بئر سبع, وذبح ذبائح لإله أبيه إسحاق.","46:2":"فكلم الله إسرائيل في رؤى الليل وقال: «يعقوب, يعقوب!». فقال: «هأنذا».","46:3":"فقال: «أنا الله, إله أبيك. لا تخف من النزول إلى مصر, لأني أجعلك أمة عظيمة هناك.","46:4":"أنا أنزل معك إلى مصر, وأنا أصعدك أيضا. ويضع يوسف يده على عينيك».","46:5":"فقام يعقوب من بئر سبع, وحمل بنو إسرائيل يعقوب أباهم وأولادهم ونساءهم في العجلات التي أرسل فرعون لحمله.","46:6":"وأخذوا مواشيهم ومقتناهم الذي اقتنوا في أرض كنعان, وجاءوا إلى مصر. يعقوب وكل نسله معه.","46:7":"بنوه وبنو بنيه معه, وبناته وبنات بنيه وكل نسله, جاء بهم معه إلى مصر.","46:8":"وهذه أسماء بني إسرائيل الذين جاءوا إلى مصر: يعقوب وبنوه. بكر يعقوب رأوبين.","46:9":"وبنو رأوبين: حنوك وفلو وحصرون وكرمي.","46:10":"وبنو شمعون: يموئيل ويامين وأوهد وياكين وصوحر وشأول ابن الكنعانية.","46:11":"وبنو لاوي: جرشون وقهات ومراري.","46:12":"وبنو يهوذا: عير وأونان وشيلة وفارص وزارح. وأما عير وأونان فماتا في أرض كنعان. وكان ابنا فارص: حصرون وحامول.","46:13":"وبنو يساكر: تولاع وفوة ويوب وشمرون.","46:14":"وبنو زبولون: سارد وإيلون وياحلئيل.","46:15":"هؤلاء بنو ليئة الذين ولدتهم ليعقوب في فدان أرام مع دينة ابنته. جميع نفوس بنيه وبناته ثلاث وثلاثون.","46:16":"وبنو جاد: صفيون وحجي وشوني وأصبون وعيري وأرودي وأرئيلي.","46:17":"وبنو أشير: يمنة ويشوة ويشوي وبريعة, وسارح هي أختهم. وابنا بريعة: حابر وملكيئيل.","46:18":"هؤلاء بنو زلفة التي أعطاها لابان لليئة ابنته, فولدت هؤلاء ليعقوب, ست عشرة نفسا.","46:19":"ابنا راحيل امرأة يعقوب: يوسف وبنيامين.","46:20":"وولد ليوسف في أرض مصر: منسى وأفرايم, اللذان ولدتهما له أسنات بنت فوطي فارع كاهن أون.","46:21":"وبنو بنيامين: بالع وباكر وأشبيل وجيرا ونعمان وإيحي وروش ومفيم وحفيم وأرد.","46:22":"هؤلاء بنو راحيل الذين ولدوا ليعقوب. جميع النفوس أربع عشرة.","46:23":"وابن دان: حوشيم.","46:24":"وبنو نفتالي: ياحصئيل وجوني ويصر وشليم.","46:25":"هؤلاء بنو بلهة التي أعطاها لابان لراحيل ابنته. فولدت هؤلاء ليعقوب. جميع الأنفس سبع.","46:26":"جميع النفوس ليعقوب التي أتت إلى مصر, الخارجة من صلبه, ما عدا نساء بني يعقوب, جميع النفوس ست وستون نفسا.","46:27":"وابنا يوسف اللذان ولدا له في مصر نفسان. جميع نفوس بيت يعقوب التي جاءت إلى مصر سبعون.","46:28":"فأرسل يهوذا أمامه إلى يوسف ليري الطريق أمامه إلى جاسان, ثم جاءوا إلى أرض جاسان.","46:29":"فشد يوسف مركبته وصعد لاستقبال إسرائيل أبيه إلى جاسان. ولما ظهر له وقع على عنقه وبكى على عنقه زمانا.","46:30":"فقال إسرائيل ليوسف: «أموت الآن بعد ما رأيت وجهك أنك حي بعد».","46:31":"ثم قال يوسف لإخوته ولبيت أبيه: «أصعد وأخبر فرعون وأقول له: إخوتي وبيت أبي الذين في أرض كنعان جاءوا إلي.","46:32":"والرجال رعاة غنم, فإنهم كانوا أهل مواش, وقد جاءوا بغنمهم وبقرهم وكل ما لهم.","46:33":"فيكون إذا دعاكم فرعون وقال: ما صناعتكم؟","46:34":"أن تقولوا: عبيدك أهل مواش منذ صبانا إلى الآن, نحن وآباؤنا جميعا. لكي تسكنوا في أرض جاسان. لأن كل راعي غنم رجس للمصريين».","47:1":"فأتى يوسف وأخبر فرعون وقال: «أبي وإخوتي وغنمهم وبقرهم وكل ما لهم جاءوا من أرض كنعان, وهوذا هم في أرض جاسان».","47:2":"وأخذ من جملة إخوته خمسة رجال وأوقفهم أمام فرعون.","47:3":"فقال فرعون لإخوته: «ما صناعتكم؟» فقالوا لفرعون: «عبيدك رعاة غنم نحن وآباؤنا جميعا».","47:4":"وقالوا لفرعون: «جئنا لنتغرب في الأرض, إذ ليس لغنم عبيدك مرعى, لأن الجوع شديد في أرض كنعان. فالآن ليسكن عبيدك في أرض جاسان».","47:5":"فكلم فرعون يوسف قائلا: «أبوك وإخوتك جاءوا إليك.","47:6":"أرض مصر قدامك. في أفضل الأرض أسكن أباك وإخوتك, ليسكنوا في أرض جاسان. وإن علمت أنه يوجد بينهم ذوو قدرة, فاجعلهم رؤساء مواش على التي لي»","47:7":"ثم أدخل يوسف يعقوب أباه وأوقفه أمام فرعون. وبارك يعقوب فرعون.","47:8":"فقال فرعون ليعقوب: «كم هي أيام سني حياتك؟»","47:9":"فقال يعقوب لفرعون: «أيام سني غربتي مئة وثلاثون سنة. قليلة و ردية كانت أيام سني حياتي, ولم تبلغ إلى أيام سني حياة آبائي في أيام غربتهم».","47:10":"وبارك يعقوب فرعون وخرج من لدن فرعون.","47:11":"فأسكن يوسف أباه وإخوته وأعطاهم ملكا في أرض مصر, في أفضل الأرض, في أرض رعمسيس كما أمر فرعون.","47:12":"وعال يوسف أباه وإخوته وكل بيت أبيه بطعام على حسب الأولاد.","47:13":"ولم يكن خبز في كل الأرض, لأن الجوع كان شديدا جدا. فخورت أرض مصر وأرض كنعان من أجل الجوع.","47:14":"فجمع يوسف كل الفضة الموجودة في أرض مصر وفي أرض كنعان بالقمح الذي اشتروا, وجاء يوسف بالفضة إلى بيت فرعون.","47:15":"فلما فرغت الفضة من أرض مصر ومن أرض كنعان أتى جميع المصريين إلى يوسف قائلين: «أعطنا خبزا, فلماذا نموت قدامك؟ لأن ليس فضة أيضا».","47:16":"فقال يوسف: «هاتوا مواشيكم فأعطيكم بمواشيكم, إن لم يكن فضة أيضا».","47:17":"فجاءوا بمواشيهم إلى يوسف, فأعطاهم يوسف خبزا بالخيل وبمواشي الغنم والبقر وبالحمير. فقاتهم بالخبز تلك السنة بدل جميع مواشيهم.","47:18":"ولما تمت تلك السنة أتوا إليه في السنة الثانية وقالوا له: «لا نخفي عن سيدي أنه إذ قد فرغت الفضة, ومواشي البهائم عند سيدي, لم يبق قدام سيدي إلا أجسادنا وأرضنا.","47:19":"لماذا نموت أمام عينيك نحن وأرضنا جميعا؟ اشترنا وأرضنا بالخبز, فنصير نحن وأرضنا عبيدا لفرعون, وأعط بذارا لنحيا ولا نموت ولا تصير أرضنا قفرا».","47:20":"فاشترى يوسف كل أرض مصر لفرعون, إذ باع المصريون كل واحد حقله, لأن الجوع اشتد عليهم. فصارت الأرض لفرعون.","47:21":"وأما الشعب فنقلهم إلى المدن من أقصى حد مصر إلى أقصاه.","47:22":"إلا إن أرض الكهنة لم يشترها, إذ كانت للكهنة فريضة من قبل فرعون, فأكلوا فريضتهم التي أعطاهم فرعون, لذلك لم يبيعوا أرضهم.","47:23":"فقال يوسف للشعب: «إني قد اشتريتكم اليوم وأرضكم لفرعون. هوذا لكم بذار فتزرعون الأرض.","47:24":"ويكون عند الغلة أنكم تعطون خمسا لفرعون, والأربعة الأجزاء تكون لكم بذارا للحقل, وطعاما لكم ولمن في بيوتكم, وطعاما لأولادكم».","47:25":"فقالوا: «أحييتنا. ليتنا نجد نعمة في عيني سيدي فنكون عبيدا لفرعون».","47:26":"فجعلها يوسف فرضا على أرض مصر إلى هذا اليوم: لفرعون الخمس. إلا إن أرض الكهنة وحدهم لم تصر لفرعون.","47:27":"وسكن إسرائيل في أرض مصر, في أرض جاسان, وتملكوا فيها وأثمروا وكثروا جدا.","47:28":"وعاش يعقوب في أرض مصر سبع عشرة سنة. فكانت أيام يعقوب, سنو حياته مئة وسبعا وأربعين سنة.","47:29":"ولما قربت أيام إسرائيل أن يموت دعا ابنه يوسف وقال له: «إن كنت قد وجدت نعمة في عينيك فضع يدك تحت فخذي واصنع معي معروفا وأمانة: لا تدفني في مصر,","47:30":"بل أضطجع مع آبائي, فتحملني من مصر وتدفنني في مقبرتهم». فقال: «أنا أفعل بحسب قولك».","47:31":"فقال: «احلف لي». فحلف له. فسجد إسرائيل على رأس السرير.","48:1":"وحدث بعد هذه الأمور أنه قيل ليوسف: «هوذا أبوك مريض». فأخذ معه ابنيه منسى وأفرايم.","48:2":"فأخبر يعقوب وقيل له: «هوذا ابنك يوسف قادم إليك». فتشدد إسرائيل وجلس على السرير.","48:3":"وقال يعقوب ليوسف: «الله القادر على كل شيء ظهر لي في لوز, في أرض كنعان, وباركني.","48:4":"وقال لي: ها أنا أجعلك مثمرا وأكثرك, وأجعلك جمهورا من الأمم, وأعطي نسلك هذه الأرض من بعدك ملكا أبديا.","48:5":"والآن ابناك المولودان لك في أرض مصر, قبلما أتيت إليك إلى مصر هما لي. أفرايم ومنسى كرأوبين وشمعون يكونان لي.","48:6":"وأما أولادك الذين تلد بعدهما فيكونون لك. على اسم أخويهم يسمون في نصيبهم.","48:7":"وأنا حين جئت من فدان ماتت عندي راحيل في أرض كنعان في الطريق, إذ بقيت مسافة من الأرض حتى آتي إلى أفراتة, فدفنتها هناك في طريق أفراتة, التي هي بيت لحم».","48:8":"ورأى إسرائيل ابني يوسف فقال: «من هذان؟».","48:9":"فقال يوسف لأبيه: «هما ابناي اللذان أعطاني الله ههنا». فقال: «قدمهما إلي لأباركهما».","48:10":"وأما عينا إسرائيل فكانتا قد ثقلتا من الشيخوخة, لا يقدر أن يبصر, فقربهما إليه فقبلهما واحتضنهما.","48:11":"وقال إسرائيل ليوسف: «لم أكن أظن أني أرى وجهك, وهوذا الله قد أراني نسلك أيضا».","48:12":"ثم أخرجهما يوسف من بين ركبتيه وسجد أمام وجهه إلى الأرض.","48:13":"وأخذ يوسف الاثنين أفرايم بيمينه عن يسار إسرائيل, ومنسى بيساره عن يمين إسرائيل وقربهما إليه.","48:14":"فمد إسرائيل يمينه ووضعها على رأس أفرايم وهو الصغير, ويساره على رأس منسى. وضع يديه بفطنة فإن منسى كان البكر.","48:15":"وبارك يوسف وقال: «الله الذي سار أمامه أبواي إبراهيم وإسحاق, الله الذي رعاني منذ وجودي إلى هذا اليوم,","48:16":"الملاك الذي خلصني من كل شر, يبارك الغلامين. وليدع عليهما اسمي واسم أبوي إبراهيم وإسحاق, وليكثرا كثيرا في الأرض».","48:17":"فلما رأى يوسف أن أباه وضع يده اليمنى على رأس أفرايم, ساء ذلك في عينيه, فأمسك بيد أبيه لينقلها عن رأس أفرايم إلى رأس منسى.","48:18":"وقال يوسف لأبيه: «ليس هكذا يا أبي, لأن هذا هو البكر. ضع يمينك على رأسه».","48:19":"فأبى أبوه وقال: «علمت يا ابني, علمت. هو أيضا يكون شعبا, وهو أيضا يصير كبيرا. ولكن أخاه الصغير يكون أكبر منه, ونسله يكون جمهورا من الأمم».","48:20":"وباركهما في ذلك اليوم قائلا: «بك يبارك إسرائيل قائلا: يجعلك الله كأفرايم وكمنسى». فقدم أفرايم على منسى.","48:21":"وقال إسرائيل ليوسف: «ها أنا أموت, ولكن الله سيكون معكم ويردكم إلى أرض آبائكم.","48:22":"وأنا قد وهبت لك سهما واحدا فوق إخوتك, أخذته من يد الأموريين بسيفي وقوسي».","49:1":"ودعا يعقوب بنيه وقال: «اجتمعوا لأنبئكم بما يصيبكم في آخر الأيام.","49:2":"اجتمعوا واسمعوا يا بني يعقوب, واصغوا إلى إسرائيل أبيكم:","49:3":"رأوبين, أنت بكري, قوتي وأول قدرتي, فضل الرفعة وفضل العز.","49:4":"فائرا كالماء لا تتفضل, لأنك صعدت على مضجع أبيك. حينئذ دنسته. على فراشي صعد.","49:5":"شمعون ولاوي أخوان, آلات ظلم سيوفهما.","49:6":"في مجلسهما لا تدخل نفسي. بمجمعهما لا تتحد كرامتي. لأنهما في غضبهما قتلا إنسانا, وفي رضاهما عرقبا ثورا.","49:7":"ملعون غضبهما فإنه شديد, وسخطهما فإنه قاس. أقسمهما في يعقوب, وأفرقهما في إسرائيل.","49:8":"يهوذا, إياك يحمد إخوتك, يدك على قفا أعدائك, يسجد لك بنو أبيك.","49:9":"يهوذا جرو أسد, من فريسة صعدت يا ابني, جثا وربض كأسد وكلبوة. من ينهضه؟","49:10":"لا يزول قضيب من يهوذا ومشترع من بين رجليه حتى يأتي شيلون وله يكون خضوع شعوب.","49:11":"رابطا بالكرمة جحشه, وبالجفنة ابن أتانه, غسل بالخمر لباسه, وبدم العنب ثوبه.","49:12":"مسود العينين من الخمر, ومبيض الأسنان من اللبن.","49:13":"زبولون, عند ساحل البحر يسكن, وهو عند ساحل السفن, وجانبه عند صيدون.","49:14":"يساكر, حمار جسيم رابض بين الحظائر.","49:15":"فرأى المحل أنه حسن, والأرض أنها نزهة, فأحنى كتفه للحمل وصار للجزية عبدا.","49:16":"دان, يدين شعبه كأحد أسباط إسرائيل.","49:17":"يكون دان حية على الطريق, أفعوانا على السبيل, يلسع عقبي الفرس فيسقط راكبه إلى الوراء.","49:18":"لخلاصك انتظرت يا رب.","49:19":"جاد, يزحمه جيش, ولكنه يزحم مؤخره.","49:20":"أشير, خبزه سمين وهو يعطي لذات ملوك.","49:21":"نفتالي, أيلة مسيبة يعطي أقوالا حسنة.","49:22":"يوسف, غصن شجرة مثمرة, غصن شجرة مثمرة على عين. أغصان قد ارتفعت فوق حائط.","49:23":"فمررته ورمته واضطهدته أرباب السهام.","49:24":"ولكن ثبتت بمتانة قوسه, وتشددت سواعد يديه. من يدي عزيز يعقوب, من هناك, من الراعي صخر إسرائيل,","49:25":"من إله أبيك الذي يعينك, ومن القادر على كل شيء الذي يباركك, تأتي بركات السماء من فوق, وبركات الغمر الرابض تحت. بركات الثديين والرحم.","49:26":"بركات أبيك فاقت على بركات أبوي. إلى منية الآكام الدهرية تكون على رأس يوسف, وعلى قمة نذير إخوته.","49:27":"بنيامين ذئب يفترس. في الصباح يأكل غنيمة, وعند المساء يقسم نهبا».","49:28":"جميع هؤلاء هم أسباط إسرائيل الاثنا عشر. وهذا ما كلمهم به أبوهم وباركهم. كل واحد بحسب بركته باركهم.","49:29":"وأوصاهم وقال لهم: «أنا أنضم إلى قومي. ادفنوني عند آبائي في المغارة التي في حقل عفرون الحثي.","49:30":"في المغارة التي في حقل المكفيلة, التي أمام ممرا في أرض كنعان, التي اشتراها إبراهيم مع الحقل من عفرون الحثي ملك قبر.","49:31":"هناك دفنوا إبراهيم وسارة امرأته. هناك دفنوا إسحاق ورفقة امرأته, وهناك دفنت ليئة.","49:32":"شراء الحقل والمغارة التي فيه كان من بني حث».","49:33":"ولما فرغ يعقوب من توصية بنيه ضم رجليه إلى السرير, وأسلم الروح وانضم إلى قومه.","50:1":"فوقع يوسف على وجه أبيه وبكى عليه وقبله.","50:2":"وأمر يوسف عبيده الأطباء أن يحنطوا أباه. فحنط الأطباء إسرائيل.","50:3":"وكمل له أربعون يوما, لأنه هكذا تكمل أيام المحنطين. وبكى عليه المصريون سبعين يوما.","50:4":"وبعد ما مضت أيام بكائه كلم يوسف بيت فرعون قائلا: «إن كنت قد وجدت نعمة في عيونكم, فتكلموا في مسامع فرعون قائلين:","50:5":"أبي استحلفني قائلا: ها أنا أموت. في قبري الذي حفرت لنفسي في أرض كنعان هناك تدفنني, فالآن أصعد لأدفن أبي وأرجع».","50:6":"فقال فرعون: «اصعد وادفن أباك كما استحلفك».","50:7":"فصعد يوسف ليدفن أباه, وصعد معه جميع عبيد فرعون, شيوخ بيته وجميع شيوخ أرض مصر,","50:8":"وكل بيت يوسف وإخوته وبيت أبيه, غير أنهم تركوا أولادهم وغنمهم وبقرهم في أرض جاسان.","50:9":"وصعد معه مركبات وفرسان, فكان الجيش كثيرا جدا.","50:10":"فأتوا إلى بيدر أطاد الذي في عبر الأردن وناحوا هناك نوحا عظيما وشديدا جدا, وصنع لأبيه مناحة سبعة أيام.","50:11":"فلما رأى أهل البلاد الكنعانيون المناحة في بيدر أطاد قالوا: «هذه مناحة ثقيلة للمصريين». لذلك دعي اسمه «آبل مصرايم». الذي في عبر الأردن.","50:12":"وفعل له بنوه هكذا كما أوصاهم:","50:13":"حمله بنوه إلى أرض كنعان ودفنوه في مغارة حقل المكفيلة, التي اشتراها إبراهيم مع الحقل ملك قبر من عفرون الحثي أمام ممرا.","50:14":"ثم رجع يوسف إلى مصر هو وإخوته وجميع الذين صعدوا معه لدفن أبيه بعد ما دفن أباه.","50:15":"ولما رأى إخوة يوسف أن أباهم قد مات, قالوا: «لعل يوسف يضطهدنا ويرد علينا جميع الشر الذي صنعنا به».","50:16":"فأوصوا إلى يوسف قائلين: «أبوك أوصى قبل موته قائلا:","50:17":"هكذا تقولون ليوسف: آه! اصفح عن ذنب إخوتك وخطيتهم, فإنهم صنعوا بك شرا. فالآن اصفح عن ذنب عبيد إله أبيك». فبكى يوسف حين كلموه.","50:18":"وأتى إخوته أيضا ووقعوا أمامه وقالوا: «ها نحن عبيدك».","50:19":"فقال لهم يوسف: «لا تخافوا. لأنه هل أنا مكان الله؟","50:20":"أنتم قصدتم لي شرا, أما الله فقصد به خيرا, لكي يفعل كما اليوم, ليحيي شعبا كثيرا.","50:21":"فالآن لا تخافوا. أنا أعولكم وأولادكم». فعزاهم وطيب قلوبهم.","50:22":"وسكن يوسف في مصر هو وبيت أبيه, وعاش يوسف مئة وعشر سنين.","50:23":"ورأى يوسف لأفرايم أولاد الجيل الثالث. وأولاد ماكير بن منسى أيضا ولدوا على ركبتي يوسف.","50:24":"وقال يوسف لإخوته: «أنا أموت, ولكن الله سيفتقدكم ويصعدكم من هذه الأرض إلى الأرض التي حلف لإبراهيم وإسحاق ويعقوب».","50:25":"واستحلف يوسف بني إسرائيل قائلا: «الله سيفتقدكم فتصعدون عظامي من هنا».","50:26":"ثم مات يوسف وهو ابن مئة وعشر سنين, فحنطوه ووضع في تابوت في مصر."};
